        Verse(book = "Jenèz", chapter = 1, verseNumber = 12, text = "Tè a pouse tout kalite plant: zèb, plant ki bay grenn, pyebwa ki bay fwi ak tout grenn yo. Bondye gade sa l' te fè a, li wè l' bon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 1, verseNumber = 13, text = "Yon lannwit pase, yon maten rive. Se te twazyèm jou a.", bookId = 1),
