        Verse(book = "Jenèz", chapter = 1, verseNumber = 19, text = "Yon lannwit pase, yon maten rive. Se te katriyèm jou a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 1, verseNumber = 20, text = "Bondye di ankò. Se pou dlo yo kale anpil anpil bèt vivan. Se pou zwazo vole nan syèl la anwo tè a. Se konsa sa te pase.", bookId = 1),
        Verse(book = "Jenèz", chapter = 1, verseNumber = 21, text = "Bondye kreye gwo bèt lanmè yo, tout kalite bèt vivan k'ap naje nan dlo ansanm ak tout kalite zwazo. Bondye gade sa l' te fè a, li wè l' bon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 1, verseNumber = 22, text = "Bondye beni yo, li di. Fè pitit, fè anpil anpil pitit, plen dlo lanmè a. Se pou zwazo yo fè anpil anpil pitit tout sou tè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 1, verseNumber = 23, text = "Yon lannwit pase, yon maten rive. Se te senkyèm jou a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 1, verseNumber = 24, text = "Bondye di ankò. Se pou tè a kale tout kalite bèt vivan, bèt yo gade, bèt ki trennen sou vant, bèt nan bwa. Se konsa sa te pase.", bookId = 1),
        Verse(book = "Jenèz", chapter = 1, verseNumber = 25, text = "Bondye fè tout kalite bèt, bèt nan bwa, bèt yo gade, bèt ki trennen sou vant. Li gade sa l' te fè a, li wè l' bon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 1, verseNumber = 26, text = "Bondye di ankò. Ann fè moun. N'ap fè l' pòtre ak nou, pou li sanble ak nou. La gen pouvwa sou pwason ki nan lanmè yo, sou zwazo ki nan syèl la, sou tout bèt yo gade, sou tout latè, sou tout bèt nan bwa, sou tout bèt ki trennen sou vant sou tè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 1, verseNumber = 27, text = "Bondye kreye moun. Li fè l' pòtre ak li. Li kreye yo gason ak fi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 1, verseNumber = 28, text = "Li ba yo benediksyon, li di. Fè pitit, fè anpil anpil pitit mete sou tè a. Donte tè a. Mwen ban nou pouvwa sou pwason ki nan lanmè, sou zwazo ki nan syèl la, ak sou tout bèt vivan k'ap mache sou tè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 1, verseNumber = 29, text = "Bondye di. Gade. Mwen ban nou tout kalite plant ki bay grenn ak tout kalite pyebwa ki bay fwi ak grenn pou nou manje.", bookId = 1),
        Verse(book = "Jenèz", chapter = 1, verseNumber = 30, text = "Men, tout bèt ki sou tè a, tout zwazo ki nan syèl la, tout bèt ki trennen sou vant, wi tout bèt vivan, m'ap ba yo zèb vèt pou yo manje. Se konsa sa te pase.", bookId = 1),
        Verse(book = "Jenèz", chapter = 1, verseNumber = 31, text = "Bondye gade sa l' te fè a, li wè l' bon nèt. Yon lannwit pase, yon maten rive. Se te sizyèm jou a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 1, text = "Konsa, Bondye te fin fè syèl la, latè a ansanm ak tout sa ki ladan yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 2, text = "Sou sis jou, Bondye te fin fè tout sa l' t'ap fè a. Setyèm jou a, li sispann travay.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 3, text = "Li beni setyèm jou a, li mete l' apa pou li, paske se jou sa a li te sispann travay apre li te fin kreye tout sa l' t'ap kreye a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 4, text = "Se konsa sa te pase lè Bondye t'ap kreye syèl la ak latè a. Lè Seyè a, Bondye a, t'ap fè latè ansanm ak tou sa ki nan syèl la,", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 5, text = "pa t' gen yon ti pyebwa sou tè a. Ankenn zèb pa t' ankò pouse nan jaden, paske Bondye pa t' voye lapli tonbe sou tè a. Lèfini, pa t' gen moun pou travay latè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 6, text = "Men, yon vapè dlo leve soti nan tè a, li wouze tout tè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 7, text = "Lè sa a, Seyè a, Bondye a, pran pousyè tè, li fè yon nonm. Li soufle nan twou nen nonm lan pou l' ba li lavi. Epi nonm lan vin vivan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 8, text = "Seyè a, Bondye a, plante yon jaden yon kote yo rele Edenn, bò kote solèy leve a. Se la li mete nonm li te fè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 9, text = "Seyè a, Bondye a, te fè tout kalite pyebwa leve nan jaden an, bèl pyebwa ki donnen fwi ki bon pou manje. Nan mitan jaden an te gen de gwo pyebwa. Yonn se te pyebwa ki bay lavi a, lòt la se te pyebwa ki fè moun konnen sa ki byen ak sa ki mal la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 10, text = "Yon gwo larivyè soti nan peyi Edenn, li wouze jaden an. Larivyè a te fè kat branch.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 11, text = "Premye branch lan te rele Pichon. Se larivyè sa a ki wouze tout peyi Avila a, peyi kote yo jwenn anpil lò a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 12, text = "Se nan peyi sa a yo jwenn pi bon lò ansanm ak pyebwa gonm arabik ak yon pyè wouj ki koute chè yo rele oniks.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 13, text = "Dezyèm larivyè a rele Giyon. Se li ki wouze tout peyi Kouch la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 14, text = "Twazyèm larivyè a rele Tig. Se li ki pase nan peyi Lasiri, sou bò solèy leve a. Katriyèm larivyè a se Lefrat.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 15, text = "Seyè a, Bondye a, pran nonm lan, li mete l' nan jaden Edenn lan pou l' travay li, pou l' pran swen l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 16, text = "Seyè a, Bondye a, bay nonm lan lòd sa a. Ou mèt manje donn tout pyebwa ki nan jaden an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 17, text = "Men, piga ou manje donn pyebwa ki fè moun konnen sa ki byen ak sa ki mal la. Paske, jou ou manje l', w'ap mouri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 18, text = "Seyè a, Bondye a, di ankò. Sa pa bon pou nonm lan rete pou kont li. M'ap fè yon lòt moun sanble avè l' pou ede l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 19, text = "Se konsa, Seyè a, Bondye a, pran pousyè tè, li fè tout kalite zannimo ki nan savann ak tout kalite zwazo k'ap vole nan syèl la. Lè l' fini, li mennen yo bay nonm lan pou wè ki non li tapral ba yo. Se non li te ba yo a ki rete pou yo nèt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 20, text = "Se konsa, nonm lan bay tout bèt yo gade, tout bèt nan bwa ak tout zwazo ki nan syèl la non yo. Men, pa t' gen yonn ki te sanble avè l', ki ta ka ede l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 21, text = "Lè sa a, Seyè a, Bondye a, fè dòmi pran nonm lan. Msye dòmi nèt ale. Pandan l'ap dòmi an, Bondye louvri bò kòt li, li wete yon zo kòt. Apre sa, li fèmen twou a byen fèmen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 22, text = "Avèk zo kòt li te wete nan nonm lan, li fè yon fanm, li mennen l' ba li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 23, text = "Lè nonm lan wè l', li di. Aa! Fwa sa a, men yonn ki menm jan avè m'! Zo l' se zo mwen. Chè l' se chè mwen. Y'a rele l' fanm, paske se nan gason li soti.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 24, text = "Se poutèt sa, gason an va kite papa l' ak manman l' pou l' mete tèt li ansanm ak madanm li, pou tout de fè yon sèl.", bookId = 1),
        Verse(book = "Jenèz", chapter = 2, verseNumber = 25, text = "Nonm lan ak madanm li te toutouni. Men, yo pa t' wont rete konsa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 1, text = "Sèpan se bèt ki te pi rize nan tout bèt raje Seyè a, Bondye a, te kreye. Li di fanm lan konsa. Eske Bondye te janm di piga nou manje donn tout pyebwa ki nan jaden an?", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 2, text = "Fanm lan reponn sèpan an. Nou gen dwa manje donn tout pyebwa ki nan jaden an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 3, text = "Men, kanta pou pyebwa ki nan mitan jaden an, Bondye di. Piga nou manje ladan l', piga nou manyen l' menm. Sinon, n'ap mouri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 4, text = "Lè sa a, sèpan an di fanm lan. Se pa vre. Nou p'ap mouri kras.", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 5, text = "Bondye di nou sa paske li konnen jou nou manje ladan l', je nou va louvri. n'a vin tankou Bondye, n'a konn sa ki byen ak sa ki mal.", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 6, text = "Fanm lan gade, li wè jan pyebwa a te bèl, jan fwi yo sanble yo ta bon nan bouch. Li santi li ta manje ladan l' pou je l' ka louvri. Li keyi kèk fwi. Li manje, li pote bay mari l' ki manje tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 7, text = "Manje yo fin manje, je yo louvri, lè sa a, yo vin konnen yo toutouni. Yo pran kèk fèy figfrans, yo koud yo ansanm, yo fè tanga mete sou yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 8, text = "Jou sa a, solèy te fèk fin kouche lè nonm lan ak madanm li tande vwa Seyè a, Bondye a, ki t'ap pwonmennen nan jaden an. Y' al kache nan mitan pyebwa ki nan jaden an pou Seyè a, Bondye a, pa wè yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 9, text = "Men, Seyè a, Bondye a, rele nonm lan, li di l'. Kote ou ye?", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 10, text = "Nonm lan reponn li. Mwen tande vwa ou nan jaden an, mwen pè. M al kache pou ou, paske mwen toutouni.", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 11, text = "Seyè a, Bondye a, di l'. Ki moun ki di ou te toutouni? Eske ou te manje fwi pyebwa mwen te di ou pa manje a?", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 12, text = "Nonm lan reponn. Fanm ou te ban mwen an, se li menm ki ban mwen fwi pyebwa a pou m' manje, epi mwen manje l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 13, text = "Seyè a, Bondye a, mande fanm lan. Poukisa ou fè sa? Fanm lan reponn li. Se pa mwen non! Se sèpan an wi ki pran tèt mwen ki fè m' manje l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 14, text = "Seyè a, Bondye a, di sèpan an konsa. Poutèt sa ou fè a, ou madichonnen nan mitan tout bèt jaden ak tout bèt nan bwa. W'a rale sou vant ou. W'a manje pousyè tè jouk jou ou mouri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 15, text = "Ou menm ak fanm lan, m'ap fè nou lènmi yonn ak lòt. Pitit pitit pa l' ak pitit pitit pa ou ap lènmi tou. Pitit pitit li ap kraze tèt ou, epi ou menm w'ap mòde l' nan talon pye l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 16, text = "Li di fanm lan. Lè w'ap fè pitit, m'ap fè soufrans ou vin pi rèd. Wa gen pou soufri anpil lè w'ap akouche. W'ap toujou anvi mari ou. Men, se mari ou ki va chèf ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 17, text = "Apre sa li di Adan. Ou koute pawòl madanm ou, pa vre! Ou manje fwi pyebwa mwen te ba ou lòd pa manje a. Poutèt sa ou fè a, m'ap madichonnen tè a. W'a gen pou travay di toutan pou fè tè a bay sa ou bezwen pou viv.", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 18, text = "Tè a va kale tout kalite pikan ak pengwen ba ou. W'a manje fèy ki pouse nan raje.", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 19, text = "Se swe kouraj ou ki pou fè ou mete yon moso pen nan bouch ou jouk lè wa tounen nan tè kote ou soti a. Paske, se pousyè ou ye, ou gen pou tounen pousyè ankò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 20, text = "Adan bay madanm li non, li rele l' Ev, paske se li menm ki manman tout moun k'ap viv sou tè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 21, text = "Lè sa a, Seyè a, Bondye a, pran po bèt, li fè rad pou Adan ansanm ak madanm li, li biye yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 22, text = "Apre sa, Seyè a, Bondye a, di. Koulye a, Adan vin konnen sa ki byen ak sa ki mal tankou yonn nan nou. Nou p'ap kite l' lonje men l' keyi fwi pyebwa ki bay lavi a pou l' manje l', pou l' pa viv pou tout tan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 23, text = "Se konsa, Seyè a, Bondye a, mete Adan deyò nan jaden Edenn lan. Li voye l' al travay tè, menm tè Bondye te pran pou fè l' la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 3, verseNumber = 24, text = "Se konsa, li te mete Adan deyò. Sou bò kote solèy leve nan jaden an, li mete kèk zanj cheriben ak yon manchèt klere kou dife nan men yo. Yo t'ap dragonnen nan tout direksyon pou anpeche moun pwoche bò pyebwa ki bay lavi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 1, text = "Lè sa a, Adan kouche ak Ev, madanm li. Madanm li vin ansent. Li fè yon pitit gason, li rele l' Kayen, epi li di. Avèk konkou Bondye, mwen gen yon gason.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 2, text = "Apre sa, li fè Abèl, frè Kayen. Abèl te gadò mouton, Kayen menm te travay latè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 3, text = "Kèk tan apre sa, Kayen pran nan rekòt li, li ofri bay Seye a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 4, text = "Abèl menm, bò pa l', pran sa ki pi gra nan premye pitit mouton l' yo, li ofri bay Seyè a. Seyè a te kontan ofrann Abèl la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 5, text = "Men, li pa t' asepte ofrann Kayen an. Lè Kayen wè sa, li te move anpil. Li move, li mare figi l' byen mare.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 6, text = "Lè sa a, Seyè a di Kayen. Poukisa ou move konsa? Poukisa ou mare figi ou konsa?", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 7, text = "Si sa ou te fè a te byen, ou pa ta rive nan sitiyasyon sa a. Men, paske ou fè sa ki mal, peche kouche nan papòt ou. L'ap tann konsa lè pou l' pran tèt ou. Men, ou menm, se pou ou kenbe tèt ak li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 8, text = "Yon jou, Kayen di Abèl, frè li. Ann al nan jaden. Vwala, antan yo nan jaden an, Kayen vire sou frè li, li touye li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 9, text = "Seyè a mande Kayen. Kote Abèl, frè ou la? Kayen reponn. Mwen pa konnen. Eske ou te mete m' veye l'?", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 10, text = "Bondye di l' konsa. Kisa ou fè konsa? San Abèl, frè ou, ki koule atè a, ap rele tankou yon vwa moun. Li rive jouk nan zòrèy mwen. L'ap mande revanj.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 11, text = "Koulye a, tè ki te louvri bouch li pou l' te bwè san frè ou ou te fè koule a, menm tè sa a ap tounen yon madichon pou ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 12, text = "Lè w'a travay latè, li p'ap ba ou sa l' te dwe ba ou. W'ap tounen yon vakabon k'ap plede mache toupatou sou latè san rete.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 13, text = "Kayen di Seyè a: Chatiman an twòp pou mwen. Mwen p'ap ka sipòte l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 14, text = "Men ou mete m' deyò sou tè sa a koulye a, se kache pou m' al kache pou ou pa wè m'. M'ap tounen yon vakabon k'ap plede mache toupatou sou latè san rete. Nenpòt moun ki jwenn mwen va touye m'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 15, text = "Seyè a di: Non. Paske, si yon moun touye Kayen, y'ap fè l' peye sa sèt fwa. Se konsa, li mete yon siy sou Kayen pou moun pa touye l' si yo jwenn li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 16, text = "Apre sa, Kayen wete kò l' devan Seyè a, li al rete nan yon peyi yo rele Nòd, lòt bò jaden Edenn lan, sou kote solèy leve a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 17, text = "Kayen kouche avèk madanm li. Madanm li vin ansent, li fè yon ti gason yo rele Enòk. Apre sa, Kayen bati yon vil, li rele l' Enòk. Li ba l' menm non ak pitit gason l' lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 18, text = "Enòk te fè yon pitit gason yo rele Irad. Se Irad sa a ki te papa Meoujaèl. Meoujaèl te papa Metouchaèl. Se Metouchaèl ki te papa Lemèk.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 19, text = "Lemèk te gen de madanm. Yonn te rele Ada, lòt la te rele Zila.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 20, text = "Se Ada ki manman Jabal. Jabal sa a, se li menm ki zansèt tout moun sa yo ki rete anba tant epi ki gade bèt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 21, text = "Frè menm manman ak li a te rele Joubal. Se li menm ki zansèt tout moun sa yo k'ap jwe gita ak fif.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 22, text = "Zila menm bò pa l' te manman Toubal Kayen, yon bòs fòjon ki te konn travay kwiv ak fè. Toubal Kayen te gen yon sè menm manman ak li ki te rele Naama.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 23, text = "Yon jou Lemèk di madanm li yo: Ada ak Zila, koute sa m'ap di nou! Madanm mwen yo, tande byen sa m'ap di nou! Mwen touye yon moun paske li leve men li sou mwen. Mwen touye yon jenn gason paske li mete san m' deyò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 24, text = "Si yon moun touye Kayen y'ap fè l' peye sa sèt fwa. Men, si yon moun touye m', mwen menm Lemèk, y'ap fè l' peye sa swasanndisèt fwa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 25, text = "Adan te kouche ak madanm li ankò. Madanm li fè yon ti gason. Madanm lan di: Bondye ban m' yon lòt gason pou ranplase Abèl Kayen te touye a. Li rele l' Sèt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 4, verseNumber = 26, text = "Sèt, pou tèt pa l', vin gen yon pitit gason, li rele l' Enòk. Se lè sa a moun konmanse fè sèvis pou Seyè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 1, text = "Men lis non pitit pitit Adan yo: Lè Bondye kreye moun, li te fè yo pòtre avè l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 2, text = "Li kreye yo gason ak fi. Li beni yo. Jou li kreye yo a, li rele yo moun.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 3, text = "Adan te gen santrantan (130 an) lè li vin gen yon pitit gason ki te sanble avè l' tèt koupe, li rele l' Sèt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 4, text = "Apre nesans Sèt, Adan viv witsanzan (800 an). Li te vin gen anpil lòt pitit gason ak pitit fi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 5, text = "Lè Adan mouri li te gen nèfsantrantan (930 an).", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 6, text = "Sèt te gen sansenkan (105 an) lè li vin gen yon pitit gason yo te rele Enòk.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 7, text = "Apre nesans Enòk, Sèt viv witsansetan (807 an). Li te vin gen anpil lòt pitit gason ak pitit fi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 8, text = "Lè Sèt mouri, li te gen nèfsandouzan (912 an).", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 9, text = "Enòk te gen katrevendizan lè li vin gen yon pitit gason yo rele Kenan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 10, text = "Apre nesans Kenan, Enòk viv witsankenzan (815 an). Li te vin gen anpil lòt pitit gason ak pitit fi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 11, text = "Lè Enòk mouri, li te gen nèfsansenkan (905 an).", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 12, text = "Kenan te gen swasanndizan lè li vin gen yon pitit gason yo rele Malaleyèl.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 13, text = "Apre nesans Malaleyèl, Kenan viv witsankarantan (840 an). Li te vin gen anpil lòt pitit gason ak pitit fi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 14, text = "Lè Kenan mouri, li te gen nèfsandizan (910 an).", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 15, text = "Malaleyèl te gen swasannsenkan lè li vin gen yon pitit gason yo rele Jerèd.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 16, text = "Apre nesans Jerèd, Malaleyèl viv witsantrantan (830 an). Li te vin gen anpil lòt pitit gason ak pitit fi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 17, text = "Lè Malaleyèl mouri, li te gen witsankatrevenkenzan (895 an).", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 18, text = "Jerèd te gen sanswanndezan (162 an) lè li vin gen yon pitit gason yo rele Enòk.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 19, text = "Apre nesans Enòk, Jerèd viv witsanzan (800 an). Li te vin gen anpil lòt pitit gason ak pitit fi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 20, text = "Lè Jerèd mouri, li te gen nèfsanswasanndezan (962 an).", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 21, text = "Enòk te gen swasannsenkan lè li vin gen yon pitit gason yo rele Metouchela.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 22, text = "Apre nesans Metouchela, Enòk te mache byen ak Bondye pandan twasanzan (300 an). Li te vin gen anpil lòt pitit gason ak pitit fi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 23, text = "-", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 24, text = "Enòk te pase tout vi l' ap mache byen ak Bondye. Li te gen twasanswasannsenkan (365 an) lè l' disparèt, paske Bondye te pran l' avè l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 25, text = "Metouchela te gen sankatrevensètan (187 an) lè li vin gen yon pitit gason yo rele Lemèk.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 26, text = "Apre nesans Lemèk, Metouchela viv sètsankatrevendezan (782 an). Li te vin gen anpil lòt pitit gason ak pitit fi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 27, text = "Lè Metouchela mouri, li te gen nèfsanswantnevan (969 an).", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 28, text = "Lemèk te gen sankatrevendezan (182 an) lè li vin gen yon pitit gason.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 29, text = "Li rele l' Noe. Li di konsa: Pitit sa a va soulaje nou anba tout travay di n'ap fè, anba gwo travay nou blije fè avèk men nou paske Seyè a te madichonnen tè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 30, text = "Apre nesans Noe, Lemèk viv senksankatrevenkenzan (595 an). Li te vin gen anpil lòt pitit gason ak pitit fi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 31, text = "Lè Lemèk mouri, li te gen sètsanswasanndisetan (777 an).", bookId = 1),
        Verse(book = "Jenèz", chapter = 5, verseNumber = 32, text = "Noe te gen senksanzan (500 an) lè li vin gen twa pitit gason: Sèm, Kam ak Jafè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 1, text = "Lè sa a, moun te konmanse ap fè anpil anpil pitit sou latè. Yo te vin gen anpil pitit fi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 2, text = "Pitit gason Bondye yo te wè jan pitit fi lèzòm yo te bèl. Se konsa, nan fi yo te renmen yo, yo pran ladan yo pou madanm yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 3, text = "Lè Seyè a wè sa, li di: Mwen p'ap kite lèzòm viv pou tout tan, paske se moun ase yo ye. Se sanventan (120 an) sèlman pou yo viv.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 4, text = "Lè sa a, epi pandan lontan apre sa, te vin gen sou latè yon ras moun wo anpil: se te pitit pitit fi lèzòm yo te fè pou pitit gason bondye yo. Se yo ki te vanyan gason nan tan lontan yo, kifè tout moun t'ap nonmen non yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 5, text = "Seyè a wè jan lèzòm te mechan toupatou sou latè, ki jan tout lajounen se move lide ase ki te nan tèt yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 6, text = "Li vin règrèt li te fè moun sou latè. Kè l' vin sere ak lapenn.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 7, text = "Seyè a di: Mwen pral disparèt tout moun mwen te kreye yo, san kite yonn. Epi m'ap detwi ansanm ak yo tout tou bèt kat pat, tout bèt ki trennen sou vant ak tout zwazo k'ap vole nan syèl, paske mwen règrèt anpil dèske mwen te fè yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 8, text = "Men, Noe te fè Bondye plezi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 9, text = "Men pitit pitit Noe yo. Nan tout moun ki t'ap viv lè sa a, Noe te sèl moun ki t'ap mache dwat devan Bondye, ki pa t' nan anyen ki mal. Li t'ap mache byen ak Bondye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 10, text = "Li te gen twa pitit gason: Sèm, Kam ak Jafè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 11, text = "Men, tout lòt moun yo te fin pouri devan Bondye. Toupatou sou latè se te mechanste sou mechanste.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 12, text = "Bondye gade latè, li wè l' te fin pouri, paske tout moun sou latè te fin pèvèti.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 13, text = "Lè sa a, Bondye di Noe konsa: Mwen deside pou m' fini ak tout moun, paske se yo ki lakòz toupatou sou latè se mechanste ase. Wi, mwen pral detwi yo nèt ansanm ak tout sa ki sou latè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 14, text = "Fè yon gwo batiman pou ou ak bwa pichpen. W'a fè anpil ti chanm ladan l'. W'a badijonnen l' byen badijonnen anndan kou deyò avèk goudwon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 15, text = "Men ki jan pou ou fè l': Batiman an va gen katsansenkant (450) pye longè, swasannkenz pye lajè, ak karannsenk pye wotè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 16, text = "W'a mete yon twati sou batiman an. W'a kite yon espas dizwit pous ant twati a ak rebò a. W'a louvri yon sèl pòt sou kote batiman an. W'a mete yon etaj anba, yon etaj nan mitan, yon etaj anwo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 17, text = "Mwen pral voye yon gwo inondasyon dlo sou latè pou detwi tout sa k'ap viv anba syèl la. tout sa ki sou latè pral peri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 18, text = "Men, m'ap fè yon kontra avè ou. W'a antre nan batiman an, ou menm, pitit gason ou yo, madanm ou ansanm ak madanm pitit ou yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 19, text = "W'a pran avèk ou tout yon pè nan tout kalite bèt, yon mal ak yon fenmèl. Wa fè yo antre nan batiman an ansanm ak ou pou yo pa mouri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 20, text = "Konsa, nan tout kalite zwazo, nan tout kalite bèt domestik, nan tout kalite bèt ki trennen sou vant yo, gen yon pè nan chak kalite ki va vin jwenn ou pou yo pa mouri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 21, text = "Ou menm bò pa ou, ranmase tout kalite manje, mezi ou kapab. Fè yon bèl pwovizyon mete la pou ou ka jwenn manje pou ou manje ansanm ak tout bèt yo tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 6, verseNumber = 22, text = "Se konsa Noe fè tout sa Bondye te ba li lòd fè a. Wi, se sa menm li te fè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 1, text = "Seyè a di Noe: Antre nan gwo batiman an, ou menm ansanm ak tout fanmi ou, paske, nan tout moun k'ap viv koulye la a, se ou menm sèl mwen wè k'ap mache dwat devan mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 2, text = "Nan tout bèt ki bon pou moun manje, w'a pran sèt mal ak sèt fenmèl nan chak kalite. Nan tout bèt ki pa bon pou moun manje, w'a pran yon mal ak yon fenmèl nan chak kalite.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 3, text = "Konsa tou, pou zwazo k'ap vole nan syèl la, w'a pran sèt mal ak sèt fenmèl nan chak kalite, pou ras la pa disparèt sou latè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 4, text = "Paske, nan sèt jou ankò, m'ap fè yon sèl lapli tonbe sou latè pandan karant jou karant nwit. M'ap disparèt tout moun ak tout bèt mwen te fè mete sou latè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 5, text = "Noe fè tout sa Seyè a te ba li lòd fè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 6, text = "Noe te gen sisanzan (600 an) lè inondasyon an te fèt sou latè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 7, text = "Li antre nan batiman an, li menm, pitit gason li yo, madanm li ansanm ak madanm pitit li yo pou yo te ka chape anba inondasyon an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 8, text = "tout kalite bèt, kit sa ki bon pou moun manje, kit sa ki pa bon pou moun manje, tout zwazo, tout bèt ki trennen sou vant,", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 9, text = "yo tout yo vin jwenn Noe nan batiman an, de pa de, mal ak fenmèl, jan Bondye te bay Noe lòd la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 10, text = "Sou sèt jou vre, dlo kouvri tout latè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 11, text = "Jou ki fè Noe sisanzan (600 an), yon mwa, disèt jou, tout sous nan fon lanmè a pete. Syèl la menm louvri, li konmanse vide dlo sou tè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 12, text = "Lapli tonbe san rete pandan karant jou karant nwit.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 13, text = "Menm jou sa a, Noe, madanm li, pitit gason l' yo, Sèm, Kam ak Jafè, ansanm ak madanm yo antre nan batiman an,", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 14, text = "ansanm ak tout kalite bèt domestik, tout kalite bèt ki trennen sou vant ak tout kalite zwazo, tout kalite ti zwazo, tout kalite bèt ki gen zèl.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 15, text = "Yo tout yo te vin jwenn Noe nan batiman an, de grenn nan chak kalite bèt vivan ki sou latè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 16, text = "Se konsa, yon mal ak yon fenmèl nan chak kalite bèt vivan antre nan batiman an, jan Bondye te bay lòd la. Epi Bondye fèmen pòt la dèyè Noe.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 17, text = "Pandan karant jou, dlo kouvri tout tè a. Dlo yo gonfle, yo fè batiman an pèdi tè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 18, text = "Dlo yo ranfòse, yo gonfle pi rèd sou tè a jouk batiman an t'ap flote nèt sou dlo a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 19, text = "Dlo a moute pi rèd toujou anwo tè a, li kouvri tèt tout gwo mòn ki anba syèl la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 20, text = "Dlo a moute vennsenk pye depase tèt mòn yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 21, text = "Lè sa a, tout bèt sou latè mouri: zwazo, bèt domestik, zannimo, tout bèt ki trennen sou vant yo, ansanm ak tout moun.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 22, text = "tout bèt vivan ak tout moun sou latè mouri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 23, text = "Se konsa, Seyè a detwi tout bèt, tout sa ki te sou latè, depi ou tande se moun jouk zannimo domestik, bèt ki trennen sou vant ak zwazo k'ap vole nan syèl la. Yo tout yo disparèt sou latè. Sèl moun ki te rete se te Noe avèk lòt moun ki te nan batiman an ansanm ak li yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 7, verseNumber = 24, text = "Apre sa, dlo a rete anwo tè a pandan sansenkant (150) jou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 1, text = "Men, Bondye vin chonje Noe ansanm ak tout bèt bwa ak zannimo domestik ki te avè l' nan batiman an. Bondye fè yon van soufle sou latè, epi dlo yo konmanse bese.", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 2, text = "Sous dlo ki nan fon lanmè a te sispann bay dlo. Syèl la sispann bay dlo tou. Lapli sispann tonbe.", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 3, text = "Dlo yo menm t'ap bese, yo t'ap bese piti piti. Se sou sansenkant (150) jou dlo yo te konmanse bese.", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 4, text = "Sou sis mwa disèt jou, batiman an fè tè sou tèt mòn Arara yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 5, text = "Dlo yo t'ap bese toujou jouk sou dizyèm mwa a. Sou premye jou dizyèm mwa a, tèt mòn yo parèt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 6, text = "Karant jou apre sa, Noe louvri fennèt li te fè nan batiman an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 7, text = "Li lage yon kònèy. Kònèy la soti. li ale vini, li ale vini jouk dlo a te fin cheche nèt sou latè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 8, text = "Apre sa, li lage yon pijon, pou l' wè si dlo a te fin bese sou tè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 9, text = "Men, pijon an pa t' jwenn kote pou l' poze. Li tounen vin jwenn Noe nan batiman an, paske te gen dlo sou tout latè toujou. Noe lonje men l', li pran pijon an, li fè l' antre nan batiman an ankò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 10, text = "Li tann sèt jou pase. Apre sa, li lage pijon an yon dezyèm fwa, li fè l' soti nan batiman an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 11, text = "Vè aswè konsa, pijon an tounen vin jwenn li. Men, fwa sa a, li te gen yon fèy oliv tout vèt nan bèk li. Konsa, Noe vin konnen dlo a te bese sou tout latè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 12, text = "Li tann sèt jou pase anvan li lage pijon an ankò. Fwa sa a menm pijon an pa t' tounen vin jwenn li ankò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 13, text = "Se konsa, lè Noe te gen sisan ennan (601 an), nan premye jou premye mwa lanne jwif yo, dlo a te fin bese nèt sou latè. Noe dekouvri batiman an, li voye je l' gade, li wè tout tè a te chèch.", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 14, text = "Sou vennsetyèm jou dezyèm mwa a, tè a te fin chèch nèt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 15, text = "Lè sa a, Bondye di Noe:", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 16, text = "-Soti nan batiman an, ou menm, madanm ou, pitit ou yo ansanm ak madanm pitit ou yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 17, text = "Fè tout bèt yo soti tout ansanm avèk ou, zwazo yo, zannimo domestik yo, tout bèt k'ap trennen sou vant yo. Se pou yo fè pitit, fè anpil pitit pou mete sou tè a ankò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 18, text = "Se konsa Noe soti nan batiman an ansanm ak madanm li, pitit li yo ak madanm pitit li yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 19, text = "tout bèt bwa yo, tout zannimo domestik yo, tout bèt k'ap trennen sou vant yo, tout zwazo yo, yo tout yo soti nan batiman an tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 20, text = "Noe bati yon lotèl. Li pran yonn nan chak kalite bèt ak zwazo ki bon pou moun manje, li touye yo, li boule yo nèt sou lotèl la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 21, text = "Lè Bondye pran bon sant lan, sa te fè l' plezi. Li di nan kè l' -Mwen p'ap janm bay tè a madichon ankò poutèt sa lèzòm fè, paske depi yo jenn, se move lide ase ki nan kè yo. Mwen p'ap janm detwi tout bèt vivan yo ankò, jan mwen sot fè l' la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 8, verseNumber = 22, text = "Toutotan latè a la, va gen yon lè pou plante, yon lè pou rekòlte, va gen sezon fredi ak sezon chalè, va gen sezon sèk, ak sezon lapli, va gen lajounen, va gen lannwit. Wi, toutotan latè a la, bagay sa yo p'ap janm sispann.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 1, text = "Bondye beni Noe ak pitit li yo, li di yo. Fè pitit, fè anpil anpil pitit mete sou tè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 2, text = "Se pou tout zannimo sou latè, tout zwazo ki nan syèl la, tout bèt vivan ki sou latè, tout pwason ki nan lanmè bese tèt devan nou. Se pou yo pè nou. Mwen ban nou pouvwa sou yo tout.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 3, text = "Koulye a, nou gen dwa manje tout kalite bèt vivan k'ap mache, tout kalite fèy vèt. Mwen ban nou tout pou manje.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 4, text = "Tansèlman, se pa pou n' manje vyann ak tout san ladan l', paske san yon bèt se nanm li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 5, text = "Konprann sa byen: si yon moun touye nou, m'ap fè l' rann mwen kont. M'ap fè tout bèt ki touye nou rann mwen kont. tout moun ki touye moun parèy yo gen pou rann mwen kont.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 6, text = "Si yon moun touye yon moun, yon lòt moun gen pou touye l' tou, paske Bondye kreye moun pòtre ak li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 7, text = "Nou menm, se pou nou fè pitit, anpil pitit. Gaye kò nou toupatou sou latè, pou pitit nou yo toujou fè anpil pitit tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 8, text = "Bondye pale ankò ak Noe ansanm ak pitit li yo, li di yo:", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 9, text = "-Men m'ap pase yon kontra ak nou tout ansanm ak tout pitit pitit k'ap vin apre nou yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 10, text = "M'ap pase kontra a ak tout bèt vivan ki la avèk nou yo, zwazo, zannimo domestik, bèt nan bwa, avèk tout sa ki soti nan batiman an pou peple sou latè ankò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 11, text = "Wi, m'ap pase kontra mwen ak nou: mwen pwomèt pou m' pa janm voye gwo inondasyon ankò pou detwi tout moun ak tout bèt vivan yo. Konsa, p'ap janm gen gwo inondasyon ankò pou ravaje latè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 12, text = "Bondye di ankò-Kontra m'ap pase avèk nou ansanm ak tout bèt vivan ki la avèk nou yo, se yon kontra k'ap la pou tout tan. M'ap ban nou yon siy pou li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 13, text = "M'ap mete lakansyèl mwen nan syèl la. Men siy m'ap ban nou pou kontra mwen pase ak latè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 14, text = "Chak fwa m'a fè nwaj yo konmanse sanble, lakansyèl la va parèt nan syèl la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 15, text = "Lè sa a, m'a chonje kontra mwen te fè avèk nou ansanm avèk tout kalite bèt vivan yo. p'ap janm gen gwo inondasyon ankò ki pou detwi tout moun ak tout bèt k'ap viv sou latè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 16, text = "Lè lakansyèl la va parèt nan syèl la, m'a wè l', m'a chonje kontra mwen te pase pou tout tan ak tout moun ansanm ak tout kalite bèt k'ap viv sou latè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 17, text = "Sa se siy kontra mwen pase ak tout moun ansanm ak tout bèt k'ap viv sou latè. Se konsa Bondye te pale ak Noe.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 18, text = "Men non pitit Noe yo ki te soti nan batiman an: Sèm, Kam ak Jafè. Kam se te papa Kanaran.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 19, text = "Se twa pitit Noe sa yo ki peple mete moun sou tout latè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 20, text = "Noe se premye moun ki travay latè. Li plante yon jaden rezen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 21, text = "Yon jou, apre li te fin bwè diven, li sou. Li wete tout rad sou li, li kouche toutouni anba tant li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 22, text = "Lè Kam, papa Kanaran, wè papa l' toutouni, li ale di de frè l' yo sa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 23, text = "Men, Sèm ak Jafè pran yon gwo rad, yo chak pran yon bout, yo pase l' dèyè do yo, yo kenbe l' anwo zepòl yo. Yo mache pa do, yo antre, yo kouvri papa yo san yo pa janm vire tèt yo gade dèyè. Konsa yo pa wè papa yo toutouni.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 24, text = "Lè Noe soti anba toudisman diven l' lan, yo di l' sa dezyèm pitit gason l' lan te fè l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 25, text = "Li di. Madichon pou Kanaran! Se pou l' tounen dènye klas esklav frè l' yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 26, text = "Li di ankò. Lwanj pou Seyè a, Bondye Sèm lan. Se pou Kanaran tounen esklav Sèm.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 27, text = "Se pou Bondye mete sou byen Jafè yo. Se pou pitit pitit Jafè yo viv byen ak pitit Sèm yo. Se pou Kanaran tounen esklav yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 28, text = "Apre gwo inondasyon an, Noe viv twasansenkantan (350 an).", bookId = 1),
        Verse(book = "Jenèz", chapter = 9, verseNumber = 29, text = "Lè l' mouri, li te gen nèfsansenkantan (950 an).", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 1, text = "Apre gwo inondasyon an, pitit Noe yo, Sèm, Kam ak Jafè, te fè pitit. Men non pitit gason yo te fè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 2, text = "Men pitit gason Jafè yo: Se te Gomè, Magòg, Madayi, Javan, Toubal, Mechèk ak Tiras.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 3, text = "Gomè te fè twa pitit gason. Achkenaz, Rifat ak Togama.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 4, text = "Se Javan ki te papa Elicha, Tasis, Kitim ak Wodanim.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 5, text = "Se tout pitit ak pitit pitit Jafè yo sa ki zansèt tout moun k'ap viv nan zile yo, yo chak sou tè pa yo, yo chak ak lang pa yo. Yo t'ap viv ansanm, fanmi ak fanmi, nasyon ak nasyon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 6, text = "Men pitit gason Kam yo. Se te Kouch, Mizrayim, Pout ak Kanaran.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 7, text = "Kouch te fè senk pitit gason: Seba, Avila, Sabta, Rama ak Sabteka. Rama menm te gen de pitit gason: Seba ak Dedan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 8, text = "Kouch te gen yon lòt pitit gason yo te rele: Nimwòd. Nimwòd sa a, se premye moun ki te gwo chèf sou latè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 9, text = "Se te yon gwo chasè devan Seyè a. Se poutèt sa yo di. Gwo chasè devan Bondye tankou Nimwòd.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 10, text = "Nan peyi kote li t'ap gouvènen an te gen lavil sa yo: Babèl, Erèk, Akad, Kalne nan peyi Chenea.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 11, text = "Apre sa, li kite peyi a, li ale lavil Asou. Men lavil li bati yo: Neniv, Reobòt-Ir, Kalak.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 12, text = "Lèfini, li bati lavil Rezèm ant Neniv ak Kalak. Kalak sa a te yon gwo lavil.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 13, text = "Mizrayim fè pitit. Se yo ki zansèt moun peyi Lidi, peyi Anan, peyi Leyab ak peyi Naftou,", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 14, text = "peyi Patwous, peyi Kaslou ak peyi Kaftò. Se nan peyi Kaslou sa a moun Filisti yo soti.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 15, text = "Premye pitit Kanaran se te Sidon. Apre sa vin Et.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 16, text = "Se Kanaran tout ki papa Jebis, Amori, Gigach,", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 17, text = "Evi, Aka, Seni,", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 18, text = "Avad, Zema, Amat. Apre sa tout fanmi Kanaran yo gaye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 19, text = "Lizyè tè moun Kanaran yo pati depi lavil Sidon, li mete tèt sou Gera jouk li rive Gaza. Apre sa, li vire sou Sodòm ak Gomò, Adma ak Seboyim jouk li rive Lecha.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 20, text = "Se tout pitit ak pitit pitit Kam yo sa, yo chak sou tè pa yo, yo chak ak lang yo. Yo t'ap viv ansanm, fanmi ak fanmi, nasyon ak nasyon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 21, text = "Sèm te gran frè Jafè. Li te gen anpil pitit tou. Se li ki te zansèt tout pitit Ebè yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 22, text = "Men pitit gason Sèm yo. Se te Elam, Asou, Apachad, Lidi ak Aram.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 23, text = "Men pitit Aram yo. Se te Ouz, Oul, Getè ak Mach.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 24, text = "Se Apachad ki te papa Chelak. Chelak menm te papa Ebè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 25, text = "Ebè te gen de pitit gason. Yonn te rele Pelèg, paske se nan tan li moun sou latè te divize yonn ak lòt. Yo te rele frè l' la Joktan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 26, text = "Joktan te papa Almodad, Chelèf, Azmavèt, Jerak,", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 27, text = "Adoram, Ouzal, Dikla,", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 28, text = "Obal, Abimayèl, Seba,", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 29, text = "Ofi, Avila ak Jobab. Yo tout se pitit Joktan yo te ye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 30, text = "Tè kote yo t'ap viv la te pran depi lavil Mecha, li moute kote lavil Sefa, jouk mòn ki bò kote solèy leve a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 31, text = "Se tout pitit ak pitit pitit Sèm yo sa, yo chak sou tè pa yo, yo chak ak lang pa yo. Yo t'ap viv ansanm, fanmi ak fanmi, nasyon ak nasyon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 10, verseNumber = 32, text = "tout moun sa yo se branch fanmi pitit Noe yo, dapre zansèt yo, nasyon pa nasyon. Apre gwo inondasyon an, tout nasyon ki sou latè soti nan pitit Noe yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 1, text = "Nan konmansman, tout moun sou latè te pale yon sèl lang, yonn te konprann lòt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 2, text = "Apre yo pati soti kote solèy leve a, yo rive nan yon plenn nan peyi Chenea. Yo moute kay yo la, yo rete.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 3, text = "Lè sa a, yonn di lòt. Mezanmi, vini non! Ann fè brik. Ann kwit yo nan dife. Se konsa, yo pran brik sèvi wòch pou bati kay, yo pran asfat sèvi mòtye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 4, text = "Apre sa, yo di. Annou wè! Ann bati yon gwo lavil pou nou rete ak yon gwo gwo kay tout won byen wo ki rive jouk nan syèl la. Konsa tout moun va respekte nou, yo p'ap ka gaye nou toupatou sou latè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 5, text = "Seyè a desann pou l' wè lavil la ansanm ak gwo kay won moun yo t'ap bati a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 6, text = "Epi li di. Koulye a, gade! Yo tout fè yon sèl pèp. Yo tout yo pale yon sèl lang. Gade sa yo konmanse ap fè. Talè konsa y'ap pare pou yo fè sa yo vle.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 7, text = "Bon. N'ap desann, n'ap mele lang yo. Konsa, yonn p'ap ka konprann sa lòt ap di.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 8, text = "Se konsa Seyè a gaye yo toupatou sou latè. Yo sispann bati lavil la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 9, text = "Se poutèt sa yo rele lavil la Babèl, paske se la Seyè a te mele lang tout moun ki rete sou latè, li fè yo pati, li gaye yo toupatou sou latè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 10, text = "Men pitit pitit Sèm yo. Dezan apre inondasyon an, Sèm te gen santan (100 an) lè li fè yon pitit gason yo rele Apachad.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 11, text = "Apre sa, li viv senksanzan (500 an) ankò. Li te fè lòt pitit gason ak pitit fi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 12, text = "Apachad te gen trannsenkan lè li te fè yon pitit gason yo rele Chela.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 13, text = "Apre sa, li viv katsantwazan (403 an) ankò. Li te fè lòt pitit gason ak pitit fi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 14, text = "Chela te gen trantan lè li fè yon pitit gason yo rele Ebè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 15, text = "Apre sa, li viv katsantwazan (403 an) ankò. Li te fè lòt pitit gason ak pitit fi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 16, text = "Ebè te gen trannkatran lè li fè yon pitit gason yo rele Pelèg.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 17, text = "Apre sa, li viv katsantrantan (430 an). Li te fè lòt pitit gason ak pitit fi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 18, text = "Pelèg te gen trantan lè li fè yon pitit gason yo rele Reou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 19, text = "Apre sa, li viv desannevan (209 an) ankò. Li te fè lòt pitit gason ak pitit fi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 20, text = "Reou te gen tranndezan lè li fè yon pitit gason yo rele Sewoug.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 21, text = "Apre sa, li viv desansetan (207 an) ankò. Li fè lòt pitit gason ak pitit fi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 22, text = "Sewoug te gen trantan lè li fè yon pitit gason yo rele Nakò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 23, text = "Apre sa, li viv desanzan (200 an) ankò. Li te fè lòt pitit gason ak pitit fi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 24, text = "Nakò te gen ventnevan lè li fè yon pitit gason yo rele Terak.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 25, text = "Apre sa, li viv sandiznevan (119 an) ankò. Li te fè lòt pitit gason ak pitit fi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 26, text = "Terak te gen swasanndizan lè li fè twa pitit gason yo rele Abram, Nakò ak Aran.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 27, text = "Men pitit ak pitit pitit Terak yo: Terak te papa Abram, Nakò ak Aran. Aran te papa Lòt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 28, text = "Aran mouri anvan papa l'. Li mouri lavil Our nan peyi Kalde kote l' te fèt la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 29, text = "Abram ak Nakò te fè pozisyon. Abram marye ak Sarayi, Nakò marye ak Milka, pitit fi Aran. Aran te gen yon lòt pitit ankò yo te rele Jiska.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 30, text = "Sarayi pa t' gen pitit, li pa t' ka fè pitit.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 31, text = "Terak pran pitit li, Abram, pitit pitit li, Lòt, ki te pitit Aran, ansanm ak bèlfi li Sarayi ki te madanm Abram, pitit li. Li pati ak yo, li kite lavil Our nan peyi Kalde pou li ale nan peyi Kanaran. Men lè yo rive lavil Karan, yo te rete la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 11, verseNumber = 32, text = "Se la Terak mouri. Li te gen desansenkan (205 an).", bookId = 1),
        Verse(book = "Jenèz", chapter = 12, verseNumber = 1, text = "Seyè a di Abram konsa. Pati, kite peyi ou la. Kite tout fanmi ou. Kite kay papa ou, ale nan peyi m'a moutre ou la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 12, verseNumber = 2, text = "M'ap ba ou anpil pitit pitit. Y'a tounen yon gwo nasyon. m'a beni ou. Y'a nonmen non ou toupatou; w'a sèvi yon benediksyon pou tout moun.", bookId = 1),
        Verse(book = "Jenèz", chapter = 12, verseNumber = 3, text = "M'ap voye benediksyon mwen sou tout moun ki va mande benediksyon pou ou. Men, m'ap madichonnen tout moun ki va ba ou madichon. Gremesi ou, tout nasyon sou latè va jwenn benediksyon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 12, verseNumber = 4, text = "Abram pati jan Seyè a te di l' la. Lòt pati ansanm avè l' tou. Abram te gen swasannkenzan lè li kite Karan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 12, verseNumber = 5, text = "Abram pran Sarayi, madanm li, Lòt, pitit frè li a, ansanm ak tout byen li te genyen ak tout domestik li te gen avè l' nan lavil Karan, yo tout yo pati pou Kanaran. Yo rive nan peyi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 12, verseNumber = 6, text = "Abram mache nan tout peyi a, jouk li rive kote yo rele Sichèm, bò pye bwadchenn More a. Lè sa a se moun Kanaran yo ki te rete nan peyi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 12, verseNumber = 7, text = "Abram fè yon vizyon, li wè Seyè a ki di l'. Men peyi m'ap bay pitit pitit ou yo a. Se la Abram bati yon lotèl pou Seyè a ki te parèt devan li nan vizyon an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 12, verseNumber = 8, text = "Apre sa, li pati ankò, li ale nan mòn ki toupre lavil Betèl, sou bò solèy leve. Li moute tant li la. Betèl te sou bò lanmè, Ayi te sou bò solèy leve. Abram bati yon lotèl pou Seyè a la tou, epi li fè sèvis pou li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 12, verseNumber = 9, text = "Li vwayaje toujou, li desann nan direksyon sid, bout pou bout jouk li rive nan rejyon Negèv la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 12, verseNumber = 10, text = "Men, grangou tonbe sou peyi a, pa t' gen manje menm. Se poutèt sa Abram te desann nan peyi Lejip. Li rete la yon bon bout tan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 12, verseNumber = 11, text = "Li te prèt pou antre nan peyi Lejip lè li di Sarayi, madanm li. Koute non. Ou se yon bèl fanm.", bookId = 1),
        Verse(book = "Jenèz", chapter = 12, verseNumber = 12, text = "Lè gason nan peyi Lejip yo wè ou, yo pral di: Se madanm li wi! Epi y'a touye m' pou yo sa pran ou nan men m'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 12, verseNumber = 13, text = "Tanpri, di yo se sè mwen ou ye pou yo pa touye m', pou yo ka aji byen avè m' poutèt ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 12, verseNumber = 14, text = "Se konsa, rive Abram rive nan peyi Lejip, mesye yo gen tan wè jan Sarayi te yon bèl fanm.", bookId = 1),
        Verse(book = "Jenèz", chapter = 12, verseNumber = 15, text = "Kèk grannèg nan gouvènman an wè sa tou, y al di farawon an jan li te bèl. Epi yo mennen Sarayi nan palè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 12, verseNumber = 16, text = "Poutèt Sarayi, farawon an te aji byen ak Abram. Li ba li kantite mouton, kabrit, bèf, bourik, chamo, san konte esklav, fanm kou gason, pou sèvi l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 12, verseNumber = 17, text = "Men, paske farawon an te pran Sarayi, madanm Abram, pou madanm li, Seyè a voye yon bann move maladi sou li ak sou moun ki te nan palè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 12, verseNumber = 18, text = "Lè sa a, farawon an fè rele Abram, li di li. Kisa ou fè m' konsa? Poukisa ou pa t' di m' se madanm ou Sarayi ye?", bookId = 1),
        Verse(book = "Jenèz", chapter = 12, verseNumber = 19, text = "Poukisa ou te di m' se sè ou li ye? Mwen pa ta janm pran l' pou madanm mwen. Monchè, men madanm ou. Pran l', al fè wout ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 12, verseNumber = 20, text = "Farawon an pase moun li yo lòd pou fè Abram pati kite peyi a, li menm ansanm ak madanm li avèk tout sa ki te pou li.", bookId = 1)
    )

    private val part2 = listOf(
        Verse(book = "Jenèz", chapter = 13, verseNumber = 1, text = "Abram kite peyi Lejip, li moute nan nò, li tounen nan rejyon Negèv la, ansanm ak madanm li avèk tout sa li genyen. Lòt, neve l' la, te avèk li tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 13, verseNumber = 2, text = "Abram te rich anpil, li te gen anpil mouton, anpil kabrit ak anpil bèf, li te gen anpil lajan ak anpil lò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 13, verseNumber = 3, text = "Li vwayaje toujou jouk li kite Negèv la dèyè. Bout pou bout li rive bò Betèl, kote li te moute tant li anvan an, ant lavil Betèl ak lavil Ayi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 13, verseNumber = 4, text = "Li tounen kote li te moute yon lotèl premye fwa a. Li fè sèvis pou Bondye ankò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 13, verseNumber = 5, text = "Lòt menm, neve ki t'ap vwayaje ansanm avèk Abram lan, te gen mouton ak bèf pa l' tou. Li te gen moun tout avèk li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 13, verseNumber = 6, text = "Peyi a te vin twò piti pou yo de a rete ansanm, paske yo te gen twòp zannimo pou bay manje.", bookId = 1),
        Verse(book = "Jenèz", chapter = 13, verseNumber = 7, text = "Se konsa, te vin gen yon kabouyay ant gadò mouton Abram yo ak gadò mouton Lòt yo. Lè sa a, se moun Kanaran yo ak moun Ferezi yo ki te rete nan peyi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 13, verseNumber = 8, text = "Abram di Lòt konsa. Monchè, se fanmi nou ye. Pa gen rezon pou nou gen kont yonn ak lòt, ni pou gadò ou yo gen kont ak gadò pa m' yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 13, verseNumber = 9, text = "Men tout peyi a devan nou! Ann separe. Si ou fè bò dwat, m'ap fè bò gòch. Si ou fè bò gòch, m'ap fè bò dwat.", bookId = 1),
        Verse(book = "Jenèz", chapter = 13, verseNumber = 10, text = "Lòt voye je l' toupatou, li gade plenn Jouden an byen gade. tout plenn lan, rive jouk Zoa, te wouze nèt ale. Jaden yo te tankou jaden Seyè a, tankou nan peyi Lejip. (Lè sa a, Seyè a pa t' ankò disparèt lavil Sodòm ak Gomò.)", bookId = 1),
        Verse(book = "Jenèz", chapter = 13, verseNumber = 11, text = "Lòt chwazi plenn Jouden an pou li. Li pati nan direksyon solèy leve. Se konsa de mesye yo te separe.", bookId = 1),
        Verse(book = "Jenèz", chapter = 13, verseNumber = 12, text = "Abram rete nan peyi Kanaran. Lòt menm al moute kay li nan mitan lavil yo ki te nan plenn lan. Li moute kay li bò lavil Sodòm.", bookId = 1),
        Verse(book = "Jenèz", chapter = 13, verseNumber = 13, text = "Moun Sodòm yo te move moun anpil. Yo t'ap fè anpil peche kont Seyè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 13, verseNumber = 14, text = "Lè Lòt fin ale, Seyè a di Abram konsa. Kanpe kote ou ye a, voye je ou toupatou, nan tout direksyon: nò, sid, lès, lwès,", bookId = 1),
        Verse(book = "Jenèz", chapter = 13, verseNumber = 15, text = "paske mwen pral ba ou tout tè ou wè a pou ou ak pou pitit pitit ou yo pou tout tan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 13, verseNumber = 16, text = "Mapral ba ou anpil pitit pitit. Si yon moun ka konte tout grenn pousyè ki sou latè, la rive konte pitit pitit ou yo tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 13, verseNumber = 17, text = "Bon. Koulye a, ou mèt pwonmennen mache nan tout peyi a, paske se ou menm mwen pral bay li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 13, verseNumber = 18, text = "Se konsa, Abram ranmase tout zafè l', li vin rete bò pye bwadchenn Manmre yo, toupre Ebwon. Se la li bati yon lotèl pou Seyè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 1, text = "Lè sa a, Anmrafèl te wa Chenea, Ajòk te wa Elaza, Kedòlaòmè te wa Elam, Tideal te wa lòt nasyon yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 2, text = "Yo kat yo leve, y al fè lagè ak senk lòt wa. Bera ki te wa Sodòm, Bicha ki te wa Gomò, Cheneab ki te wa Adma, Chemebè ki te wa zeboyim yo, ak wa peyi Bela a. Peyi sa a te rele Zoa tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 3, text = "Senk wa sa yo mete tèt yo ansanm, yo reyini nan Fon Sidim lan kote lanmè Sèl la ye a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 4, text = "Pandan douzan, senk wa sa yo te soumèt devan Kedòlaòmè. Lanne ki fè yo trèzan an, yo revòlte.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 5, text = "Lanne apre sa, ki pou ta fè yo katòzan nan pozisyon sa a, Kedòlaòmè ansanm ak twa wa ki te mete tèt ansanm ak li yo vin rive. Yo bat refayim yo nan lavil Astawòt-Kanayim, yo bat zouzim yo nan lavil Am, yo bat emim yo nan laplenn Chave-Kiryatayim.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 6, text = "Yo bat orit yo sou mòn Seyi, jouk bò kote pye bwadchenn Paran an, ki toupre dezè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 7, text = "Apre sa, yo kase tèt tounen, yo rive bò Sous jijman an, yo bat tout chèf moun Amelèk yo, yo pran tout bèt yo. Yo bat moun Amori yo tout ki rete Azazon-Tama, yo bat yo byen bat.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 8, text = "Lè sa a, wa Sodòm, wa Gomò, wa Adma, wa zeboyim ansanm ak wa Bela a, yo soti, yo pran pozisyon nan Fon Sidim lan pou yo goumen", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 9, text = "kont Kedòlaòmè, wa Elam, Tideal, wa lòt nasyon yo, Anmrafèl, wa Chenea ak Ajòch, wa Elaza. Sa te fè kat wa kont senk wa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 10, text = "Nan Fon Sidim lan te gen anpil twou byen fon ki te plen asfat. Pandan batay la, wa Sodòm ak wa Gomò yo pran kouri pou lènmi yo, yo te vle wete kò yo nan batay la, yo tonbe nan twou asfat yo. Lòt wa yo menm kouri al kache nan mòn.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 11, text = "Kat wa yo pran tout sa yo jwenn nan Sodòm ak Gomò, ata pwovizyon manje, epi y al fè wout yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 12, text = "Yo pase men yo yo pran Lòt, pitit frè Abram lan, ansanm ak tout byen l' yo, paske se Sodòm Lòt te rete.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 13, text = "Men, yonn nan mesye ki te chape nan batay la vin di Abram sa. Lè sa a, Abram te rete toupre pye bwadchenn Manmre a. Manmre sa a, se te yon moun Amori. Se te frè Echkòl ak Ane. tout de mesye sa yo te pase kontra avèk Abram.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 14, text = "Lè Abram vin konnen yo te fè neve l' la prizonye, li sanble tout domestik ki te fèt lakay li yo epi ki te konn goumen. Li pran twasandizwit (318) antou. Epi li file dèyè wa yo jouk lavil Dann.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 15, text = "La, yon jou lannwit, li separe mesye li yo, li fè yo fè de gwoup, epi li atake lènmi yo. Li bat yo byen bat, li kouri dèyè yo jouk yo rive Oba, ki sou bò nò lavil Damas.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 16, text = "Li reprann tout byen yo te pran yo, li mennen Lòt, neve li a, tounen lakay li ansanm ak tout byen l' yo, tout medam yo ak tout pèp la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 17, text = "Apre Abram te fin kraze Kedòlaòmè ansanm ak tout lòt wa ki te fè tèt ansanm ak Kedòlaòmè yo, li t'ap tounen lakay li. Wa Sodòm lan vin rankontre l' nan Fon Chave a ki rele Fon Wa a tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 18, text = "Mèlkisedèk menm ki te wa peyi Salèm fè pote pen ak diven vini. Se yon prèt ki t'ap sèvi Bondye ki anwo nan syèl la li te ye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 19, text = "Li beni Abram, li di. Se pou Bondye ki anwo nan syèl la, li menm ki fè syèl la ak latè a, beni Abram.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 20, text = "Lwanj pou Bondye ki anwo nan syèl la. Se li menm ki te lage lènmi ou yo nan men ou. Apre sa, Abram ba li yon dizyèm nan tout sa li te pran.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 21, text = "Lèfini, wa Sodòm lan di Abram. Ou mèt gade tout byen yo pou ou. Men ban mwen moun yo sèlman.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 22, text = "Abram reponn wa Sodòm lan, li di l'. Mwen fè sèman devan Seyè a, Bondye ki anwo nan syèl la, li menm ki fè syèl la ak latè a,", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 23, text = "mwen p'ap pran anyen nan sa ki pou ou, li te mèt yon ti moso fil, yon kòd sapat. Konsa, ou p'ap janm ka di se ou menm ki fè Abram rich.", bookId = 1),
        Verse(book = "Jenèz", chapter = 14, verseNumber = 24, text = "Mwen pa bezwen anyen pou tèt pa m'. Men, m'ap asepte sa moun mwen yo te manje, ansanm ak pòsyon ki pou moun ki te mache avè m' yo. Wi, se pou Ane, Echkòl ak Manmre pran sa ki vin pou yo a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 15, verseNumber = 1, text = "Apre bagay sa yo, Abram fè yon vizyon. Li wè Seyè a ki t'ap pale avè l'. Seyè a di l' konsa. Abram, ou pa bezwen pè anyen. Se mwen menm k'ap pwoteje ou. M' sere yon gwo gwo rekonpans pou ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 15, verseNumber = 2, text = "Abram di. Seyè, Bondye, kisa ou vle ban mwen? Mwen tout fin mouri, mwen pa gen pitit. Sèl moun lakay mwen ki pral eritye m', se Elyezè, moun peyi Damas la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 15, verseNumber = 3, text = "Abram di ankò. Gade! Ou pa ban m' pitit. Se yonn nan domestik mwen yo ki pral eritye m'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 15, verseNumber = 4, text = "Lè sa a, li tande Seyè a ki di l' konsa. Non, se pa li menm ki pral eritye ou. Se pwòp pitit zantray ou ki pral eritye ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 15, verseNumber = 5, text = "Seyè a fè Abram soti deyò, li di l' konsa Leve je ou, gade syèl la byen. Konte zetwal yo si ou kapab. Apre sa, li di. Pitit pitit ou yo va anpil tankou zetwal nan syèl la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 15, verseNumber = 6, text = "Abram mete konfyans li nan Seyè a, se konsa Seyè a fè l' gras.", bookId = 1),
        Verse(book = "Jenèz", chapter = 15, verseNumber = 7, text = "Seyè a di. Se mwen menm, Seyè a, ki te fè ou soti lavil Our nan peyi Kalde a, pou m' te ka ba ou peyi sa a pou ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 15, verseNumber = 8, text = "Abram di. Seyè, Bondye, kijan pou m' fè konnen peyi sa a pou mwen vre?", bookId = 1),
        Verse(book = "Jenèz", chapter = 15, verseNumber = 9, text = "Seyè a di l'. Pran yon ti gazèl bèf twazan, yon fenmèl kabrit twazan, yon belye twazan, yon toutrèl ak yon jenn pijon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 15, verseNumber = 10, text = "Abram al pran tout bèt sa yo, li koupe yo mitan pou mitan, li mete moso yo yonn anfas lòt. Men, li pa koupe zwazo yo an de.", bookId = 1),
        Verse(book = "Jenèz", chapter = 15, verseNumber = 11, text = "Chak fwa malfini karanklou vin pou desann sou vyann bèt yo, Abram pouse yo ale.", bookId = 1),
        Verse(book = "Jenèz", chapter = 15, verseNumber = 12, text = "Solèy tapral kouche lè dòmi vòlè Abram. Li dòmi nèt ale. Epi yon sèl lapèz pran l' nan dòmi an. Kote l' te ye a vin fè tout nwa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 15, verseNumber = 13, text = "Seyè a di l'. Konnen sa byen: Pitit pitit ou yo pral viv tankou etranje nan yon peyi ki pa pou yo. Y'ap fè yo tounen esklav, y'ap peze yo pandan katsanzan (400 an).", bookId = 1),
        Verse(book = "Jenèz", chapter = 15, verseNumber = 14, text = "Men, apre sa, m'ap pini nasyon ki va pran yo fè esklav la. Konsa, lè lè a va rive pou yo kite peyi sa a, y'a soti avèk anpil anpil richès.", bookId = 1),
        Verse(book = "Jenèz", chapter = 15, verseNumber = 15, text = "Kanta ou menm, ou pral mouri ak kè poze, ou pral jwenn zansèt ou yo ki mouri deja. Wi, anvan ou antre anba tè, wa viv lontan san ankenn pwoblèm.", bookId = 1),
        Verse(book = "Jenèz", chapter = 15, verseNumber = 16, text = "Apre kat jenerasyon, pitit pitit ou yo va tounen isit la, paske se pou nou tann moun Amori yo rive nan dènye bout mechanste yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 15, verseNumber = 17, text = "Apre solèy fin kouche, te fè nwa anpil. Epi men li, yon recho ki t'ap fè lafimen ansanm ak yon gwo bwa dife tout limen parèt. Yo pase nan mitan moso vyann bèt yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 15, verseNumber = 18, text = "Se jou sa a Seyè a te pase kontra avèk Abram. Li di l' konsa M'ap bay pitit pitit ou yo tout peyi sa a, depi larivyè Lejip, rive jouk larivyè Lefrat la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 15, verseNumber = 19, text = "Sa vle di tout peyi kote moun Keni yo, moun Kenizi yo, moun Kadmon yo,", bookId = 1),
        Verse(book = "Jenèz", chapter = 15, verseNumber = 20, text = "moun Et yo, moun Ferezi yo, moun refayim yo,", bookId = 1),
        Verse(book = "Jenèz", chapter = 15, verseNumber = 21, text = "moun Amori yo, moun Kanaran yo, moun Gigach yo ak moun Jebis yo rete.", bookId = 1),
        Verse(book = "Jenèz", chapter = 16, verseNumber = 1, text = "Sarayi, madanm Abram, pa t' janm fè pitit. Sarayi te gen yon sèvant, moun peyi Lejip, yo te rele Aga.", bookId = 1),
        Verse(book = "Jenèz", chapter = 16, verseNumber = 2, text = "Sarayi di Abram konsa. Gade! Seyè a pa kite mwen fè pitit. Al kouche ak sèvant mwen an non. Ou pa janm konnen, li ka fè pitit pou mwen. Abram tonbe dakò ak sa Sarayi te di l' la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 16, verseNumber = 3, text = "Se konsa, Sarayi, madanm Abram, pran sèvant li a, Aga ki te moun peyi Lejip, li bay Abram li pou madanm. Lè sa a, Abram te gen tan gen dizan nan peyi Kanaran.", bookId = 1),
        Verse(book = "Jenèz", chapter = 16, verseNumber = 4, text = "Abram kouche ak Aga. Aga vin ansent. Lè Aga wè li ansent, lògèy vire tèt li, li pa gade Sarayi, metrès li, pou anyen ankò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 16, verseNumber = 5, text = "Lè sa a, Sarayi di Abram. Se fòt ou wi si m'ap sibi tout wont sa a. Se mwen menm ki te ba ou sèvant mwen an pou madanm. Men, depi li wè li ansent lan, li pa gade m' pou anyen ankò. Se Seyè a ki pou jije m' avè ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 16, verseNumber = 6, text = "Abram reponn Sarayi, li di l'. Sèvant ou pou ou. Li sou zòd ou. Ou gen dwa fè sa ou vle avè l'. Se konsa, Sarayi pran maltrete Aga sitèlman, Aga blije sove kite kay la pou li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 16, verseNumber = 7, text = "Zanj Seyè a kontre Aga bò yon sous dlo nan dezè a sou wout ki mennen nan peyi Chour la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 16, verseNumber = 8, text = "Li di l' konsa. Aga, sèvant Sarayi, kote ou soti la a? Kote ou prale? Aga reponn. M'ap kouri pou Sarayi, metrès mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 16, verseNumber = 9, text = "Zanj Seyè a di l'. Tounen lakay metrès ou, soumèt ou devan li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 16, verseNumber = 10, text = "Zanj lan di l' ankò. M'ap ba ou anpil anpil pitit pitit. Moun p'ap ka konte yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 16, verseNumber = 11, text = "Zanj lan di l' ankò. Gade! Ou ansent. Ou pral fè yon ti gason. Wa rele l' Izmayèl, paske Seyè a tande rèl ou nan tray w'ap pase a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 16, verseNumber = 12, text = "Pitit gason ou lan va tankou yon bourik mawon. L'ap chache tout moun kont. tout moun va chache l' kont. Li p'ap mele ak tout frè l' yo. L'ap viv pou kont li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 16, verseNumber = 13, text = "Aga di nan kè l'. Ou kwè se vre se mwen ki wè moun ki wè m' lan? Se konsa li bay Seyè a yon non, li rele l': Ou se Bondye ki wè m' lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 16, verseNumber = 14, text = "Se poutèt sa, yo rele pi dlo ki ant Kadès ak Barèd la: Pi moun vivan ki wè m' lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 16, verseNumber = 15, text = "Aga fè yon pitit gason pou Abram. Abram rele pitit la Izmayèl.", bookId = 1),
        Verse(book = "Jenèz", chapter = 16, verseNumber = 16, text = "Abram te gen katrevensizan lè Aga te fè Izmayèl.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 1, text = "Le Abram rive sou katrevendisnevan laj, Seyè a parèt devan l', li di l' konsa. Mwen se Bondye ki gen tout pouvwa a. Se pou ou toujou fè sa m' di ou fè. Se pou ou mennen yon vi san repwòch.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 2, text = "M'ap pase yon kontra avè ou, m'ap ba ou anpil anpil pitit pitit.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 3, text = "Lè sa a, Abram mete ajenou, li bese tèt li jouk atè. Bondye pale avè l' ankò, li di l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 4, text = "-Men kontra m'ap pase avè ou la. W'ap zansèt moun anpil nasyon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 5, text = "Yo p'ap rele ou Abram ankò. Men y'a rele ou Abraram, paske m'ap fè ou tounen zansèt moun anpil nasyon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 6, text = "M'ap ba ou anpil anpil pitit pitit. Y'ap tounen kantite nasyon. Anpil wa ap soti nan ras ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 7, text = "M'ap kenbe kontra m' lan avè ou, avèk tout ras ou. De pitit an pitit, se va yon kontra k'ap la pou tout tan. Se mwen k'ap Bondye ou, se mwen k'ap Bondye pitit pitit ou yo tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 8, text = "Ou wè tè kote ou rete tankou moun vini koulye a? Mwen gen pou m' ba ou l' ansanm ak tout pitit pitit ou yo. tout peyi Kanaran an ap rele ou pa ou pou tout tan. Wi, se mwen menm k'ap Bondye yo tout.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 9, text = "Bondye di Abraram. Men ou menm ansanm ak tout ras ou, de pitit an pitit, se pou nou dakò pou nou kenbe kontra a avèk mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 10, text = "Men sa pou ou menm ansanm ak tout pitit ou yo pou nou dakò fè: se pou tout gason nan mitan nou sikonsi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 11, text = "Depi koulye a, se pou nou sikonsi tout gason. Se pou sa sèvi yon siy pou moutre gen yon kontra ki pase ant nou menm avè m'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 12, text = "Se pou nou sikonsi tout gason wit jou apre yo fèt, li te mèt pitit moun lakay la, osinon pitit moun lòt nasyon ou pran pou travay lakay ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 13, text = "Wi, se pou yo tout yo sikonsi, kit yo fèt lakay ou, kit yo fèt nan peyi etranje. Se va yon mak nan kò nou pou fè wè kontra mwen pase avèk nou an, se yon kontra ki la pou tout tan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 14, text = "Si yon gason pa sikonsi, se pou yo disparèt li nan ras la, paske li pa t' kenbe kontra mwen fè ak nou an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 15, text = "Apre sa, Bondye di Abraram. Sarayi, madanm ou, p'ap rele Sarayi ankò. Men depi jòdi a y'a rele l' Sara.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 16, text = "M'ap beni madanm ou, m'ap fè l' ba ou yon pitit gason. M'ap beni l', m'ap fè l' tounen manman moun anpil nasyon. Anpil nan pitit pitit li yo va wa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 17, text = "Abraram mete ajenou, li bese tèt li jouk atè. Men, li tonbe ri lè l' chonje jan l' fin granmoun. Li t'ap di nan kè l'. Eske yon nonm ki gen santan ka fè pitit ankò? Eske Sara, yon fanm ki gen katrevendizan, ka vin ansent?", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 18, text = "Li di Bondye. Tanpri, beni Izmayèl. Pa kite l' mouri!", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 19, text = "Men Bondye di l'. Non, se Sara madanm ou, ki gen pou fè yon pitit gason pou ou. W'a rele l' Izarak. M'ap kenbe kontra mwen avèk li, ansanm ak pitit pitit li yo. Pa bliye. Se va yon kontra k'ap la pou tout tan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 20, text = "Ou mande m' pou m' pwoteje Izmayèl pou ou! M'ap fè l' pou ou! M'ap beni l', m'ap ba li anpil pitit ak anpil pitit pitit. Gen douz chèf k'ap soti nan fanmi li. M'ap fè pitit li yo tounen yon gwo nasyon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 21, text = "Men, m'ap kenbe kontra mwen an avèk Izarak, pitit gason Sara pral fè pou ou a. L'ap fèt lanne k'ap vini an, lè konsa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 22, text = "Lè Bondye fin pale avèk Abraram, li kite l', li moute nan syèl.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 23, text = "Jou sa a Abraram pran Izmayèl, pitit gason li an, ak tout gason ki t'ap travay lakay li, kit yo te fèt nan kay la, kit se moun lòt nasyon li te pran pou sèvi l', li sikonsi yo tout menm jou a, jan Bondye te pase l' lòd la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 24, text = "Abraram poutèt pa l' te gen katrevendiznèvan lè l' te sikonsi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 25, text = "Izmayèl, pitit gason l' lan, te gen trèzan lè l' te sikonsi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 26, text = "Yo tout de, yo sikonsi yo menm jou", bookId = 1),
        Verse(book = "Jenèz", chapter = 17, verseNumber = 27, text = "ansanm ak tout domestik ki te lakay li, kit yo te fèt la, kit se achte li te achte yo nan men moun lòt nasyon yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 1, text = "Seyè a parèt devan Abraram bò pye bwadchenn Manmre yo. Abraram te chita nan papòt kay li, lè ki te fè pi cho nan lajounen an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 2, text = "Abraram leve je l', li rete konsa li wè twa mesye kanpe devan li toupre pyebwa yo. Wè li wè yo, li leve nan papòt la, li kouri al jwenn yo, li bese tèt li jouk atè pou l' di yo bonjou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 3, text = "Li di. Mèt, tanpri. Pa pase devan lakay mwen san ou pa fè yon ti rete. Se sèvitè ou mwen ye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 4, text = "Kite m' mande yo pote ti gout dlo pou lave pye ou. Lèfini, w'a pran yon ti repo anba pyebwa sa a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 5, text = "'a pote yon ti manje pou ou soutni kè ou pou ou reprann fòs pou ou ka kontinye vwayaj ou. Ou rive lakay mwen, mwen la pou m' sèvi ou. Yo reponn li: -Dakò. Ou mèt fè jan ou di a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 6, text = "Abraram kouri lakay li, li ale jwenn Sara. Li di l' konsa. Fè vit. Pran trant liv farin bon kalite, mouye l', fè pen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 7, text = "Apre sa, Abraram kouri al nan bann bèt li yo, li pran yon jenn ti bèf byen gra, li bay yonn nan domestik li yo li pou li prese al kòche l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 8, text = "Apre sa, li pran fwomaj, li pran lèt fre, li mete yo ansanm ak vyann yo te pare a, li sèvi mesye yo. Pandan yo t'ap manje, Abraram te kanpe bò kote yo anba pyebwa a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 9, text = "Lèfini, yo mande l'. Kote Sara, madanm ou? Li reponn. Li la wi, anndan kay la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 10, text = "Yonn nan vizitè yo di l'. Mwen gen pou m' tounen isit la, lè konsa lanne k'ap vini an. Lè sa a, Sara, madanm ou, ap gen tan gen yon pitit gason. Sara menm te kanpe nan papòt la dèyè Abraram, li t'ap koute.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 11, text = "Abraram ak Sara te fin vye granmoun. Yo te antre nan laj. Sara te sispann gen lalen li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 12, text = "Sara tonbe ri nan kè l', li t'ap di. Koulye a, kalite jan m' fin vye a, ou kwè lide m' ta sou gason toujou! Epitou, mari mwen, mèt mwen, fin granmoun!", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 13, text = "Seyè a di Abraram. Sa ki gen la a pou Sara ri konsa, pou l'ap di nan kè l'. Eske mwen kapab fè pitit ankò, jan m' fin vye a?", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 14, text = "Bon. Eske gen kichòy ki twòp la a pou Mèt la fè? Sou dat mwen fikse a, m'a tounen pase wè ou ankò. Lè sa a, Sara va gen yon pitit gason.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 15, text = "Sara te pè, li t'ap plede, li t'ap di. Mwen pa t' ri non! Men Seyè a di l'. Men wi, machè, ou te ri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 16, text = "Mesye yo leve, yo pati, yo mete tèt sou Sodòm. Yo rive kote yo te ka voye je yo gade anba pou wè Sodòm. Abraram menm t'ap mache ak yo. Li t'ap kondi yo mete pi devan sou wout la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 17, text = "Seyè a di nan kè l'. Mwen pa kapab kache Abraram sa m' pral fè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 18, text = "Pitit pitit li yo pral tounen yon gwo nasyon ki va gen pouvwa. Gremesi Abraram, tout nasyon sou latè pral jwenn benediksyon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 19, text = "Mwen te chwazi l' pou l' te pase pitit li yo ak tout rès fanmi l' k'ap vin apre li yo lòd pou yo mache nan chemen Seyè a met devan yo, pou yo fè sa ki kòrèk ak sa ki dwat devan Bondye. Se konsa m'a fè pou li tout sa mwen te pwomèt li a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 20, text = "Apre sa, Seyè a di. Se pa ti kras bagay y'ap di sou moun Sodòm ak moun Gomò, paske peche moun sa yo lou anpil.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 21, text = "M'ap desann pou m' wè ak je mwen si sa y'ap di sou yo a se vre. Si se pa vre, m'a konnen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 22, text = "Mesye yo pati, yo mete tèt sou Sodòm. Men, Seyè a te rete ak Abraram.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 23, text = "Abraram pwoche bò kote Seyè a, li mande l'. Eske se vre ou pral touye inonsan yo ansanm ak koupab yo?", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 24, text = "Si gen senkant moun inonsan nan lavil la, èske w'ap detwi tout lavil la? Eske ou p'ap fè pa lavil la poutèt senkant inonsan sa yo?", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 25, text = "Aa! Pou di w'ap fè inonsan peri ak koupab? Se pa posib. Ou pa ka fè sa. Se lenjistis pou inonsan gen menm sò ak koupab. Non, sa pa ka fèt. Bondye k'ap jije tout moun sou tè a pa ka nan fè lenjistis.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 26, text = "Seyè a reponn. Si mwen jwenn senkant inonsan nan lavil Sodòm, m'ap fè pa tout lavil la, poutèt senkant inonsan sa yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 27, text = "Abraram pale ankò, li di. Eskize m' wi! Seyè, si m' penmèt mwen pale ankò. Se moun ase mwen ye, mwen pa gen dwa di ou anyen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 28, text = "Men, si se karannsenk moun inonsan sèlman ou jwenn, èske ou pral detwi tout lavil la paske manke senk pou fè senkant lan? Seyè a reponn. Si mwen jwenn karannsenk inonsan sèlman, mwen p'ap detwi lavil la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 29, text = "Abraram pale ankò, li di. Ou pa janm konnen, ka gen karant inonsan ase? Seyè a reponn. Si gen karant inonsan, mwen p'ap detwi lavil la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 30, text = "Abraram di. Tanpri, Seyè, pa fache sou mwen non. M'ap di ou yon ti mo ankò. Ou pa janm konnen, ou ka jwenn trant inonsan ase nan lavil la. Seyè a reponn. Si mwen jwenn trant, m'ap fè pa lavil la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 31, text = "Abraram di. Eskize m' wi, Seyè, si m' penmèt mwen pale toujou. Men, sipoze ou jwenn vin inonsan sèlman? Seyè a reponn li. Si mwen jwenn vin inonsan, m'ap fè pa lavil la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 32, text = "Abraram di ankò. Tanpri, Seyè, pa fache sou mwen non. M'ap di yon dènye mo. Si ou jwenn dis inonsan ase? Seyè a reponn li. Si mwen jwenn dis inonsan, m'ap fè pa lavil la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 18, verseNumber = 33, text = "Apre li fin pale ak Abraram, Seyè a al fè wout li. Abraram menm tounen lakay li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 1, text = "De zanj Bondye yo rive Sodòm nan aswè. Lòt te chita bò pòtay lavil la. Wè li wè yo, li leve, li al kontre yo. Li bese tèt li jouk atè pou l' di yo bonjou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 2, text = "Li di. Mesye, mwen la pou m' sèvi nou. Tanpri, vin lakay mwen. n'a ka lave pye nou, n'a pase nwit la la. Denmen maten, n'a leve, n'a reprann wout nou. Mesye yo reponn. Non. Nou pral pase nwit la sou laplas la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 3, text = "Men Lòt te fòse yo sitèlman, y' al lakay li avè l'. Lòt pare yon bon manje pou yo, li fè pen san ledven. Epi yo manje.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 4, text = "Yo pa t' ankò kouche, lè mesye lavil Sodòm yo, jenn gason kou vye tonton, sènen kay la. tout gason nan lavil la te kouri vini.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 5, text = "Yo rele Lòt, yo di l' konsa. Kote mesye ki vin pase nwit lakay ou aswè a? Fè yo soti vin jwenn nou pou nou kouche ak yo?", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 6, text = "Lòt soti al jwenn yo nan papòt la. Li fèmen pòt la dèyè do l',", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 7, text = "li di yo konsa Tanpri, mezanmi. Pa fè bagay sal sa a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 8, text = "Gade, mwen gen de pitit fi ki tifi toujou, m'ap mennen yo ban nou. Nou mèt fè sa nou vle avèk yo. Men, pa fè mesye sa yo anyen, paske mwen resevwa yo lakay mwen, mwen fèt pou m' pwoteje yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 9, text = "Men, yo di. Wete kò ou la. Se moun vini ou ye! Kisa ou ye atò pou ou vin di nou sa pou nou fè. Sispann fè radòt la a, anvan nou pa fè ou pi mal pase yo. Sa ou tande a, yo bourade Lòt, epi yo pwoche pou yo defonse pòt la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 10, text = "Men, de mesye yo ki te anndan an lonje men yo, yo rale Lòt antre anndan, epi yo fèmen pòt la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 11, text = "Lèfini, yo vegle tout mesye ki te devan pòt kay la, depi pi piti a jouk pi gran an. Se konsa mesye yo t'ap vire tounen adwat agoch, yo pa t' kapab jwenn kote pòt kay la te ye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 12, text = "De mesye yo pale ak Lòt, yo di l' konsa. Ki moun ankò ou gen nan lavil la? Pran bofi ou yo, pitit gason ou yo, ak pitit fi ou yo ansanm ak tout bagay ou gen nan lavil la, mete kò ou deyò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 13, text = "Nou pral detwi tout bò isit la. Seyè a te tande tout sa yo t'ap di sou moun lavil sa a. Li voye nou detwi l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 14, text = "Lòt soti, li al jwenn mari pitit fi li yo, li di yo. Leve non, fè vit, ann met deyò. Seyè a pral detwi lavil la. Men bofi li yo te kwè se jwe li t'ap jwe.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 15, text = "Kou jou pral kase, zanj Bondye yo leve Lòt pou l' fè vit. Yo di l'. Fè vit non, monchè! Pran madanm ou ak de pitit fi ou yo, met deyò. Si se pa sa, n'ap mouri tout lè Bondye ap pini lavil la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 16, text = "Lè yo wè Lòt t'ap kalbende, yo pran men li, yo pran men madanm li ansanm ak de pitit fi li yo, yo mennen yo andeyò lavil la, yo lage yo. Yo te fè sa, paske Seyè a te gen pitye pou Lòt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 17, text = "Apre zanj yo te fin fè yo soti nan lavil la, yo di l'. Sove poul ou, si ou pa vle mouri. Pa gad dèyè. Pa rete menm nan plenn lan. Kouri al nan mòn yo pou ou pa pase tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 18, text = "Men, Lòt reponn li. O! Non, Mèt. Tanpri, pa mande m' tout sa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 19, text = "Gade, ou deja fè m' yon gwo favè. Ou moutre m' jan ou gen pitye anpil pou mwen. Ou sove lavi m'. Men, mòn lan twò lwen. m'a mouri anvan m' rive, malè a va gen tan rive sou mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 20, text = "Gade: ou wè ti bouk sa a? Li toupre. m'a gen tan rive la pou m' kache kò mwen. Tanpri, kite m' ale la. Ou wè se yon ti kote ki tout piti. Konsa m'a sove lavi m'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 21, text = "Zanj lan di l'. Dakò, Mwen fè ou favè sa a ankò: mwen p'ap detwi ti bouk w'ap pale m' lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 22, text = "Kouri vit ale. Mwen p'ap ka fè anyen toutotan ou poko rive la. Se poutèt sa yo rele ti bouk la Zoa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 23, text = "Solèy te fèk ap leve lè Lòt rive Zoa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 24, text = "Lè sa a, Seyè a fè yon sèl lapli souf ak dife soti nan syèl la tonbe sou Sodòm ak Gomò. Wi, se Seyè a menm ki te fè sa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 25, text = "Li detwi de lavil sa yo ak tout plenn lan ansanm ak tout moun ki te rete nan lavil yo ak tout plant ki t'ap pouse nan tè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 26, text = "Men, madan Lòt vire gade dèyè. Lamenm li tounen yon gwo estati sèl.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 27, text = "Nan granmaten, Abraram leve, li ale kote li te kanpe ap pale ak Seyè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 28, text = "Li voye je l' bò Sodòm ak Gomò, li wè tout plenn lan. Epi li rete konsa li wè gwo lafimen ap moute soti nan tè a tankou lafimen k'ap leve nan yon gwo founo dife.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 29, text = "Se konsa, lè Bondye t'ap detwi lavil yo nan plenn lan, li chonje Abraram. Li fè Lòt chape anba malè li tapral lage sou lavil kote li te rete a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 30, text = "Men Lòt te pè rete nan bouk Zoa a. Se konsa, li menm ak de pitit li yo, yo soti Zoa, yo moute, y al rete nan mòn yo. Yo fè kay yo nan yon gwo twou wòch.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 31, text = "Pi gran fi a di pi piti a. Papa nou ap fin granmoun. Pa gen gason nan peyi a pou marye ak nou pou nou ka fè pitit jan sa fèt toupatou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 32, text = "Vini non. Annou fè papa bwè diven jouk li sou. Apre sa, n'a kouche avè l'. Konsa, n'a fè pitit pou papa nou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 33, text = "Menm jou sa a, lè aswè rive, yo fè papa yo bwè diven jouk li sou. Pi gran fi a kouche ak papa l'. Men, papa a te sitèlman sou, li pa t' konn anyen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 34, text = "Nan denmen, pi gran an di pi piti a. Yèswa, mwen te kouche ak papa m'. Aswè a se tout pa ou: N'ap fè l' bwè diven ankò jouk li sou. Epi w'a al kouche avè l', pou nou de nou kapab fè pitit pou papa nou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 35, text = "Se konsa, lè aswè rive, yo fè papa a bwè diven ankò jouk li sou. Epi pi piti a kouche avè l'. Men, fwa sa a ankò, Lòt pa t' konnen anyen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 36, text = "Se konsa de pitit fi Lòt yo vin ansent pou papa yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 37, text = "Pi gran an fè yon pitit gason, li rele l' Moab. Se li menm ki zansèt moun Moab yo ki la jouk koulye a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 19, verseNumber = 38, text = "Pi piti a tout fè yon pitit gason. Li rele l' Bennami. Se li menm ki zansèt moun Amon yo ki la jouk jòdi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 20, verseNumber = 1, text = "Abraram kite Manmre, li pati, li ale Negèv, li rete ant Kadès ak Chour kote li moute kay li. Pandan tout tan li t'ap viv nan peyi Gera a,", bookId = 1),
        Verse(book = "Jenèz", chapter = 20, verseNumber = 2, text = "li t'ap di se sè li Sara te ye. Se konsa, Abimelèk, wa peyi Gera a, fè yo mennen Sara ba li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 20, verseNumber = 3, text = "Men pandan lannwit, Abimelèk fè yon rèv, li wè Bondye parèt devan li. Bondye di l'. Gade non, monchè. Ou pral mouri tande, paske Sara se yon madan marye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 20, verseNumber = 4, text = "Men, Abimelèk pa t' gen tan kouche avè Sara. Li di. Mèt, èske w'ap kite yon pèp inonsan peri?", bookId = 1),
        Verse(book = "Jenèz", chapter = 20, verseNumber = 5, text = "Se Abraram ki di m' se sè li Sara ye. Sara pou tèt pa l' di m' se frè li Abraram ye. Mwen fè sa m' fè a san ankenn move lide. Mwen konnen mwen pa fè anyen ki mal.", bookId = 1),
        Verse(book = "Jenèz", chapter = 20, verseNumber = 6, text = "Bondye reponn li nan rèv la. Wi. Mwen konnen ou fè sa ou fè a san ankenn move lide dèyè tèt ou. Se poutèt sa mwen pa kite ou fè peche sa a kont mwen. Mwen pa kite ou fè madanm lan anyen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 20, verseNumber = 7, text = "Men sa pou ou fè: renmèt nonm lan madanm li. Se yon pwofèt Bondye li ye. La lapriyè pou ou pou ou pa mouri. Men, si ou pa renmèt li, mwen tout di ou nou pral mouri, ou menm ansanm ak tout fanmi ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 20, verseNumber = 8, text = "Nan maten, bonè bonè, Abimelèk rele tout domestik li yo, li rakonte yo tout bagay. Yo tout yo te pè anpil.", bookId = 1),
        Verse(book = "Jenèz", chapter = 20, verseNumber = 9, text = "Lèfini, Abimelèk rele Abraram, li di l'. Kisa ou fè nou konsa? Kisa m' fè ou pou ou ta lakòz yon gwo malè konsa tonbe sou mwen ak sou peyi a? Sa ou fè nou la a, se bagay moun pa gen dwa fè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 20, verseNumber = 10, text = "Abimelèk di Abraram ankò. Poukisa ou fè sa ou fè a?", bookId = 1),
        Verse(book = "Jenèz", chapter = 20, verseNumber = 11, text = "Abraram reponn li. Mwen te di nan kè m' pa gen moun ki gen krentif pou Bondye bò isit la. Mwen tè kwè yo ta ka touye m' poutèt madanm mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 20, verseNumber = 12, text = "Men, se vre wi, se sè m' li ye. Nou menm papa, men nou pa menm manman. Epi se madanm mwen li ye tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 20, verseNumber = 13, text = "Se konsa, lè Bondye fè m' kite lakay papa m' pou m' al nan peyi etranje yo, mwen di Sara: m'ap mande ou pou rann mwen yon sèvis? Si ou renmen m' vre, tanpri, kote ou pase, se pou di se frè ou mwen ye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 20, verseNumber = 14, text = "Lè sa a, Abimelèk renmèt Sara bay Abraram. Anmenmtan li ba li mouton, bèf ak domestik, fanm kou gason, pou sèvi l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 20, verseNumber = 15, text = "Li di Abraram. Gade! tout peyi m' lan devan ou. Rete kote ki fè ou plezi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 20, verseNumber = 16, text = "Epi li di Sara. Mwen bay frè ou la mil (1.000) pyès lajan. Se pou sa ka fè moun ki la avè ou yo bliye sak te rive ou. Konsa, tout moun va konnen ou pa t' fè anyen ki mal.", bookId = 1),
        Verse(book = "Jenèz", chapter = 20, verseNumber = 17, text = "-", bookId = 1),
        Verse(book = "Jenèz", chapter = 20, verseNumber = 18, text = "Poutèt sa ki te rive Sara, madanm Abraram lan, Seyè a te fè tout fanm lakay Abimelèk pa t' kapab fè pitit. Abraram lapriyè pou Abimelèk, epi Bondye geri li. Bondye geri madanm li tout ansanm ak medam k'ap travay lakay li pou yo kapab fè pitit ankò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 1, text = "Seyè a fè Sara favè, jan l' te di l' la. Li fè sa l' te pwomèt li a rive vre.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 2, text = "Sara vin ansent. Atout li te fin vye granmoun lan, li fè yon pitit gason pou Abraram, nan dat Bondye te di l' la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 3, text = "Abraram rele pitit gason Sara te fè pou li a Izarak.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 4, text = "Ti gason an te gen wit jou lè Abraram sikonsi l', jan Bondye te ba li lòd la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 5, text = "Abraram te gen santan sou tèt li lè Izarak, pitit li a, te fèt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 6, text = "Sara di konsa. Bondye fè m' bagay ki fè m' ri. tout moun ki tande sa pral ri avè m' tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 7, text = "Apre sa, li di ankò: -Ki moun ki ta di Abraram yon jou Sara gen pou bay timoun tete? Men, atout li fin vye a, mwen fè yon pitit gason pou li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 8, text = "Ti gason an grandi, li sevre. Jou yo sevre l' la, Abraram fè yon gwo fèt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 9, text = "Yon jou Izmayèl, pitit Aga, fanm peyi Lejip la te fè pou Abraram lan t'ap jwe ak Izarak, pitit Sara a. Sara wè sa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 10, text = "Li di Abraram konsa: -Mete sèvant la deyò ansanm ak tout pitit li a, paske pitit sèvant sa a pa gen dwa eritye ak Izarak, pitit mwen an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 11, text = "Pawòl sa a te fè Abraram lapenn anpil, paske Izmayèl te pitit li tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 12, text = "Men, Bondye di Abraram konsa-Ou pa bezwen pran lapenn pou ti gason an ak pou Aga, sèvant ou a. Ou mèt fè tout sa Sara di ou fè a, paske se Izarak ki pral ba ou pitit pitit mwen pwomèt ou yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 13, text = "M'ap bay pitit sèvant lan anpil pitit pitit. M'ap fè l' tounen yon nasyon, paske se pitit ou li ye tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 14, text = "Nan denmen Abraram leve bonè, li pran pen ak yon sak an po bèt plen dlo, li bay Aga. Li ede l' mete yo sou tèt li. Li ba li pitit la, li fè l' ale kite kay la. Aga pati, li mache, li mache, jouk li pèdi nan dezè Bècheba a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 15, text = "Lè dlo nan sak la fini, li kite pitit la anba yon touf raje.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 16, text = "li ale, li chita pi devan, yon bon ti distans, li di nan kè l' -Mwen pa ka rete ap gade pitit mwen an ap mouri konsa. Pandan li chita konsa, pitit la pran rele.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 17, text = "Bondye tande rèl pitit la. Zanj Bondye a rete nan syèl la, li pale ak Aga, li di l' konsa-Sa ou genyen, Aga? Ou pa bezwen pè. Kote Bondye ye a, li tande rèl ti pitit la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 18, text = "Leve non, pran ti pitit la, kenbe l'. M'ap fè pitit pitit li yo tounen yon gwo nasyon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 19, text = "Bondye louvri je Aga. Aga wè yon pi. li ale, li plen sak an po a dlo. Li bay ti pitit la bwè dlo kont kò l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 20, text = "Bondye te avèk ti pitit la. Li grandi, li rete nan dezè a. Li te rive konn tire flèch nan banza ak anpil ladrès.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 21, text = "Se nan dezè Paran li te rete. Manman l' te chwazi yon madanm pou li nan jenn fi peyi Lejip yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 22, text = "Lè sa a, Abimelèk ale ansanm avek Pikòl, kòmandan lame li a, li pale ak Abraram. Li di l' konsa-Bondye avè ou nan tout sa w'ap fè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 23, text = "Koulye a, fè sèman, isit la menm, devan Bondye, ou p'ap janm twonpe ni mwen menm, ni pitit mwen yo, ni pitit pitit mwen yo. Mwen te aji byen avè ou. Pwomèt w'ap aji byen avè m' tou, epi w'ap sèvi byen ak tout moun nan peyi kote ou rete a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 24, text = "Abraram reponn. -M' fè sèman.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 25, text = "Men Abraram te fè Abimelèk repwòch pou yon pi li domestik Abimelèk yo te pran pa fòs.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 26, text = "Abimelèk di l' -Mwen pa konnen ki moun ki fè sa. Ni tou, ou pa t' janm di m' anyen sou sa. Se koulye a m'ap tande koze a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 27, text = "Abraram pran kèk mouton ak kèk bèf li bay Abimelèk. Konsa, yo pase kontra yonn ak lòt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 28, text = "Abraram pran sèt mouton nan bann mouton l' yo, li mete yo sou kote.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 29, text = "Abimelèk mande l' -Poukisa ou mete sèt mouton sa yo sou kote.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 30, text = "Abraram reponn li-Asepte sèt mouton sa yo. Si ou asepte yo, sa vle di ou rekonèt devan tout moun se mwen menm ki te fouye pi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 31, text = "Se poutèt sa yo rele anplasman an Bècheba, paske se la menm yo te sèmante yonn bay lòt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 32, text = "Se Bècheba yo te pase kontra yonn ak lòt. Apre sa, Abimelèk leve, li tounen nan peyi moun Filisti yo, ansanm ak Pikòl, kòmandan lame li a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 33, text = "Se la Bècheba Abraram plante yon pye tonmaren. Lèfini li fè sèvis pou Seyè a, Bondye ki la pou tout tan an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 21, verseNumber = 34, text = "Apre sa, Abraram rete kèk lanne ankò nan peyi Filisti a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 1, text = "Apre tout bagay sa yo, Bondye sonde Abraram pou wè sou ki pye li ye avè l'. Bondye rele l' -Abraram! Abraram! Abraram reponn-Men mwen wi!", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 2, text = "Bondye di l': -Pran Izarak, pitit ou a, sèl pitit gason ou genyen an, pitit ou renmen anpil la. Ale nan peyi Morija, w'a moute sou tèt mòn mwen pral moutre ou la. Lè w'a rive la, w'a touye l'. Apre sa, w'a boule l' nèt pou mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 3, text = "Nan denmen maten, bonè bonè, Abraram leve, li sele bourik li, li pran Izarak ansanm ak de nan domestik li yo. Li fann kèk moso bwa pou l' fè dife pou boule vyann bèt l'ap ofri a. Epi li pati nan direksyon kote Bondye te di l' la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 4, text = "Sou twa jou, Abraram gade, li wè kote a yon bon ti bout devan l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 5, text = "Abraram di domestik li yo. -Nou menm, mesye, rete isit la ak bourik la. Mwen menm ak ti gason an, nou pral jouk lòt bò a, pou nou fè sèvis pou Bondye. Apre sa, n'a tounen vin jwenn nou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 6, text = "Abraram pran bwa pou fè dife a, li bay Izarak pote li. Li menm, li pote bagay pou limen dife a ansanm ak yon kouto nan men l'. Yo tout de pati ansanm.", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 7, text = "Pandan y'ap mache konsa, Izarak di Abraram: -Papa! Abraram reponn: -Wi, pitit mwen! Izarak mande l': -Mwen wè ou gen dife ak bwa. Men, kote mouton pou boule a?", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 8, text = "Abraram reponn: -Pitit mwen, se sou kont Bondye sa ye. Yo toude t'ap kontinye mache ansanm.", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 9, text = "Lè yo rive kote Bondye te di l' la, Abraram moute yon lotèl, li ranje bwa yo sou li. Li mare Izarak, pitit gason l' lan, li mete l' sou lotèl la, anwo bwa yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 10, text = "Apre sa, li lonje men l', li pran kouto a pou l' koupe kou ti gason an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 11, text = "Men, zanj Bondye a rete nan syèl la, li rele l': -Abraram! Abraram! Abraram reponn. -Men mwen wi!", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 12, text = "Zanj lan di l' -Pa leve men ou sou ti gason an. Pa fè l' anyen. Koulye a mwen konnen ou gen krentif pou Bondye vre, paske ou pa t' derefize touye sèl pitit gason ou lan pou mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 13, text = "Abraram voye je l', li wè yon belye mouton ki te gen kòn li yo makònen nan yon lyann. li ale, li pran mouton an, li touye l', li boule li nèt sou lotèl la pou Bondye nan plas pitit li a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 14, text = "Abraram rele kote sa a: Se sou kont Seyè a sa ye. Se poutèt sa, jouk jòdi a, moun ap repete: Sou mòn Seyè a, tout bagay sou kont li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 15, text = "Zanj Bondye a rete nan syèl la, li pale ak Abraram yon dezyèm fwa, li di l' konsa:", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 16, text = "-Mwen sèmante sou tèt mwen. Se mwen menm Seyè a ki di sa. Mwen gen pou m' beni ou anpil poutèt sa ou fè a. Ou pa t' refize ban mwen pitit ou a, sèl pitit gason ou genyen an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 17, text = "Mwen pwomèt pou m' ba ou anpil pitit pitit. Y'ap tankou zetwal nan syèl la, tankou grenn sab bò lanmè. Y'a bat tout lènmi yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 18, text = "Gremesi tout pitit pitit ou yo, tout nasyon sou latè pral jwenn benediksyon. Wi, yo tout, paske ou te fè sa m' te mande ou fè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 19, text = "Abraram tounen bò kote domestik li yo, domestik yo pati ansanm avè l' pou peyi Bècheba, kote Abraram te rete a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 20, text = "Apre tout bagay sa yo, yo vin di Abraram konsa: -Tande non. Milka fè pitit tout wi pou Nak, frè ou la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 21, text = "Premye pitit la rele Ouz. Apre li, vini Bouz, Kemwèl, papa Aram,", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 22, text = "Kesèd, Azò, Pildach, Jidlaf ak Betwèl.", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 23, text = "Se Betwèl ki papa Rebeka. Se wit gason sa yo Milka te fè pou Nakò, frè Abraram lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 22, verseNumber = 24, text = "Reouma, fanm kay Nakò a te fè pitit tout pou li: se te Tebak, Gam, Tach ak Maka.", bookId = 1),
        Verse(book = "Jenèz", chapter = 23, verseNumber = 1, text = "Sara viv sanvennsetan (127 an).", bookId = 1),
        Verse(book = "Jenèz", chapter = 23, verseNumber = 2, text = "Li mouri yon kote yo rele Kiriyat Aba osinon Ebwon nan peyi Kanaran. Abraram pran lapenn pou lanmò Sara, li plenn sò li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 23, verseNumber = 3, text = "Abraram leve bò kote kadav la, li ale pale ak moun Et yo. Li di yo konsa:", bookId = 1),
        Verse(book = "Jenèz", chapter = 23, verseNumber = 4, text = "-Se etranje mwen ye, se depasaj mwen ye nan mitan nou. Vann mwen yon anplasman pou m' ka antere madanm mwen, konsa m'a wete kadav la devan je m'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 23, verseNumber = 5, text = "Moun Et yo reponn Abraram, yo di l' konsa:", bookId = 1),
        Verse(book = "Jenèz", chapter = 23, verseNumber = 6, text = "-Mèt, koute sa n'ap di ou. Ou se yon gwonèg Bondye voye nan mitan nou. Chwazi yonn nan pi bon kavo nou yo pou antere madanm ou. Pa gen yonn nan nou ki pou ta refize ba ou kavo li pou antere madanm ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 23, verseNumber = 7, text = "Abraram kanpe. Pa respè pou moun Et yo, li bese tèt li byen ba devan yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 23, verseNumber = 8, text = "Li di yo: -Si nou dakò pou m' antere madanm mwen isit la, pou m' wete kadav li devan je m', koute sa m'ap di nou. Nou konnen Efwon, pitit gason Zoka a? Pale avè l' pou mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 23, verseNumber = 9, text = "Mande l' pou l' vann mwen twou wòch Makpela a ki pou li nan bout jaden l' lan. Mande l' pou l' vann mwen li pou pri li vo, pou sa ka sèvi m' simityè isit la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 23, verseNumber = 10, text = "Efwon te chita la avèk lòt moun Et yo, bò pòtay lavil la, kote moun yo konn reyini an. Devan moun Et yo, devan tout moun ki t'ap pase bò pòtay la, Efwon reponn Abraram. Li di li:", bookId = 1),
        Verse(book = "Jenèz", chapter = 23, verseNumber = 11, text = "-Non, mèt! Koute sa m'ap di ou: Mwen fè ou kado jaden an ak tout twou wòch ki ladan l' lan. Mwen fè ou kado l' devan tout moun peyi m' yo. M'ap ba ou l' pou ou ka antere madanm ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 23, verseNumber = 12, text = "Men, Abraram bese tèt li byen ba devan moun Et yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 23, verseNumber = 13, text = "Li pale ak Efwon pou tout moun ka tande. Li di l': -Koute sa m'ap di ou: M'ap achte tout jaden an nan men ou pou pri li vo. Tanpri, asepte lajan m'ap ba ou pou li a. Se lè sa a m'a antere madanm mwen ladan l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 23, verseNumber = 14, text = "Efwon reponn Abraram: -Mèt, tanpri koute sa m'ap di ou:", bookId = 1),
        Verse(book = "Jenèz", chapter = 23, verseNumber = 15, text = "Yon moso tè ki vo katsan (400) pyès lò, pa gen rezon pou n'ap diskite pou sa. Antere madanm ou sou li non!", bookId = 1),
        Verse(book = "Jenèz", chapter = 23, verseNumber = 16, text = "Abraram dakò ak sa Efwon di l' la. Li peze lajan an, li bay Efwon li devan tout moun Et yo. Wi, li ba li katsan (400) pyès lò dapre jan kòmèsan yo te sèvi nan peyi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 23, verseNumber = 17, text = "Se konsa, moso tè Efwon te gen Makpela a, anfas peyi Manmre a, ansanm ak tout twou wòch la ak tout pyebwa ki nan jaden an, jouk sou lizyè li,", bookId = 1),
        Verse(book = "Jenèz", chapter = 23, verseNumber = 18, text = "yo vin pou Abraram, devan tout moun Et yo, devan tout moun ki te bò pòtay la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 23, verseNumber = 19, text = "Apre sa, Abraram antere Sara, madanm li, nan twou wòch ki te nan jaden Makpela a, anfas Manmre yo rele Ebwon an, nan peyi Kanaran.", bookId = 1),
        Verse(book = "Jenèz", chapter = 23, verseNumber = 20, text = "Se konsa, Abraram achte jaden an ak tout twou wòch ki te ladan l' lan, nan men moun Et yo, li fè l' sèvi simityè pou li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 1, text = "Abraram te fin vye. Li te antre nan granmoun. Seyè a te beni Abraram nan tout bagay.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 2, text = "Abraram te gen yon domestik ki te pi ansyen pase tout lòt yo. Se li menm ki te jeran reskonsab tout byen li yo. Abraram di l' konsa: -Men, mete men ou nan fant janm mwen, fè sèman.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 3, text = "Mwen vle pou ou fè sèman sou Seyè a, Bondye syèl la ak Bondye latè a, pou ou pa chwazi yon madanm pou pitit gason m' lan nan medam k'ap viv nan peyi Kanaran kote m' rete a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 4, text = "Men, se nan peyi pa m' pou ou ale, pou ou chwazi pami moun menm ras ak mwen yo yon madanm pou Izarak, pitit gason m' lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 5, text = "Domestik la mande l': -Kisa pou m' fè si fi a pa vle kite peyi l' pou l' vin avè m' nan peyi sa a? Eske se pou m' mennen pitit gason ou lan ale nan peyi kote ou te soti a?", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 6, text = "Abraram reponn li: -Non, non, non! Pa janm mennen pitit mwen an laba a!", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 7, text = "Seyè a, Bondye syèl la, te pran m' fè m' soti lakay papa m' ak nan peyi fanmi mwen. Li pale avè m'. Li fè m' sèman l'ap bay pitit pitit mwen yo peyi sa a. Enben, se li menm ki va fè zanj li pran devan ou, pou ou chwazi yon madanm nan moun laba yo pou pitit gason m' lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 8, text = "Si madanm lan pa vle vin avè ou, w'a konnen ou kit ak sèman ou te fè m' lan. Sèlman, nenpòt jan, pa mennen pitit gason m' lan laba a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 9, text = "Domestik la mete men l' nan fant janm Abraram, mèt li, epi li sèmante pou l' fè sa l' mande l' fè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 10, text = "Domestik la pran dis chamo nan chamo mèt li yo. Li pran yon kantite bèl bagay ki koute chè, li chaje chamo yo. Li leve, li pati, li ale lavil kote Nakò rete a nan peyi Mezopotami.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 11, text = "Lè aswè rive, li fè chamo yo kouche bò pi ki lòt bò pòtay lavil la. Se te lè ti medam yo tè konn vin tire dlo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 12, text = "Li lapriyè, li di: -Seyè, ou menm ki Bondye Abraram, mèt mwen, tanpri, fè m' jwenn jòdi a sa m'ap chache a. Moutre jan ou bon pou Abraram, mèt mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 13, text = "Men mwen kanpe bò pi a, kote medam yo ap vin chache dlo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 14, text = "Mwen mande ou pou jenn fi ki va reponn mwen l'ap ban m' bwè lèfini l'ap bay chamo m' yo bwè tou, lè m'a di l': Tanpri, bese krich ou a ban m' ti gout dlo pou m' bwè, fè se li menm ou chwazi pou Izarak, sèvitè ou la. Lè sa a, m'a konnen jan ou bon pou mèt mwen vre.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 15, text = "Li t'ap pale toujou lè Rebeka parèt avèk yon krich sou zepòl li. Rebeka te pitit Betwèl. Betwèl sa a te pitit gason Milka ki te marye ak Nakò, frè Abraram lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 16, text = "Se te yon jenn fi. Li te bèl anpil, li te tifi. Li desann nan sous la, li plen krich li. Epi li moute soti deyò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 17, text = "Domestik la kouri al jwenn li, li di l' konsa: -Tanpri, ban m' ti gout dlo nan krich ou a non.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 18, text = "Rebeka reponn li: -Wi. Bwè non, msye. Li desann krich la soti sou zepòl li, li kenbe l' nan men l' pou fè nonm lan bwè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 19, text = "Lè nonm lan fin bwè, jenn fi a di l': -Mwen pral pran dlo pou chamo ou yo, pou yo ka bwè kont yo tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 20, text = "Li prese vide rès dlo krich la nan yon ti basen pou chamo yo bwè, epi li kouri desann nan sous la al chache dlo jouk tout chamo yo fin bwè kont yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 21, text = "Nonm lan menm te sezi. Li t'ap gade fi a san l' pa di anyen, li t'ap tann pou l' wè si Seyè a pa t' fè l' vwayaje pou gremesi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 22, text = "Lè chamo yo fin bwè, nonm lan pran yon bèl zanno lò ki peze sis gram, li pase l' nan nen Rebeka. Li pran de bèl braslè ki peze san gram, li mete yo nan bra li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 23, text = "Epi li mande l': -Pitit ki moun ou ye? Tanpri, di m' non. Eske gen kote lakay papa ou pou m' pase nwit la avèk chamo m' yo?", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 24, text = "Jenn fi a reponn: -Mwen se pitit fi Betwèl, yonn nan pitit gason Milka ak Nakò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 25, text = "Li di l' anko: -Lakay nou, nou gen kont pay zèb pou chamo ou yo. Wa jwenn kote pou ou pase nwit la tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 26, text = "Lè sa a, nonm lan tonbe ajenou, li bese tèt li jouk atè devan Seyè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 27, text = "Li di: -Lwanj pou Seyè a, Bondye Abraram, mèt mwen an. Li gen pitye pou li, li kenbe pwomès li te fè l' la. Li mennen m' tout dwat lakay fanmi mèt mwen an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 28, text = "Jenn fi a kouri lakay manman l'. Li rakonte tout sa ki te rive.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 29, text = "Rebeka te gen yon frè yo rele Laban. Laban kouri deyò al jwenn nonm lan bò sous la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 30, text = "Li te wè zanno a nan nen sè li ak braslè yo nan bra l', li te tande l' ap rakonte sa nonm lan te di l'. Lamenm li al jwenn nonm lan ki te kanpe bò sous la ansanm ak chamo l' yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 31, text = "Laban di l': -Antre non. Ou se yon nonm Seyè a beni. Poukisa ou rete deyò a konsa? Mwen pare yon kote pou ou nan kay la. Gen plas pou chamo ou yo tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 32, text = "Nonm lan antre nan kay la. Laban desele chamo yo. Li fè ba yo pay ak zèb. Yo pare dlo pou nonm lan lave pye l', ansanm ak moun ki te avè l' yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 33, text = "Lèfini, yo sèvi yo manje. Men nonm lan di: -Anvan m' manje, se pou m' di sa m' gen pou m' di a. Laban di l': -Bon. Pale non.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 34, text = "Msye pran lapawòl, li di: -Mwen se domestik Abraram.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 35, text = "Seyè a voye anpil benediksyon sou mèt mwen. Li fè l' vin grannèg. Li ba li mouton, bèf, lajan, lò, domestik, sèvant, chamo, bourik.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 36, text = "Sara, madanm mèt mwen, te fin vye granmoun lè li te resi fè yon pitit gason pou li. Mèt mwen bay pitit sa a tout sa li genyen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 37, text = "Mèt mwen fè m' fè sèman, li di m' piga m' chwazi yon madanm pou pitit gason l' lan nan medam moun peyi Kanaran kote l' rete a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 38, text = "Men se pou m ale lakay papa l' pou mwen chwazi yon madanm nan ras li pou pitit gason l' lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 39, text = "Lè sa a, mwen di mèt mwen: Bon, si fi a pa vle vini avè m', kisa pou m' fè?", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 40, text = "Li reponn mwen: Seyè a ki wè jan mwen toujou obeyi l' va voye zanj li avè ou. Li p'ap fè ou vwayaje pou gremesi. Ou va chwazi yon madanm nan fanmi papa m' pou gason m' lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 41, text = "Si ou fè sa, w'a kit ak sèman ou te fè m' lan. Konsa tou, si ou rive kay fanmi m', si yo menm yo refize, w'a kit ak sèman ou te fè m' lan tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 42, text = "Jòdi a, lè m' rive bò sous dlo a, mwen di: Seyè, Bondye Abraram, mèt mwen an, si sa fè ou plezi, fè m' pa vwayaje pou gremesi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 43, text = "Gade, m'ap rete kanpe bò sous dlo a. Lè m'a wè yon jenn fi k'ap vin chache dlo nan pi a, m'a va di l': Tanpri, ban m' ti gout dlo nan krich ou a pou m' bwè. Si li reponn mwen:", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 44, text = "Ou mèt bwè! Apre sa, m'a bay chamo ou yo bwè tou, tanpri fè se li menm ou chwazi pou madanm pitit mèt mwen an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 45, text = "Mwen pa t' menm fin di pawòl sa yo nan kè m', lè m' wè Rebeka rive ak krich li sou zepòl li. Li desann nan sous la, li pran dlo epi mwen di l': Tanpri, ban m' ti gout dlo pou m' bwè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 46, text = "Lamenm, li desann krich la soti sou zepòl li, li di m': Bwè non. Apre sa, m'a bay chamo ou yo bwè tou. Mwen bwè, epi li bay chamo m' yo bwè tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 47, text = "Mwen mande l': Pitit ki moun ou ye? Li reponn mwen: Mwen se pitit fi Betwèl, pitit gason Milka ak Nakò. Lè sa a, mwen mete zanno a nan nen l', mwen mete braslè sa yo nan bra l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 48, text = "Mwen tonbe ajenou, mwen bese tèt mwen jouk atè devan Seyè a, mwen fè lwanj Seyè a, Bondye Abraram, mèt mwen an, paske li mennen m' tout dwat lakay frè mèt mwen an, kote mwen jwenn yon madanm pou pitit gason l' lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 49, text = "Alèkile, si nou vle aji byen avè l', si nou vle fè l' konfyans, fè m' konnen. Si nou pa dakò, fè m' konnen tou, pou m' ka konnen sa pou m' fè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 50, text = "Laban ak Betwèl reponn: -Bagay sa a se travay Seyè a, Bondye a. Nou pa gen anyen pou n' di nan sa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 51, text = "Men Rebeka devan ou, pran li, mennen l' ale pou l' vin madanm pitit gason mèt ou a, jan Bondye te di l' la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 52, text = "Lè domestik Abraram lan tande sa, li tonbe ajenou, li bese tèt li jouk atè devan Seyè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 53, text = "Apre sa, li pran rale bèl bijou fèt an ajan ak an lò ansanm ak rad, li bay Rebeka. Li te bay frè a ak manman an anpil bèl kado tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 54, text = "Apre sa, domestik Abraram lan manje ansanm ak moun ki te avè l' yo, yo bwè, yo dòmi. Nan maten, lè yo leve, domestik la di: -Kite m' tounen al jwenn mèt mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 55, text = "Men, frè a avèk manman an di konsa: -Kite fi a pase dis jou ankò avèk nou non. Apre sa, n'a pati.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 56, text = "Li reponn yo: -Pa ban m' reta. Seyè a pa fè m' vwayaje pou gremesi. Tanpri, kite m' al jwenn mèt mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 57, text = "Yo di l': -Bon. Ann rele fi a. Ann mande l' sa l' di nan sa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 58, text = "Yo rele Rebeka, yo mande l': -Eske ou vle ale ak nonm sa a? Li reponn: -Wi, mwen vle ale.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 59, text = "Se konsa yo kite Rebeka, sè yo a, ansanm ak bòn ki te nouris li a pati avèk domestik Abraram lan, ansanm ak moun ki te vin avè l' yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 60, text = "Yo beni Rebeka, yo di l': -Rebeka, sè nou, nou mande Bondye pou ou fè anpil anpil pitit. Se pou pitit pitit ou yo bat tout lènmi yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 61, text = "Apre sa, Rebeka avèk tout sèvant li yo leve, yo moute chamo yo, yo pati avèk nonm lan. Domestik la pran l', li pati ak li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 62, text = "Lè sa a, Izarak te vini nan dezè a, bò kote Pi moun vivan ki wè m' lan. Li te rete nan peyi Negèv.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 63, text = "Yon jou swa, Izarak t'ap pwonmennen deyò nan jaden li, li t'ap kalkile. Li leve je l', li gade, li wè kèk chamo ki t'ap vini.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 64, text = "Menm lè a tou, Rebeka leve je l', li wè Izarak. Li desann chamo a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 65, text = "Li mande domestik la: -Ki msye sa a k'ap mache vin jwenn nou nan jaden an? Domestik la reponn li: -Se mèt mwen an wi. Rebeka pran yon vwal, li bouche figi l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 66, text = "Domestik la rakonte Izarak tout sa li te fè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 24, verseNumber = 67, text = "Izarak mennen Rebeka lakay li, kay ki te pou Sara, manman l' lan. Li pran l' pou madanm li. Izarak te renmen Rebeka. Se konsa li te jwenn konsolasyon, apre li te fin pèdi manman l' lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 1, text = "Abraram te pran yon lòt fanm yo te rele Ketoura.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 2, text = "Ketoura fè sis pitit pou li: Zimran, Joksan, Medan, Madyan, Jisbak ak Swak.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 3, text = "Joksan te papa Seba ak Dedan. Men pitit Dedan yo: Se te moun Achou yo, moun Letouch yo ak moun Lemou yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 4, text = "Men pitit Madyan yo: Se te Efa, Efe, Enòk, Abida ak Elda. Se tout moun sa yo ki te pitit ak pitit pitit Ketoura.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 5, text = "Abraram kite tout byen l' yo pou Izarak.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 6, text = "Men anvan l' mouri, li te bay pitit li te fè ak lòt fanm kay yo kèk kado. Apre sa, li fè yo pati, li voye yo byen lwen Izarak, pitit gason l' lan, li voye yo nan peyi kote solèy leve a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 7, text = "Abraram te viv sanswasannkenzan (175 an).", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 8, text = "Abraram te fin granmoun, li te wè kont jou l', li te pase vye jou l' yo san pwoblèm. Apre sa li mouri, li al jwenn moun li yo ki te mouri deja.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 9, text = "Izarak ak Izmayèl, pitit li yo, antere l' nan twou wòch Makpela a, nan jaden Efwon, pitit Zoka, yon moun Et, anfas Manmre.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 10, text = "Se jaden sa a Abraram te achte nan men mesye Et yo. Se la yo te antere Abraram ak Sara, madanm li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 11, text = "Apre Abraram mouri, Bondye te beni Izarak, pitit gason l' lan, ki te rete toupre Pi moun vivan ki wè m' lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 12, text = "Men pitit pitit Izmayèl, pitit Abraram lan. Se Aga, moun peyi Lejip, sèvant Sara, ki te fè pitit sa a pou Abraram.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 13, text = "Men non pitit Izmayèl yo. N'ap konmanse ak pi gran an pou rive sou pi piti a. Nebajòt te premye pitit Izmayèl. Apre li vini Keda, Adbeyèl, Mibsam,", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 14, text = "Michma, Douma, Masa,", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 15, text = "Adad, Tema, Jetou, Nafich ak Kedma.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 16, text = "Se yo ki te pitit Izmayèl. Se konsa yo te rele yo ansanm ak tout katye kote yo te rete ak kote yo te moute tant yo. Sa te fè douz chèf, chak ak nasyon pa yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 17, text = "Izmayèl te gen santrannsetan (137 an) lè l' mouri. Y al antere l' menm kote ak moun li yo ki te mouri deja.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 18, text = "Pitit pitit Izmayèl yo te rete sou teritwa ki konmanse depi Avila rive jouk Chou, anfas peyi Lejip sou bò solèy leve a, anvan ou pran peyi Lasiri. Yo t'ap viv pou kont yo. Yo pa t' mele ak rès fanmi yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 19, text = "Men istwa Izarak, pitit Abraram.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 20, text = "Abraram te papa Izarak. Izarak te gen karantan lè li marye ak Rebeka ki te pitit fi Betwèl, moun lavil Aram, ki te rete nan peyi Mezopotami an. Rebeka te sè Laban, moun lavil Aram.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 21, text = "Madanm Izarak pa t' ka fè pitit. Izarak lapriyè Seyè a pou li, Seyè a reponn li. Rebeka, madanm li, vin ansent.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 22, text = "De ti pitit yo t'ap plede goumen nan vant li. Rebeka di: -Si se konsa sa ye, mwen pa konprann anyen? li al lapriyè Seyè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 23, text = "Seyè a reponn li: -Ou gen de nasyon nan vant ou. W'ap fè de pèp: chak ap pran bò pa yo. Yonn p'ap vle wè lòt. Yonn ap pi gwonèg pase lòt. Pi gran an pral sou zòd pi piti a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 24, text = "Lè jou pou Rebeka akouche a rive, li fè de marasa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 25, text = "Premye ki te fèt la te tout wouj. Li te kouvri ak pwal sou tout kò l'. Se poutèt sa yo te rele l' Ezaou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 26, text = "Lè dezyèm lan te fèt, men li te kenbe Ezaou nan talon pye l': se poutèt sa yo rele l' Jakòb. Izarak te gen swasantan sou tèt li lè yo te fèt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 27, text = "Timoun yo grandi. Ezaou te vin yon bon chasè, li te toujou nan bwa. Men Jakòb te yon nonm byen dousman, li te renmen rete lakay.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 28, text = "Izarak te pito Ezaou, paske li te renmen manje vyann jibye, men Rebeka te pito Jakòb.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 29, text = "Yon jou, Jakòb te fin kwit yon bon bouyon, Ezaou antre sot nan jaden, li te bouke anpil.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 30, text = "Li di Jakòb konsa: -M'ap mouri grangou. Tanpri, ban m' ti gout nan bouyon pwa wouj ou a. Se poutèt sa yo te bay Ezaou yon lòt ti non. Yo te rele l' Edon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 31, text = "Men Jakòb di l': -M'ap ba ou ti gout si ou vann mwen dwa ou kòm premye pitit.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 32, text = "Ezaou reponn: -Dakò. Mwen pral mouri. Kisa dwa kòm premye pitit la ap sèvi m'?", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 33, text = "Jakòb di li: -Fè m' sèman anvan. Ezaou fè sèman ba li, li vann li dwa l' kòm premye pitit.", bookId = 1),
        Verse(book = "Jenèz", chapter = 25, verseNumber = 34, text = "Lèfini, Jakòb ba li pen ak ti gout nan bouyon pwa a. Ezaou manje, li bwè. Li leve, li pati. Konsa, Ezaou te konsidere dwa li kòm premye pitit pou anyen.", bookId = 1)
    )

    private val part3 = listOf(
        Verse(book = "Jenèz", chapter = 26, verseNumber = 1, text = "Te vin gen yon lòt grangou nan peyi a, pi rèd pase sa ki te tonbe sou peyi a nan tan Abraram lan. Lè sa a, Izarak ale yon kote yo rele Gera kay Abimelèk, wa moun Filisti yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 2, text = "Izarak fè yon vizyon, li wè Seyè a parèt devan l'. Seyè a di l': -Pa desann nan peyi Lejip, rete kote m'ap di ou rete a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 3, text = "W'a pase kèk tan nan peyi sa a. M'ap avè ou, m'ap beni ou, paske mwen pral ba ou tout tè sa a pou ou menm ak pou tout ras ou. m'a kenbe sèman mwen te fè bay Abraram, papa ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 4, text = "M'ap ba ou anpil anpil pitit tankou zetwal nan syèl la. M'ap ba yo tout tè sa yo. Gremesi pitit pitit ou yo, tout nasyon sou latè pral jwenn benediksyon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 5, text = "tout sa, paske Abraram te tande m' lè m' te pale avè l', li te swiv tout lòd mwen yo ak tout kòmandman mwen yo. Li te fè tout sa mwen mande l', li te obeyi tout lwa mwen yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 6, text = "Se konsa Izarak rete kote yo rele Gera a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 7, text = "Lè mesye ki te rete nan peyi a mande l' kisa madanm li ye pou li, li reponn yo se sè l' li ye, paske li te pè di se madanm li Rebeka te ye pou mesye yo pa t' touye l' pou yo te ka pran Rebeka ki te bèl anpil.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 8, text = "Izarak te gen kèk tan depi l' te rete la. Yon jou, Abimelek, wa moun Filisti yo, t'ap gade nan fennèt li, li te wè Izarak ki t'ap pase men sou Rebeka, madanm li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 9, text = "Lè sa a, Abimelèk voye chache Izarak. Li di l' konsa: -Gade non, monchè, se madanm ou li ye! Poukisa ou di se sè ou li ye! Izarak reponn li: -Mwen te di sa paske mwen te kwè yo ta ka touye m', si m' te di se madanm mwen li ye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 10, text = "Abimelèk di l': -Kisa ou fè nou konsa? Yonn nan mesye nou yo ta ka byen rive kouche avèk madanm ou! Se ou ki ta lakòz nou fè peche sa a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 11, text = "Se konsa Abimelèk pase lòd sa a bay tout pèp la: -Si yon moun manyen nonm sa a, osinon madanm li, y'ap touye l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 12, text = "Izarak fè jaden nan peyi a. Lè lanne a bout, li rekòlte san fwa valè sa l' te plante a, paske Seyè a te beni l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 13, text = "Msye te vin rich. Li t'ap fè lajan toujou, jouk li rive vin rich anpil anpil.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 14, text = "Li te gen kantite kabrit, mouton ak bèf, ak anpil moun ki t'ap sèvi l'. Sa te fè moun Filisti yo rayi sò li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 15, text = "Se konsa yo konble tout pi domestik Abraram yo te fouye sou tan Abraram, papa Izarak. Yo plen yo tè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 16, text = "Lèfini, Abimelèk di Izarak: -Pati, al fè wout ou! Ou pi grannèg pase nou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 17, text = "Se konsa Izarak pati kite kote l' te ye a, li ale nan Fon Gera a. Se la li moute kay li pou l' rete.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 18, text = "Li fè refouye tout pi dlo yo te fouye sou tan Abraram, papa l'. Se pi sa yo moun Filisti yo te bouche apre lanmò Abraram. Izarak ba yo menm non papa l' te ba yo a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 19, text = "Domestik Izarak yo te fouye ankò nan fon an. Yo te jwenn yon sous dlo k'ap ponpe.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 20, text = "Men, gadò mouton peyi Gera yo leve yon sèl kont avèk gadò mouton Izarak yo. Yo t'ap di: -Dlo sa a, se pou nou li ye. Se konsa Izarak rele pi a Pi dezagreman paske yo te chache l' dezagreman pou dlo a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 21, text = "Domestik Izarak yo fouye yon lòt pi ki te lakòz yo chache yo kont ankò. Se konsa Izarak rele pi a Pi ki fè lènmi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 22, text = "Lè l' wè sa, li wete kò l' kote l' te ye a, li fouye yon lòt pi pou sa pa t' fè kont. Se poutèt sa li rele pi a Pi ki pa nan kont. Li di: -Koulye a Seyè a ban nou kont espas nan peyi a pou nou pa nan kont. Se atò zafè nou pral mache nan peyi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 23, text = "Izarak pati, li moute Bècheba.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 24, text = "Menm jou sa a, nan mitan lannwit, Seyè a parèt nan yon vizyon, li di Izarak konsa: -Mwen se Bondye Abraram, papa ou. Ou pa bezwen pè anyen, paske mwen la avèk ou. M'ap beni ou, m'ap ba ou anpil pitit pitit, poutèt Abraram, sèvitè m' lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 25, text = "Izarak bati yon lotèl la, li fè sèvis pou Seyè a. Li moute kay li la. Domestik li yo fouye yon lòt pi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 26, text = "Abimelèk soti Gera, li vin wè Izarak. Li te gen avè l' Akouzat, yon bon zanmi l', ak Pikòl, kòmandan lame li a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 27, text = "Izarak mande yo: -Poukisa nou vin wè m' koulye a? Jan nou te rayi m' sa a jouk nou te rive mete m' deyò nan peyi nou an!", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 28, text = "Yo reponn li: -Koulye a nou konnen Seyè a avèk ou. Se poutèt sa nou di n'ap fè yon kontra avè ou, n'ap sèmante yonn bay lòt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 29, text = "W'ap sèmante ou p'ap janm fè nou anyen, menm jan nou pa t' janm fè ou anyen. W'ap sèmante nou te toujou aji byen avè ou. Nou kite ou ale san bri san kont. Koulye a, ou gen benediksyon Bondye sou ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 30, text = "Izarak fè gwo fèt pou yo. Yo manje, yo bwè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 31, text = "Nan granmaten, yo leve, yo sèmante yonn bay lòt. Apre sa, moun Filisti yo di Izarak orevwa. Yo separe tankou de bon zanmi, epi y al fè wout yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 32, text = "Menm jou sa a, domestik Izarak yo vin ba l' nouvèl pi yo t'ap fouye a. Yo di l': -Nou jwenn dlo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 33, text = "Izarak rele pi a Chibeya. Se poutèt sa, jouk jòdi a, yo rele lavil la Bècheba.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 34, text = "Ezaou te gen karantan lè l' marye ak Jidit, pitit fi Beri, yon moun Et. Li te gen yon lòt madanm tout yo te rele Basmat, pitit fi Elon, yon moun Et tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 26, verseNumber = 35, text = "Medam sa yo te rann Izarak ak Rebeka lavi minab.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 1, text = "Izarak te fin vye granmoun, je l' pa t' bon, li pa t' kapab wè ladan yo ankò. Li rele premye pitit li a, Ezaou, li di l' konsa: -Pitit mwen, Ezaou reponn li: -Men mwen wi, papa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 2, text = "Izarak di l': -Ou wè jan m' fin vye. Mwen pa konn ki jou m'ap mouri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 3, text = "Tanpri, pran zam ou yo, flèch ou yo ak banza ou la. Ale nan bwa a, chase jibye pou mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 4, text = "Lèfini, pare vyann lan jan ou konnen mwen renmen l' lan, pote l' ban mwen. m'a manje. Epi m'a ba ou benediksyon mwen anvan m' mouri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 5, text = "Rebeka menm t'ap tande sa Izarak t'ap di Ezaou, gason l' lan. Ezaou soti, li pati li al lachas pou papa l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 6, text = "Lè sa a, Rebeka di Jakòb, pitit li a: -Men mwen fèk tande papa ou di Ezaou, frè ou la:", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 7, text = "Al chase jibye pote pou mwen, kwit li, m'a manje. Apre sa, m'a beni ou devan Seyè a anvan m' mouri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 8, text = "Koulye a, pitit mwen, koute sa m'ap di ou: Fè sa m'ap mande ou la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 9, text = "Ale pran de jenn kabrit byen gra nan bann lan, pote yo ban mwen. m'a pare yo pou papa ou jan m' konnen li renmen l' lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 10, text = "W'a pote l' bay papa ou, la manje, la beni ou anvan l' mouri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 11, text = "Jakòb reponn manman l': -Men manman, Ezaou, frè mwen an, gen pwal sou tout kò li. Mwen menm, po pa m' lis.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 12, text = "Si papa m' manyen m', la wè se twonpe m'ap twonpe l'. Lè sa a pase li ban mwen benediksyon, la ban m' madichon pito.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 13, text = "Men manman an reponn: -Madichon la ba ou a va tonbe sou mwen, pitit mwen. Ou menm, fè sa mwen di ou fè a, al chache kabrit yo mennen ban mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 14, text = "Jakòb ale chache bèt yo, li mennen yo bay manman l'. Manman l' pare yon manje jan li konnen papa a te renmen l' lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 15, text = "Apre sa, Rebeka pran rad Ezaou, premye pitit li a, pi bèl rad Ezaou te gen lakay la, li mete yo anwo Jakòb, dezyèm pitit li a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 16, text = "Avèk po ti kabrit yo, li kouvri bra ak kou Jakòb.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 17, text = "Apre sa, li bay Jakòb manje a avèk pen li te fè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 18, text = "Jakòb al jwenn papa l', li di: -Papa. Izarak reponn li: -Men mwen, pitit mwen. Kilès nan nou ki la a?", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 19, text = "Jakòb reponn: -Se mwen menm Ezaou, premye gason ou lan. Mwen fè sa ou te di m' fè a. Leve non, chita. Manje vyann mwen pote pou ou a. Apre sa, wa ban mwen benediksyon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 20, text = "Izarak di Jakòb: -Ki jan ou fè jwenn bèt la vit konsa, pitit mwen? Jakòb reponn li: -Seyè a, Bondye ou la, ede m'. Li fè jibye a vin devan mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 21, text = "Izarak di: -Pwoche non. Vini mwen manyen ou, pitit mwen, pou m' wè si wi ou non ou se Ezaou, pitit mwen an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 22, text = "Jakòb pwoche bò kote Izarak, papa l', ki manyen l'. Epi Izarak di: -Vwa a se vwa Jakòb, men bra a se bra Ezaou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 23, text = "Li pa t' rekonèt Jakòb, paske bra li te plen pwal tankou bra Ezaou, frè li a. Izarak beni l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 24, text = "Li di l': -Se vre, se Ezaou, pitit mwen, ou ye? Jakòb reponn li: -Se mwen wi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 25, text = "Izarak di l': -Sèvi m' non. m'a manje vyann ou pote a. Apre sa, m'a beni ou. Jakòb sèvi l' manje a, li manje. Lèfini, Jakòb ba li diven, li bwè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 26, text = "Izarak, papa l', di l': -Pwoche non, pitit mwen. vin bo m'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 27, text = "Jakòb pwoche, li bo papa l'. Papa a pran sant rad ki te sou li a, epi li ba li benediksyon l'. Li di l': -Sant kò pitit mwen an tankou sant yon jaden Seyè a beni.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 28, text = "Se pou Bondye ba ou lawouze ki soti nan syèl la. Se pou l' fè jaden ou donnen anpil. Se pou l' ba ou bèl rekòt ble ak rezen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 29, text = "Se pou kantite pèp soumèt devan ou. Se pou kantite nasyon bese tèt devan ou. Se ou menm ki pou mèt frè ou yo. Se pou pitit pitit manman ou yo bese tèt devan ou. Se pou tout moun ki ba ou madichon jwenn madichon. Se pou tout moun ki beni ou jwenn benediksyon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 30, text = "Izarak te fin beni Jakòb. Jakòb te fèk kite papa li, Izarak, lè Ezaou, frè li a, antre soti lachas.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 31, text = "Li te pare yon bon plat manje, li pote l' bay papa l'. Li di l': -Leve chita non, papa. Manje vyann pitit ou pote pou ou a, pou ou ka beni l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 32, text = "Izarak, papa l', mande: -Ki moun sa a? Li reponn: -Se mwen menm, Ezaou, premye pitit gason ou lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 33, text = "Tande Izarak tande sa, li sezi, li pran tranble kou fèy bwa. Li di: -Kilès sa ki te pote ban m' manje jibye li sot chase a? Mwen fèk fin manje anvan ou rive la a. Mwen ba li benediksyon m' lan ki pou li nèt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 34, text = "Lè Ezaou tande sa, yon sèl kòlè moute l', li tonbe rele byen fò: -Beni m' tout non, papa!", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 35, text = "Izarak reponn li: -Frè ou la vini, li twonpe m'. Li pran benediksyon ki te pou ou a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 36, text = "Ezaou di: -Sa fè dezyèm fwa li pran sak pou mwen. Eske se paske li rele Jakòb la kifè l'ap pase devan m' konsa? Premye fwa a, li te pran dwa m' kòm premye pitit. Men koulye a, li pran benediksyon ki te pou mwen an! Apre sa, li di: -Men papa, èske ou pa gen yon lòt benediksyon pou mwen?", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 37, text = "Izarak reponn Ezaou: -Mwen mete l' chèf sou ou. Mwen fè tout rès fanmi an tounen moun k'ap sèvi l'. Mwen ba li mezi pwovizyon l'. Kisa m' ka fè pou ou ankò, pitit mwen?", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 38, text = "Ezaou di papa a: -Se sèl benediksyon sa a ou te genyen, papa? Tanpri, beni m' tout non, papa! Lè sa a, Ezaou pete yon sèl rèl, li kriye byen fò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 39, text = "Se konsa Izarak di l': -Latè p'ap ba ou sa l' te dwe ba ou. p'ap gen lawouze ki soti nan syèl la pou wouze jaden ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 40, text = "Se zam ou k'ap fè ou viv. W'ap sèvi frè ou la, se vre. Men, se pye poudre ou ye, w'a soti anba men l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 41, text = "Ezaou te rayi Jakòb poutèt papa a te ba li benediksyon ki te pou li a. Li di nan kè l': Papa m' pa lwen mouri. Fini yo fini antere l', m'ap touye Jakòb, frè mwen an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 42, text = "Yo vin rapòte bay Rebeka sa ki te soti nan bouch Ezaou, premye pitit gason l' lan. Li fè rele Jakòb, dezyèm pitit li a, li di l': -Koute! Ezaou, frè ou la, vle tire revanj sou ou. Li vle touye ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 43, text = "Koulye a, pitit mwen, koute sa m'ap di ou la. Leve, pati ale kay Laban, frè mwen an ki rete nan peyi Karan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 44, text = "W'a rete kèk tan la avèk li, jouk tan kòlè frè ou la va bese,", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 45, text = "jouk tan la sispann move sou ou, jouk li va bliye sa ou te fè l' la. Lè sa a, atò, m'a voye chache ou, m'a fè ou tounen. Poukisa pou m' ta pèdi tou de pitit gason m' yo yon sèl jou a?", bookId = 1),
        Verse(book = "Jenèz", chapter = 27, verseNumber = 46, text = "Rebeka di Izarak konsa: -Mwen degoute, mwen bouke ak bann fi Et sa yo. Pase pou m' ta wè Jakòb pran yonn nan moun sa yo, yonn nan bann fi Et sa yo k'ap viv nan peyi a pou madanm, pito m' mouri!", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 1, text = "Izarak rele Jakòb, li beni l'. Apre sa, li ba li lòd sa a: -Piga ou pran fi peyi Kanaran an pou madanm ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 2, text = "Leve non, ale Mezopotami lakay Betwèl, papa manman ou. W'a pran yonn nan piti fi Laban yo pou madanm. Laban, se frè manman ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 3, text = "Mwen mande Bondye ki gen tout pouvwa a pou l' beni maryaj ou, pou l' ba ou anpil pitit, pou ou tounen zansèt anpil nasyon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 4, text = "Se pou l' beni ou, ou menm ansanm ak tout pitit pitit ou yo, menm jan li te beni Abraram, pou ou ka pran posesyon peyi kote w'ap viv koulye a, peyi li te deja bay Abraram lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 5, text = "Se konsa Izarak fè Jakòb pati. Jakòb ale nan Mezopotami lakay Laban, pitit Betwèl, moun peyi Aram lan. Laban se te frè Rebeka, manman Jakòb ak Ezaou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 6, text = "Ezaou vin konnen ki jan Izarak te beni Jakòb, ki jan li te voye l' Mezopotami al chache yon madanm. Li vin konnen tout lè Izarak t'ap beni Jakòb la, li te pase l' lòd sa a: Piga ou pran fi peyi Kanaran an pou madanm ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 7, text = "Ezaou te wè Jakob te obeyi papa l' ak manman l', li te pati pou Mezopotami.", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 8, text = "Konsa, Ezaou vin wè Izarak papa l' pa t' renmen fi peyi Kanaran yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 9, text = "Li leve, li ale lakay Izmayèl, lòt pitit gason Abraram lan, li pran yon lòt madanm mete sou sa li te genyen deja yo. Li marye ak Maalat, yonn nan pitit fi Izmayèl yo. Maalat sa a, se te sè Nebajòt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 10, text = "Jakòb kite Bècheba, li pati pou Karan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 11, text = "Li rive yon kote, li rete pase nwit la la, paske sòlèy te fin kouche. Li pran yon wòch sèvi l' zòrye, epi li kouche atè a konsa pou l' dòmi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 12, text = "Li fè yon rèv. Li reve li wè yon nechèl ki te kanpe de pye l' atè ak tèt li pèdi nan syèl la. Zanj Bondye yo t'ap moute desann sou nechèl la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 13, text = "Epi li wè Seyè a kanpe anwo nechèl la. Seyè a t'ap di: -Se mwen menm, Seyè a, Bondye Abraram, zansèt ou, ak Bondye Izarak. Ou wè tè kote ou kouche a, m'ap ba ou l' pou ou menm ansanm ak tout pitit pitit ou yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 14, text = "Pitit pitit ou yo pral menm kantite ak grenn pousyè ki sou latè. Yo pral gaye nan tout direksyon, lès, lwès, nò, sid. Ou menm ak tout pitit pitit ou yo, nou pral tounen yon benediksyon pou tout moun ki sou latè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 15, text = "Pa bliye, m'ap toujou la avèk ou, m'ap voye je sou ou kote ou pase. M'ap fè ou tounen nan peyi sa a, paske mwen p'ap lage ou san m' pa fè tout sa mwen sot di ou la a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 16, text = "Jakòb leve nan dòmi an, li di: -Wè pa wè, Seyè a isit la, mwen pa t' konn sa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 17, text = "Msye vin pè, li di: -Isit la se yon kote pou moun respekte! Se pa lòt bagay, isit la se kay Bondye ak pòt syèl la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 18, text = "Jakòb leve byen bònè, li pran wòch li te fè sèvi l' zòrye a, li plante l' tankou yon bòn tè, li vide lwil sou li pou mete l' apa pou Bondye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 19, text = "Li rele kote sa a Betèl. (Anvan sa, lavil la te rele Louz.)", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 20, text = "Jakòb fè yon pwomès bay Seyè a, li di: -Si Bondye toujou kanpe avèk mwen, si li voye je sou mwen nan tout vwayaj sa m'ap fè a, si li ban m' manje pou m' manje ak rad pou m' met sou mwen,", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 21, text = "si l' fè m' tounen ak kè poze lakay papa m', Seyè a va Bondye m' vre.", bookId = 1),
        Verse(book = "Jenèz", chapter = 28, verseNumber = 22, text = "Wòch sa a mwen plante nan tè tankou bòn lan va sèvi kay pou Bondye. m'a ba ou yon dizyèm nan tout sa ou va ban mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 1, text = "Jakòb pran mache ankò, li ale nan direksyon peyi moun ki rete bò kote solèy leve a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 2, text = "Li rete konsa, li wè yon pi nan mitan savann lan. Te gen twa bann mouton ki te kouche bò pi a. Se nan pi sa a yo te konn pran dlo pou bay bèt yo bwè. Men te gen yon gwo wòch ki te bouche bouch pi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 3, text = "Lè tout bèt yo te sanble, gadò yo te met ansanm pou wete wòch la sou bouch pi a pou fè bèt yo bwè. Apre sa, yo tounen met kouvèti a sou bouch pi a ankò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 4, text = "Jakòb mande gadò mouton yo konsa: -Zanmi m' yo, moun ki bò nou ye? Yo reponn li: -Nou se moun Karan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 5, text = "Li di yo: -Eske nou konnen Laban, pitit Nakò a? Yo reponn li: -Men wi, nou konnen l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 6, text = "Li mande yo: -Ban m' nouvèl li non. Li byen? Yo reponn li: -Li byen wi. Gade, men Rachèl, pitit fi li a, k'ap vini ak bann mouton li yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 7, text = "Jakòb di yo: -Men, solèy la byen wo toujou, se poko lè pou nou antre mouton yo. Sak fè nou pa bay yo bwè, epi nou ta tounen mete yo nan manje?", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 8, text = "Yo reponn li: -Nou pa ka fè sa. Fòk nou tann tout bann mouton yo sanble. Atòkile, nou tout n'a met men ansanm pou n' woule wòch ki sou bouch pi a. Se lè sa a n'a bay mouton yo bwè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 9, text = "Jakòb t'ap pale ak yo toujou lè Rachèl vin rive ak bann mouton papa l' yo. Se li menm ki te gade mouton l' yo pou li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 10, text = "Kou Jakòb wè Rachèl, pitit fi Laban, frè manman l' lan, avèk bann mouton Laban yo, li pwoche, li woule wòch ki te sou bouch pi a, li bay bann mouton Laban yo bwè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 11, text = "Lè l' fini, li bo Rachèl. Apre sa, li pran kriye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 12, text = "Jakòb fè Rachèl konnen se ti fanmi Laban li ye, pitit Rebeka, sè Laban an. Rachèl kouri al di papa l' sa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 13, text = "Lè Laban tande se pitit sè li a, li kouri al jwenn li. Li pran l', li pase men nan kou l', li bo l', epi li mennen l' lakay li. Rive yo rive Jakòb rakonte l' tout sak te pase.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 14, text = "Lè sa a, Laban di l': -Aa wi, se ras mwen ou ye vre. Jakòb rete pase yon mwa lakay Laban.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 15, text = "Laban mande Jakòb: -Ou se fanmi m', se vre. Men, sa pa vle di fòk ou sevi m' gratis pou sa. Di m' konbe pou m' peye ou?", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 16, text = "Laban te gen de pitit fi. Pi gran an te rele Leya, pi piti a te rele Rachèl.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 17, text = "Leya te gen je pichpich, men Rachèl te gen bèl fòm kò, li te bèl anpil.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 18, text = "Jakòb te renmen Rachèl. Li reponn Laban: M'ap sèvi avè ou sèt lanne pou Rachèl, dezyèm pitit fi ou la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 19, text = "Laban di l': Pito se ou menm mwen bay li pase m' bay yon lòt moun li. Ou mèt rete lakay mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 20, text = "Se konsa Jakòb pase sètan ap travay kay Laban pou l' te ka marye ak Rachèl. Sèt lanne yo te pase tankou dlo, paske li te renmen ti fi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 21, text = "Lè lè a rive, Jakòb di Laban: -Bon. Li lè atò pou ou ban m' pitit fi ou la pou m' ka marye avè l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 22, text = "Se konsa Laban fè yon gwo resepsyon nòs, li envite tout moun nan kanton an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 23, text = "Men aswè, li te pran Leya, pitit fi li a, li mennen l' bay Jakòb ki kouche avè l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 24, text = "Laban te pran Zilpa, yonn nan sèvant li yo, li bay Leya pou sèvant pa li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 25, text = "Nan denmen maten, Jakòb vin wè se Leya yo te ba li. Li di Laban: -Kisa ou fè m' konsa? Eske se pa pou Rachèl mwen te sèvi avèk ou? Poukisa ou ban m' koutba sa a?", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 26, text = "Laban di l': -Se pa koutim nou isit pou n' marye ti sè anvan gran sè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 27, text = "Tann senmenn lan fin pase. Lè sa a, n'a fin fete nòs la. Apre sa, m'a ba ou Rachèl, si ou dakò pou sèvi avè m' pandan sèt lòt lanne ankò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 28, text = "Jakòb tonbe dakò. Lè senmenn fèt la fin pase, Laban pran lòt pitit fi l' la, Rachèl, li bay Jakòb li pou madanm tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 29, text = "Laban pran Bila, yonn nan sèvant li yo, li bay Rachèl li pou sèvant li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 30, text = "Jakòb kouche ak Rachèl. Li te renmen l' pi plis pase Leya. Li sèvi ak Laban pandan sèt lanne ankò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 31, text = "Lè Seyè a wè jan Jakòb pa t' renmen Leya, li fè l' fè pitit. Men, Rachèl pa t' kapab fè pitit.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 32, text = "Leya vin ansent, li fè yon pitit gason, li di: -Seyè a wè jan m'ap soufri. Koulye a, mari m' va renmen m'. Se konsa li rele l' Woubenn.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 33, text = "Leya vin ansent ankò, li fè yon lòt gason. Li di: -Seyè a ban m' yon lòt gason ankò, paske li wè jan mari m' pa renmen m' menm. Se konsa li rele l' Simeyon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 34, text = "Li vin ansent yon twazyèm fwa, li fè yon lòt pitit gason ankò. Li di: -Fwa sa a, mari m' pral rete avè m' nèt paske mwen fè twa pitit gason pou li. Se konsa li rele l' Levi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 29, verseNumber = 35, text = "Apre sa, li vin ansent ankò, li fè yon lòt pitit gason. Li di: -Fwa sa a, m'ap fè lwanj Seyè a. Se konsa li rele l' Jida. Apre sa, Leya sispann fè pitit.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 1, text = "Lè Rachèl wè li pa t' kapab fè pitit pou Jakòb, li vin gen yon sèl jalouzi kont sè li a, li di Jakòb: -Fè m' fè pitit! Si se pa sa m'ap mouri sou kont ou!", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 2, text = "Jakòb fè kòlè sou Rachèl, li di li: -Eske se mwen ki Bondye? Se li menm ki anpeche ou fè pitit.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 3, text = "Rachèl di li: -Bon. Men Bila, sèvant mwen an. Kouche avè l'. La fè yon pitit pou mwen. Konsa, gremesi Bila, m'a gen pitit tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 4, text = "Se konsa, Rachèl te pran sèvant li a, li bay Jakòb pou madanm. Jakòb kouche ak Bila.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 5, text = "Bila vin ansent, li fè yon ti gason pou Jakòb.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 6, text = "Lè sa a, Rachèl di: -Seyè a rann mwen jistis. Li tande vwa mwen. Li ban m' yon gason. Se poutèt sa Rachèl te rele pitit la Dann.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 7, text = "Apre sa, Bila, sèvant Rachèl la, vin ansent ankò, li fè yon dezyèm gason pou Jakòb.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 8, text = "Rachèl di: -Mwen t'ap mennen yon gwo batay kont sè m' lan devan Bondye. Men se mwen ki genyen. Se konsa li rele pitit la Nèftali.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 9, text = "Lè Leya wè li te sispann fè pitit, li pran Zilpa, sèvant li a, bay Jakòb pou madanm tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 10, text = "Zilpa, sèvant Leya a, fè yon ti gason pou Jakòb.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 11, text = "Leya di: -Ala fanm gen chans se mwen menm! Se konsa li rele pitit la Gad.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 12, text = "Zilpa, sèvant Lea a, fè yon dezyèm pitit gason pou Jakòb.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 13, text = "Leya di konsa: -Ala benediksyon mwen jwenn! Koulye a medam yo pral di jan mwen se yon fanm ki beni. Se konsa li rele pitit la Asè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 14, text = "Pandan rekòt ble a, Woubenn soti al nan jaden, li jwenn kèk mandragò. Li pote rasen yo bay Leya, manman li. Rachèl di Leya konsa: -Tanpri, ban m' kèk moso rasen mandragò pitit ou pote pou ou a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 15, text = "Leya reponn li: -Atò ou pa fè m' ase? Ou fin pran mari m', koulye a ou vle pran mandragò pitit gason m' lan tou? Rachèl di l': -Enben, Jakòb va kouche avè ou aswè a pou mandragò pitit gason ou lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 16, text = "Nan aswè, lè Jakòb parèt sot nan jaden, Leya soti al kontre l', li di l' konsa: -Se pou ou vin kouche avè m' aswè a, paske mwen bay mandragò pitit gason m' lan pou sa. Se konsa, jou swa sa a, Jakòb kouche avèk Leya.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 17, text = "Bondye reponn lapriyè Leya a. Li vin ansent, epi li fè yon senkyèm pitit gason pou Jakòb.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 18, text = "Leya di: -Bondye ban m' sa m' merite a, paske mwen te bay mari m' sèvant mwen an pou madanm. Se konsa, Leya rele pitit gason an Isaka.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 19, text = "Leya vin ansent ankò, li fè yon sizyèm pitit gason pou Jakòb.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 20, text = "Leya di: -Bondye fè m' yon bèl kado. Fwa sa a, mari m' pral pou mwen nèt, paske mwen fè sis pitit gason pou li. Se konsa li rele pitit la Zabilon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 21, text = "Apre sa, li fè yon pitit fi. Li rele l' Dena.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 22, text = "Lè sa a, Bondye vin chonje Rachèl, li reponn lapriyè li, li fè l' ka fè pitit.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 23, text = "Se konsa Rachèl vin ansent, li fè yon pitit gason. Li di: -Bondye fè yo sispann pase m' nan rizib.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 24, text = "Epi Rachèl rele pitit gason an Jozèf, paske li te di: -Se pou Seyè a ba m' yon lòt gason ankò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 25, text = "Apre Rachèl te fè Jozèf, Jakòb di Laban konsa: -Kite m' pati pou m ale lakay mwen nan peyi mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 26, text = "Ban mwen madanm mwen yo ansanm ak timoun yo pou m' ka ale, paske se pou yo mwen t'ap sèvi ak ou. Ou konnen tout kantite sèvis mwen rann ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 27, text = "Laban reponn li: -Fè m' plezi sa a: mwen rekonèt se poutèt ou Seyè a beni m' tout beni sa a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 28, text = "Di m' sa pou m' peye ou, m'a ba ou li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 29, text = "Jakòb di l': -Ou konnen jan mwen sèvi avè ou. Ou wè ki jan bann bèt ou yo peple depi yo nan men m'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 30, text = "Ti sa ou te genyen anvan m' te vini an tounen yon kantite depi mwen mete pye m' isit la. Akòz mwen Seyè a pa manke beni ou. Alekile, li lè pou m' al travay pou tèt pa mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 31, text = "Laban di l': -Kisa pou m' ba ou? Jakòb reponn li: -Ou pa bezwen peye m' pou sa. Men si ou dakò avèk sa mwen pral di ou la, m'a rete ankò pou okipe bèt ou yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 32, text = "Jòdi a, mwen pral pwonmennen mache nan mitan tout bèt ou yo. M'ap pran tout ti mouton nwa, ak tout ti kabrit ki takte osinon pentle yo, m'ap mete yo apa. Se sa ase w'a ban mwen pou sèvis mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 33, text = "Lè w'a vin wè sa ou dakò ban mwen an, w'a konnen si m' te fè vis, wi ou non. Lè w'a vin kontwole sa ki pou mwen yo, si mwen gen yon mouton ki pa nwa, osinon yon kabrit ki pa takte ou ki pa pentle, ou mèt konnen se vòlè mwen vòlè ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 34, text = "Laban reponn li: -Dakò. n'a fè l' jan ou di l' la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 35, text = "Men menm jou a, Laban wete tout bouk kabrit ki te gen pwal takte osinon ki te gen re sou tout kò yo, ak tout fenmèl kabrit ki te gen pwal takte osinon pentle, ou ankò ki te gen tach blan sou yo. Li wete tout mouton nwa yo, li pran tout bèt sa yo, li renmèt yo bay pitit gason l' yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 36, text = "Apre sa, li pati byen lwen Jakòb avèk bann bèt li yo, li mache pandan twa jou epi li rete. Jakòb menm te pran swen rès mouton ak kabrit Laban yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 37, text = "Jakòb koupe kèk branch vèt nan pye sikren, pye zanmann ak pye bwadòm, li wete kèk lèz nan kòs yo. Konsa branch yo te vin gen bann vèt, bann blan sou tout kò yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 38, text = "Li pran yo, li mete yo tout kote yo bay bèt yo bwè dlo. Li te ranje branch bwa yo la, paske se lè bèt yo vin bwè dlo yo kwaze.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 39, text = "Konsa, lè bèt yo kwaze devan branch bwa de koulè yo, yo fè pitit takte, pitit pentle, osinon ak re sou tout kò yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 40, text = "Jakòb separe mouton yo, li pran tout mouton ki te takte osinon ki te nwa nan mouton Laban yo, li mete yo apa. Se konsa, li te vin gen yon bann bèt apa ki pa t' mele ak bèt Laban yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 41, text = "Lè bèt ki gra yo ap kwaze, Jakòb mete branch yo devan je yo kote y'ap bwè a. Konsa, yo kwaze devan branch yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 42, text = "Men, li pa mete branch yo lè se bèt mèg yo k'ap kwaze. Se konsa, bèt mèg yo vin pou Laban, epi bèt gra yo vin pou Jakòb.", bookId = 1),
        Verse(book = "Jenèz", chapter = 30, verseNumber = 43, text = "Jakòb vin rich anpil, Li te gen anpil bèt. Kanta pou sèvant, domestik, chamo ak bourik, li pa t' manke sa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 1, text = "Jakòb vin konnen jan pitit gason Laban yo t'ap di: -Jakòb fin pran tou sa ki te pou papa nou. Se byen papa nou li fin ranmase kifè li rich konsa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 2, text = "Jakòb vin wè tout Laban pa t' ba li menm karaktè li te konn ba li anvan an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 3, text = "Lè sa a, Seyè a di l': -Tounen nan peyi kote ou te fèt la, al jwenn fanmi ou. M'ap toujou la avè ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 4, text = "Se konsa Jakòb fè chache Rachèl ak Leya. Li voye di yo rive kote l' nan savann kote bèt li yo ye a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 5, text = "Li di yo: -Mwen wè karaktè papa nou pa menm jan avè m' ankò. Li chanje anpil, men Bondye papa m' lan toujou avè m'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 6, text = "Nou tout de nou konnen jan mwen te sèvi ak papa nou ak tout kouraj mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 7, text = "Men li menm, li toujou ap twonpe mwen. Li chanje lide dis fwa lè lè a rive pou li peye m'. Men, Bondye pa janm kite l' fè m' anyen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 8, text = "Lè Laban di: ou mèt pran tout kabrit takte yo pou ou, tout bann bèt yo tonbe fè pitit takte. Lè li di: m'ap ba ou tout kabrit ki gen re sou tout kò yo, tout bann bèt yo tonbe fè pitit ak re sou tout kò yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 9, text = "Se Bondye menm ki pran bann bèt papa nou yo, li ban mwen yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 10, text = "Lè bèt yo mande kwaze, mwen fè yon rèv, mwen wè tout bouk ki t'ap kwaze yo se bouk ki takte, ki pentle ak sa ki gen re sou tout kò yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 11, text = "Zanj Bondye a pale avè m' nan rèv la, li di m': Jakòb. Mwen reponn li: Men mwen wi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 12, text = "Li di m' ankò: Leve je ou gade: tout bouk k'ap vole fenmèl yo se bouk ki takte ak sa ki gen re sou tout kò yo. Se mwen menm k'ap fè sa konsa, paske mwen wè tout sa Laban ap fè ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 13, text = "Mwen se Bondye ki te parèt devan ou lè ou te Betèl, kote ou te mete gwo wòch la apa pou mwen an. Ou chonje, lè sa a, ou te fè yon pwomès ban mwen. Koulye a, leve, kite peyi sa a. Tounen nan peyi kote ou te fèt la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 14, text = "Rachèl ak Leya reponn Jakòb: -Nou pa gen anyen ankò pou n' eritye nan men papa nou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 15, text = "Eske li pa konsidere nou tankou etranje? Li vann nou. Koulye a, li fin manje tout lajan yo te ba li pou nou an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 16, text = "Tout richès Bondye wete nan men papa nou an, se pou nou ansanm ak pitit nou yo. Koulye a, se pou ou fè tout sa Bondye di ou fè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 17, text = "Lè sa a, Jakòb leve, li mete pitit li yo ansanm ak madanm li yo sou chamo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 18, text = "Li pran tout bèt li yo ansanm ak tout sa li te rive genyen pandan li te Mezopotami an, li mennen yo ale. Li pati, li al jwenn papa l', Izarak, nan peyi Kanaran.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 19, text = "Lè sa a, Laban t al taye lenn mouton l' yo. Pandan li pa t' la, Rachèl vòlè ti zidòl kay papa l' yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 20, text = "Se konsa Jakòb twonpe Laban, moun lavil Aram lan, li pati san l' pa di l' sa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 21, text = "Li pran tout sa li te genyen, li mete deyò, li ale, li travèse larivyè Lefrat, li pran chemen pou li al sou mòn Galarad.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 22, text = "Twa jou apre, Laban pran nouvèl Jakòb te pati.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 23, text = "Msye pran moun pa li yo avè l', li pati dèyè Jakòb. Apre sèt jou, li jwenn li sou mòn Galarad.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 24, text = "Men, pandan lannwit, Bondye parèt devan Laban, moun lavil Aram lan, nan yon rèv, li di l': -Piga ou di Jakòb anyen ni an byen, ni an mal.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 25, text = "Se konsa, Laban jwenn Jakòb ki te moute tant li sou mòn lan. Laban te moute tant li tout sou mòn Galarad pou li menm ansanm ak moun pa l' yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 26, text = "Laban di Jakòb: -Kisa ou fè konsa? Ou twonpe m', ou pran pitit fi mwen yo, ou mennen yo ale tankou prizonye ou fè nan lagè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 27, text = "Poukisa ou twonpe m', ou leve ou pati an kachèt san ou pa avèti m'? Si ou te di m' sa, nou ta fè fèt, nou ta chante, nou ta bat tanbou, nou ta jwe gita anvan nou voye ou ale.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 28, text = "Ou pa menm kite m' bo pitit pitit mwen yo ak pitit fi m' yo. Ou aji tankou moun fou, monchè!", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 29, text = "Mwen gen kont pouvwa anba men m' pou m' ta regle ou. Men yè swa, pandan lannwit lan Bondye papa ou la di m': Piga ou di Jakòb anyen ni an byen, ni an mal.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 30, text = "Mwen konnen ou pati paske se pa ti anvi ou pa te anvi tounen lakay papa ou. Men, sa ou te bezwen vòlè ti zidòl kay mwen yo fè?", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 31, text = "Jakòb reponn Laban, li di l': -Mwen te pè, paske mwen te kwè ou ta ka reprann pitit fi ou yo nan menm.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 32, text = "Men, kanta pou ti zidòl kay ou yo, si ou jwenn yo nan men yon moun isit la, se pou moun sa a mouri. Men, mwen pran tout moun sa yo pou temwen, si ou jwenn yon bagay lakay mwen ki pou ou, pran l' pote l' ale. Jakòb pa t' konnen Rachèl te vòlè ti zidòl kay yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 33, text = "Laban antre anba tant Jakòb la, li chache, li ale anba tant Leya a, apre sa anba tant de sèvant yo, li pa jwenn anyen. Li soti anba tant Leya a, li antre anba tant Rachèl. la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 34, text = "Rachèl menm te pran ti zidòl kay yo, li te mete yo anba aparèy chamo a, epi li chita sou yo. Laban menm chache tout anba tant lan, li pa jwenn anyen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 35, text = "Rachèl di papa l' konsa: -Si ou wè mwen pa ka leve kanpe devan ou, ou pa bezwen fache non. Se lalen mwen mwen genyen. Se konsa Laban fouye toupatou, li pa jwenn ti zidòl kay li yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 36, text = "Lè sa a, Jakòb move sou Laban. Li pete yon kabouyay ak li, li di l': -Ki krim mwen fè? Kisa m' fè ki mal pou w'ap pousib mwen konsa?", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 37, text = "Ou fin fouye tout zafè m' yo. Kisa ou jwenn ki pou ou? Mete l' la devan moun pa ou yo ak moun pa m' yo, pou yo ka di ki moun ki gen rezon!", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 38, text = "Sa fè ventan depi m avè ou. Mouton ou yo ak kabrit ou yo pa janm manke fè pitit. Mwen pa janm manje yon ti bouk nan bèt ou yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 39, text = "Lè bèt nan bwa touye yon mouton, mwen pa janm pote l' ba ou. Mwen te pran pèt la sou kont mwen. Ou te rann mwen reskonsab tout bèt yo vòlè, kit se lannwit, kit se lajounen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 40, text = "Lajounen, chalè te fini avè m'. Lannwit, se te fredi, mwen pa t' kapab dòmi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 41, text = "Se konsa sa te ye pandan tout ventan mwen pase lakay ou yo. Mwen travay pandan katòzan pou de pitit fi ou yo. Apre sa, mwen fè sizan ankò ap travay pou bann bèt ou yo. Atousa, ou jwenn mwayen chanje pawòl dis fwa lè lè a rive pou ou peye m'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 42, text = "Si Bondye papa m' lan, Bondye Abraram lan, Bondye Izarak respekte a, pa t' la avèk mwen, koulye a ou ta voye m' ale yon men devan yon men dèyè. Men Bondye wè tout traka mwen bay tèt mwen, li wè travay mwen fè, se konsa yè swa li rann jijman li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 43, text = "Laban reponn Jakòb: -Fi sa yo se pitit mwen yo ye. Timoun sa yo, se pa m' yo ye. Bann bèt sa yo se pou mwen yo ye. tout sa ou wè la a, se pou mwen yo ye. Bon, kisa m' ka fè koulye a pou pitit fi mwen yo ak pou pitit pitit mwen yo?", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 44, text = "Vini non. Annou pase yon kontra, mwen menm avè ou. Ann kite yon mak ki va sèvi pou fè nou toujou chonje kontra a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 45, text = "Jakòb pran yon gwo wòch, li plante l' nan tè a, li fè l' rete kanpe tankou yon bòn.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 46, text = "Epi, li di moun li yo: -Ranmase wòch. Mesye yo ranmase wòch, yo anpile yo fè yon gwo pil. Apre sa, yo chita bò pil wòch la, yo manje.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 47, text = "Laban rele pil wòch la Jega Saadouta nan lang pa l', men Jakòb te rele l' nan lang pa l' Galèd.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 48, text = "Laban di: -Pil wòch sa a va sèvi pou fè nou tout de toujou chonje kontra a. Se poutèt sa yo rele kote sa a Galèd.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 49, text = "Laban di ankò: -Se pou Bondye voye je sou nou tout de lè nou fin separe. Se konsa yo rele kote sa a Mispa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 50, text = "Laban pale ankò, li di: -Si ou maltrete pitit fi mwen yo, si ou pran lòt fanm ankò sou yo, konnen ou p'ap annafè ak yon moun tankou nou tande. Atansyon, men se ak Bondye menm, ki temwen sa nou sot fè a, w'ap annafè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 51, text = "Laban di Jakòb ankò: -Men pil wòch mwen mete pou separe nou an. Men bòn ou plante a la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 52, text = "Ni pil wòch yo ni bòn lan ap sèvi yon mak. Mwen pa gen dwa depase l' pou m' vin atake ou, ni ou pa gen dwa depase l' pou ou vin atake m'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 53, text = "Se pou Bondye Abraram lan, Bondye Nakò a, Bondye papa yo a, mete rezon nan mitan nou. Lè sa a, Jakòb sèmante nan non Bondye Izarak, papa l' respekte a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 54, text = "Apre sa, li touye yon bèt, li ofri l' bay Bondye sou mòn lan, epi li envite moun pa l' yo vin manje. Lè yo fin manje, yo pase nwit la sou mòn lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 31, verseNumber = 55, text = "Nan denmen maten byen bonè, Laban leve, li bo pitit pitit li yo ak pitit fi li yo. Li beni yo. Apre sa, li pati, li tounen lakay li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 1, text = "Jakòb menm ale chemen chemen l'. Li kontre kèk zanj Bondye sou wout li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 2, text = "Lè li wè yo, li di: -Sa se lame Bondye a. Se konsa li rele kote a Manayim.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 3, text = "Jakòb voye kèk komisyonè devan al jwenn Ezaou, frè li a, nan peyi Seyi, kote Edon te rete a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 4, text = "Men sa li ba yo lòd pou yo di: -Men sa n'a di Ezaou, mèt mwen: Jakòb, nèg pa ou la, voye di ou konsa, li te pase tout tan sa a lakay Laban. Se poutèt sa li te pran tout reta sa a pou l' tounen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 5, text = "Li gen bèf, bourik, mouton, kabrit, domestik ak sèvant. Li voye di ou sa pou ou ka fè pa l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 6, text = "Lè mesaje yo tounen vin jwenn Jakòb, yo di l': -Nou t ale kote Ezaou, frè ou la. Koulye a li gen tan sou wout pou l' vin kontre ou. Li gen katsan (400) moun ak li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 7, text = "Jakòb te pè anpil. Li te boulvèse. Li pran moun ki te avè l' yo, li fè yo fè de pòsyon. Li fè menm bagay la ak mouton, bèf, chamo li te genyen yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 8, text = "Li t'ap di nan kè l': -Si Ezaou vin atake yon pòsyon, lòt pòsyon an va gen tan chape.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 9, text = "Jakòb lapriyè, li di: -O Bondye Abraram granpapa m' lan, Bondye Izarak papa m' lan! O Seyè, ou menm ki te di m' tounen nan peyi m' kote m' te fèt la! W'a fè tout bagay mache byen pou mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 10, text = "Mwen menm k'ap sèvi ou la, mwen pa wè poukisa ou fè m' tout favè sa yo, poukisa ou toujou kenbe pawòl ou avè m'. Lè m' t'ap travèse larivyè Jouden, se annik yon baton mwen te gen nan men m'. Koulye a m'ap tounen, mwen tèlman genyen, mwen ka separe yo fè de pòsyon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 11, text = "Tanpri, delivre m' non anba men Ezaou, frè mwen an! Mwen pè pou l' pa vin atake nou, pou l' pa touye ata fanm yo ak timoun yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 12, text = "Chonje sa ou te di m' lan: M'ap fè tout bagay mache byen pou ou. M'ap si tèlman ba ou pitit pitit, moun p'ap ka konte yo. Y'ap tankou grenn sab bò lanmè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 13, text = "Jakòb rete pase nwit la kote l' te ye a. Apre sa, nan sa l' te gen avè l' yo, li chwazi ladan yo pou fè Ezaou, frè l' la, kado.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 14, text = "Li pran desan (200) fenmèl kabrit ak vin bouk, desan fenmèl mouton ak vin belye,", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 15, text = "trant fenmèl chamo nouris ak tout ti chamo yo dèyè yo, karant manman bèf, dis towo, vin fenmèl bourik ak dis mal bourik.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 16, text = "Li pran bèt yo, li mete chak kalite apa, li renmèt chak kalite bay yonn nan domestik li yo. Li di yo konsa: -Pran devan mwen. Chak moun ap kite yon distans nan mitan bèt pa l' yo ak bèt ki devan l' yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 17, text = "Epi li pase premye a lòd sa a: -Lè Ezaou, frè m' lan, va kontre ou, l'ap mande ou: Kilès ki mèt ou? Kote ou prale? Pou ki moun bèt sa yo w'ap pouse devan ou konsa a?", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 18, text = "W'a reponn li: Se pou Jakòb, nèg pa ou la. Se yon kado li voye bay Ezaou, mèt mwen an. Li menm, li dèyè, l'ap vini.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 19, text = "Li pase dezyèm lan, twazyèm lan ak tout lòt moun ki t'ap mache dèyè bèt yo menm lòd la. -Men sa nou gen pou n' di Ezaou, lè nou kontre l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 20, text = "Se pou nou di: Wi, Jakòb, nèg pa ou la, ap vin dèyè nou pye pou pye. Jakòb t'ap di nan kè l'. Avèk tout kado m'ap voye devan m' lan, m'ap fè kè l' kontan. Konsa, lè n'a kontre, ou pa janm konnen, li ka fè pa m'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 21, text = "Moun yo pran devan ak kado yo. Men Jakòb rete dèyè, li pase nwit la kote l' te ye a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 22, text = "Menm jou lannwit sa a, Jakòb leve, li pran de madanm li yo, de sèvant li yo ak onz pitit gason li yo, li janbe lòt bò larivyè Jabòk, nan pas la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 23, text = "Apre li fin fè yo janbe larivyè a, li fè janbe tout sa li te genyen tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 24, text = "Men li menm, li te rete pou kont li dèyè. Lè sa a, gen yon moun ki mare batay ak li, yo goumen jouk devanjou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 25, text = "Lè nonm lan wè li pa t' ka bat li, li bay Jakòb yon kou nan ren l'. Se konsa zo ren l' dejwente pandan yo t'ap goumen an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 26, text = "Nonm lan di l': -Kite m' ale, paske bajou pral kase. Jakòb reponn li: -Si ou pa beni mwen, mwen p'ap kite ou ale.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 27, text = "Nonm lan di: -Ki jan ou rele? Li reponn: -Jakòb.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 28, text = "Nonm lan di l': -Yo p'ap rele ou Jakòb ankò. Y'ap rele ou Izrayèl, paske ou goumen ak Bondye, ou goumen ak moun, se ou menm ki genyen batay la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 29, text = "Jakòb mande l': -Tanpri, di m' ki jan ou rele? Li reponn: -Poukisa w'ap mande m' ki jan mwen rele? Apre sa li beni Jakòb.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 30, text = "Jakòb di konsa: -Mwen wè Bondye, mwen pa mouri. Se konsa, li rele kote l' te ye a Penyèl.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 31, text = "Solèy te gen tan ap leve lè Jakòb kite Penyèl, li t'ap bwete poutèt ren li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 32, verseNumber = 32, text = "Se poutèt sa, jouk jòdi a, pitit pitit Izrayèl yo pa manje venn ki kenbe zo ren an, paske se sou venn sa a Bondye te frape Jakòb.", bookId = 1),
        Verse(book = "Jenèz", chapter = 33, verseNumber = 1, text = "Jakòb leve je l' gade, li wè Ezaou ki t'ap mache vin jwenn li avèk katsan moun dèyè li. Li pran timoun yo, li separe yo, li bay Leya pa l' yo, li bay Rachèl pa l' yo, li bay de sèvant yo pa yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 33, verseNumber = 2, text = "Li mete de sèvant yo devan nèt ak pitit yo, Leya ak pitit li yo nan mitan, Rachèl ak Jozèf dèyè nèt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 33, verseNumber = 3, text = "Li menm, li pran mache devan yo tout. Li bese tèt li jouk atè pandan sèt fwa, jouk li rive toupre Ezaou, frè li a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 33, verseNumber = 4, text = "Ezaou menm kouri al kontre l', li pase bra l' nan kou l', li bat do l', li bo li. Epi yo tout de yo pran kriye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 33, verseNumber = 5, text = "Lè Ezaou voye je l' gade, li wè medam yo ak timoun yo. Li di: -Ki moun sa yo ki avè ou la a? Jakòb reponn li: -tout se pitit Seyè a bay nèg pa ou la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 33, verseNumber = 6, text = "Lè sa a, sèvant yo pwoche ak timoun yo, yo bese tèt yo jouk atè devan Ezaou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 33, verseNumber = 7, text = "Apre sa, Leya pwoche ak timoun pa l' yo, yo bese tèt yo tout devan li. Andènye nèt, Jozèf ak Rachèl pwoche, yo bese tèt yo tout devan li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 33, verseNumber = 8, text = "Ezaou mande l': -Moun mwen kontre pi devan an, poukisa ou te voye yo? Jakòb reponn li: -Se pou m' te ka fè kè ou kontan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 33, verseNumber = 9, text = "Ezaou di l': -Frè mwen, mwen gen tout sa m' bezwen. Ou mèt kenbe tou sa ou genyen pou ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 33, verseNumber = 10, text = "Jakòb reponn li: -Non. Si ou kontan wè m' tout bon, tanpri, asepte kado m'ap ba ou yo. Paske, lè mwen kontre ou, se tankou si m' te wè figi Bondye. Gade jan ou resevwa m' byen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 33, verseNumber = 11, text = "Tanpri, asepte kado m'ap ba ou yo, paske Bondye te beni m' anpil. Mwen pa manke anyen. Jakòb fòse Ezaou sitèlman, bout pou bout, Ezaou asepte.", bookId = 1),
        Verse(book = "Jenèz", chapter = 33, verseNumber = 12, text = "Li di: -Bon. Ann pati. Ann ale. M'ap pran devan ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 33, verseNumber = 13, text = "Men Jakòb reponn li: -Mèt mwen, ou konnen jan timoun yo fèb. Epi, fòk mwen pa bliye fenmèl mouton ak manman bèf yo ki nouris. Si m' fè yo mache twòp yon sèl jou, se kont pou yo tout mouri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 33, verseNumber = 14, text = "Tanpri, mèt mwen, ou mèt pran devan nèg pa ou la, mwen menm m'ap vin dèyè ti pa ti pa, jan bèt yo ak timoun yo ka mache, jouk m'a rive lakay ou nan peyi Seyi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 33, verseNumber = 15, text = "Ezaou di l': -Bon. m'a kite kèk moun nan moun pa m' yo avè ou? Jakòb reponn: -Se pa nesesè. Yon sèl bagay mwen mande, se pou mèt mwen bliye tout bagay.", bookId = 1),
        Verse(book = "Jenèz", chapter = 33, verseNumber = 16, text = "Menm jou a, Ezaou pati tounen nan peyi Seyi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 33, verseNumber = 17, text = "Jakòb menm pati pou Soukòt. Lè li rive la, li bati yon kay pou li ak yon pak pou bèt li yo. Se sak fè yo rele kote sa a Soukòt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 33, verseNumber = 18, text = "Lè Jakòb tounen soti Mezopotami, li rive anbyen lavil Sichèm, nan peyi Kanaran. Li moute tant li sou moso tè ki anfas lavil la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 33, verseNumber = 19, text = "Li achte moso tè kote li te moute tant li a pou san (100) pyès lajan nan men pitit Amò yo. Se Amò sa a ki te papa Sichèm.", bookId = 1),
        Verse(book = "Jenèz", chapter = 33, verseNumber = 20, text = "Jakòb bati yon lotèl la tou. Li rele l': Bondye se Bondye Izrayèl la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 1, text = "Dena, pitit fi Leya te fè pou Jakòb la, te soti al rann medam peyi a vizit.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 2, text = "Lè sa a, Sichèm, pitit Amò, moun Evi a, te chèf nan kanton an. Lè li wè Dena, li mete men sou li, li fè kadejak sou li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 3, text = "Men Sichèm te tonbe damou pou Dena, pitit fi Jakòb la. Li te pale dous ak tifi a, paske li te renmen l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 4, text = "Sichèm di Amò, papa l': -Al mande pou fi sa a pou mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 5, text = "Jakòb vin konnen Sichèm te fè kadejak sou Dena, pitit fi li a. Men, paske pitit gason l' yo te nan savann ak bèt yo, li pa di anyen jouk lè yo tounen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 6, text = "Amò, papa Sichèm, ale bò kot Jakòb pou fè yon pale sou sa avè l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 7, text = "Lè sa a, pitit gason Jakòb yo t'ap tounen soti nan savann. Lè yo pran nouvèl la, yo te move, yo te fache anpil, paske Sichèm te fè yon bagay grav: li te avili moun Izrayèl yo lè l' te fè kadejak sou pitit fi Jakòb la. Bagay konsa pa t' dwe fèt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 8, text = "Amò di yo konsa: -Pitit gason m' lan, Sichèm, fin fou pou fi nou an. Tanpri, kite li marye avè l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 9, text = "Ann pase kontra yonn ak lòt pou nou zanmi. n'a ban nou nan pitit fi nou yo pou madanm pitit gason nou yo. n'a pran nan pitit fi nou yo pou madanm pitit gason nou yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 10, text = "Konsa n'a rete ansanm ak nou nan peyi a. n'a rete kote nou vle, n'a fè kòmès jan nou vle, n'a achte tè nou vle.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 11, text = "Apre sa, Sichèm di papa ak frè Dena yo: -Fè m' favè sa a, tanpri. m'a ban nou tout sa nou vle.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 12, text = "Di m' kisa pou m' fè nou kado. Nou mèt mande m' nenpòt ki gwo pri pou maryaj la. M'ap ban nou tout sa n'a mande m'. Men, se pou nou dakò. Kite m' marye ak fi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 13, text = "Men pitit gason Jakòb yo bay Sichèm ak Amò, papa li, yon repons pou woule yo. Paske Sichèm te avili sè yo a, yo t'ap pare yon move kou pou yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 14, text = "Yo di yo: -Nou pa ka kite sè nou an marye ak yon nonm ki pa sikonsi. Se va yon avilisman pou nou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 15, text = "N'ap dakò nan yon sèl kondisyon. Se pou nou vin menm jan ak nou, se pou tout gason nan kanton an sikonsi tankou nou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 16, text = "Lè sa a atò, n'a kite sè nou an marye avè ou. Nou menm tout n'a ka marye ak pitit fi ou yo. n'a rete nan peyi a ansanm ansanm, n'a tounen yon sèl pèp.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 17, text = "Men, si nou pa dakò ak kondisyon sa a, si nou pa vle pou yo sikonsi nou, n'ap pran sè nou an, epi nou pral fè wout nou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 18, text = "Amò ak Sichèm, pitit gason l' lan, tonbe dakò ak yo pou kondisyon an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 19, text = "Se konsa jenn gason an te prese fè sa yo te mande l' fè a, paske li te renmen pitit fi Jakòb la anpil. tout moun kay papa l' te konsidere l' anpil.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 20, text = "Amò ak Sichèm, pitit gason l' lan, al nan pòtay lavil la, kote tout moun yo te konn reyini, yo pale ak moun peyi a. Yo di yo:", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 21, text = "-Mesye sa yo, se pa moun ki vin pou kont. Ann kite yo rete nan peyi a. Ann kite yo fè trafik yo. Peyi a gen kont plas pou yo. Ann marye ak pitit fi yo, ann kite yo marye ak pitit fi nou yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 22, text = "Mesye sa yo dakò pou yo rete ansanm ak nou, pou nou fè yon sèl pèp. Men yo pase yon kondisyon: se pou tout gason nan mitan nou sikonsi, menm jan yo menm yo sikonsi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 23, text = "Konsa, tout bèt yo, tout byen yo, tout zannimo yo ap vin pou nou yon lè. Se asepte pou n' asepte kondisyon an pou yo ka rete viv ansanm ak nou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 24, text = "tout moun ki te reyini bò pòtay lavil la te tonbe dakò ak sa Amò ak Sichèm, pitit li a, te di yo. Se konsa yo sikonsi tout gason ki te la bò pòtay lavil la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 25, text = "Twa jou apre, mesye yo t'ap soufri ak sikonsizyon an toujou lè de nan pitit gason Jakòb yo, Simeyon ak Levi, frè menm manman ak Dena yo, pran nepe yo, yo antre nan lavil la san pesonn pa sispèk anyen, yo touye tout gason yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 26, text = "Yo touye Amò ak Sichèm, pitit gason l' lan, yo pran Dena, yo fè l' kite kay Sichèm lan, y al fè wout yo avè l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 27, text = "Lòt pitit Jakòb yo menm jete kò yo sou kadav yo, yo piye lavil la byen piye, paske moun lavil la te avili sè yo a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 28, text = "Apre sa, yo pran tout bèt, tout bèf, tout bourik ak tout sa ki te nan lavil la ak nan jaden yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 29, text = "Yo pran tout richès ak tout sa ki te nan kay mesye yo pote ale, yo fè tout pitit yo ak tout medam yo prizonye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 30, text = "Apre sa, Jakòb rele Simeyon ak Levi, li di yo: -Gade nan ki traka nou mete m'. Koulye a, moun ki rete nan peyi a, moun Kanaran yo ak moun Perezi yo, pral rayi m'. Mwen pa gen anpil moun. Si yo mete ansanm sou do mwen pou atake m', y'ap touye m' ansanm ak tout moun lakay mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 34, verseNumber = 31, text = "Men Simeyon ak Levi reponn: -Atò, se pou nou te kite yo trete sè nou an tankou nenpòt jennès!", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 1, text = "Bondye di Jakòb: -Leve non, moute al Betèl, epi rete la. Bati yon lotèl la pou Bondye ki te parèt devan ou lan, lè ou t'ap kouri pou Ezaou, frè ou la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 2, text = "Se konsa Jakòb rele fanmi l' yo ansanm ak tout lòt moun ki avè l' yo. li di yo: -Pran tout lòt bondye etranje n'ap sèvi yo, voye yo jete. Mete nou nan kondisyon pou sèvi Bondye. Mete rad nèt sou nou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 3, text = "Nou pral kite kote nou ye a, nou pral Betèl, kote mwen pral bati yon lotèl pou Bondye ki te reponn lapriyè m' lè m' te anba tray la, pou Bondye ki te la avèk mwen kote m' pase nan vwayaj mwen te fè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 4, text = "Se konsa yo renmèt Jakòb tout bondye etranje yo te gen nan men yo ansanm ak tout zanno yo te gen nan zòrèy yo. Jakòb antere tout sa anba pye bwadchenn ki te toupre lavil Sichèm lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 5, text = "Apre sa, yo pati. tout moun ki te rete nan zòn lan te vin pè Bondye anpil. Yo yonn pa leve al rapouswiv pitit Jakòb yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 6, text = "Jakòb rive ansanm ak tout moun ki te avè l' yo lavil Louz, nan peyi Kanaran. Se lavil sa a yo rele Betèl tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 7, text = "Li bati yon lotèl la, li rele kote a Betèl, paske se la Bondye te parèt devan li lè li t'ap kouri pou frè l' la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 8, text = "Lè sa a, Debora, bòn Rebeka a, mouri. Yo antere l' pi ba Betèl, anba pye bwadchenn lan. Se konsa yo rele pye bwadchenn lan: chenn dlo nan je a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 9, text = "Lè Jakòb te tounen soti Mezopotami, Bondye parèt ankò devan li, li beni li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 10, text = "Bondye di l' konsa: -Yo rele ou Jakòb pa sa? Men, yo p'ap rele ou Jakòb ankò, y'a rele ou Izrayèl. Depi lè sa a, se Izrayèl yo rele l' vre.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 11, text = "Bondye di l' ankò: -Se mwen menm Bondye ki gen tout pouvwa a. W'ap gen anpil pitit ak pitit pitit. Gen ladan yo k'ap wa. W'ap si tèlman gen anpil pitit pitit, y'a tounen yon kantite nasyon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 12, text = "Peyi mwen te bay Abraram ak Izarak la, m'ap ba ou li tou. Apre sa, m'ap bay pitit pitit ou yo li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 13, text = "Apre sa, Bondye kite l' kote li t'ap pale ak li a, li moute nan syèl.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 14, text = "Jakòb pran yon gwo wòch, li plante l' pou l' make kote Bondye te pale avèk li a. Li pran diven, li wouze wòch la, apre sa li vide lwil sou li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 15, text = "Li rele kote Bondye te pale avè l' la Betèl.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 16, text = "Apre sa, yo pati yo kite Betèl. Yo pa t' twò lwen rive lavil Efrata lè lè a te rive pou Rachèl akouche. Li t'ap soufri anpil.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 17, text = "Lè doulè a te pi rèd, fanmchay la di l': -Ou pa bezwen pè. Ou fè yon pitit gason ankò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 18, text = "Rachèl tapral mouri, li t'ap rann dènye souf li lè li rele pitit la Bennoni. Men papa a rele l' Benjamen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 19, text = "Rachèl mouri, yo antere l' sou wout lavil Efrata. Se lavil sa a yo rele Betleyèm lan tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 20, text = "Jakòb make tonm lan ak yon gwo wòch: yo rele l' Moniman tonm Rachèl la. Wòch la la jouk jòdi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 21, text = "Apre sa, Izrayèl pati, li al moute tant li lòt bò Migdaledè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 22, text = "Antan Jakòb t'ap viv nan peyi sa a, Woubenn al kouche ak Bila, yonn nan fanm papa l' yo. Izrayèl vin konn sa, li te fache anpil. Jakòb te gen douz pitit gason.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 23, text = "Men non pitit Leya te fè pou li yo: Woubenn, premye pitit gason l' lan, Simeyon, Levi, Jida, Isaka ak Zabilon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 24, text = "Men non pitit Rachèl te fè pou li yo: Jozèf ak Benjamen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 25, text = "Men non pitit Bila, sèvant Rachèl la, te fè pou li yo: Dann ak Nèftali.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 26, text = "Men non pitit Zilpa, sèvant Leya a, te fè pou li yo: Gad ak Asè. Se tout pitit gason sa yo Jakòb te genyen antan li te nan peyi Mezopotami.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 27, text = "Jakòb al wè papa l' Izarak, nan Manmre (yo rele kote sa a Kija aba tou, ou ankò Ebwon). Se la Abraram ak Izarak te pase tout lavi yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 28, text = "Izarak te gen sankatreven lanne sou tèt li", bookId = 1),
        Verse(book = "Jenèz", chapter = 35, verseNumber = 29, text = "lè li mouri. Li te fin granmoun, li te wè kont jou li lè l' al jwenn moun li yo ki te mouri deja. Ezaou ak Jakòb, pitit gason l' yo, antere li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 1, text = "Men pitit pitit Ezaou yo. Se Ezaou sa a yo te rele Edon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 2, text = "Ezaou te chwazi fi nan moun peyi Kanaran yo pou madanm. Yonn te rele Ada. Se te pitit fi Elon, yon moun Et. Yon lòt te rele Olibama, pitit fi Ana, ki li menm te pitit fi Zibeyon, yon moun Evi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 3, text = "Li te marye tout ak Basmat, pitit fi Izmayèl la, sè Nebajòt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 4, text = "Se Ada ki te fè Elifaz pou Ezaou. Basmat te fè Reouyèl,", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 5, text = "Olibama menm te fè Jeouch, Jalam epi Kore. Se tout pitit sa yo Ezaou te fè antan li te nan peyi Kanaran.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 6, text = "Yon jou, Ezaou pran madanm li yo, pitit gason l' yo, pitit fi li yo, tout moun ki te lakay li, tout mouton l' yo, tout kabrit li yo ansanm ak tou sa li te genyen nan peyi Kanaran, li pati pou yon lòt peyi byen lwen Jakòb, frè li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 7, text = "Li te fè sa paske tè kote li t'ap viv ansanm ak Jakòb, frè l' la, te vin twò piti pou yo. Yo te vin gen twòp bèt, yo pa t' kapab rete ansanm ankò menm kote a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 8, text = "Se konsa Ezaou, yo rele Edon tou, al rete nan mòn Seyi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 9, text = "Men pitit pitit Ezaou, papa moun Edon yo ki rete nan mòn Seyi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 10, text = "Men non pitit gason Ezaou yo: Se te Elifaz, pitit Ada, madanm Ezaou, ak Reouyèl, pitit Basmat, madanm Ezaou tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 11, text = "Men non pitit gason Elifaz yo: Se te Teman, Oma, Zefo, Gayetan ak Kenaz.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 12, text = "Elifaz, pitit Ezaou a, te gen yon fanm kay yo te rele Timna. Se li ki manman Amalèk. Sa yo se tout pitit pitit gason Ada, madanm Ezaou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 13, text = "Men non pitit gason Reouyèl yo: Se te Naat, Zerak, Chanma ak Miza. Sa yo se pitit pitit gason Basmat, madanm Ezaou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 14, text = "Men non pitit gason Olibama, madanm Ezaou, te fè pou li: Jeouch, Jalam ak Kore. Olibama te pitit fi Ana, pitit fi Zibeyon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 15, text = "Men chèf branch fanmi pitit pitit Ezaou yo. Men non tout pitit gason Elifaz, premye pitit gason Ezaou a: Se te Teman, Oma, Zefo, Kenaz,", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 16, text = "Kore, Gayetan ak Amalèk. Yo tout te chèf. Se pitit Elifaz sa yo ki te chèf nan peyi Edon an: Yo tout se pitit pitit Ada yo ye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 17, text = "Men non pitit gason Reouyèl, pitit gason Ezaou a: Se te Naat, Zerak, Chanma ak Miza. Yo tout te chèf tou. Se pitit Reouyèl sa yo ki te chèf nan peyi Edon an. Yo tout se pitit pitit Basmat, madanm Ezaou, yo ye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 18, text = "Men non tout pitit gason Olibama, madan Ezaou: Se te Jeouch, Jalam ak Kore. Yo tout te chèf. Se chèf sa yo ki te pitit Olibama, madan Ezaou. Olibama te pitit fi Ana.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 19, text = "Se te non tout pitit pitit Ezaou yo sa. Yo te rele Ezaou Edon tou. Se yo ki te chèf branch fanmi yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 20, text = "Men non tout pitit gason Seyi, moun peyi Ori. Se yo menm ki rete nan peyi a depi lontan. Se Lotan, Chobal, Zibeyon, Ana,", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 21, text = "Dichon, Ezè ak Dichan. Se chèf moun peyi Ori yo sa. Yo se pitit gason Seyi nan peyi Edon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 22, text = "Men non pitit Lotan yo: Se te Ori ak Eman. Timna te sè Lotan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 23, text = "Men non pitit Chobal yo: Se te Alvan, Manaat, Ebal, Chefo ak Anam.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 24, text = "Men non pitit Zibeyon yo: Se te Aja ak Ana. Se Ana sa a ki te jwenn sous dlo cho yo nan dezè a, lè l' t'ap gade bourik Zibeyon, papa l' yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 25, text = "Men non pitit Ana yo: Se te Dichon, yon gason ak Olibama, yon fi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 26, text = "Men non pitit gason Dichon yo: Se te Emdan, Echban, Jitran ak Keran.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 27, text = "Men non pitit gason Ezè yo: Se te Bilan, Zavan ak Akan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 28, text = "Men non pitit gason Dichan yo: Ouz ak Aran.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 29, text = "Men non chèf moun peyi Ori yo: Se te Lotan, Chobal, Zibeyon, Ana,", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 30, text = "Dichon, Ezè, Dichan. Se te tout chèf moun Ori yo sa. Se yo ki te chèf branch fanmi moun Ori yo nan peyi Seyi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 31, text = "Men wa ki te gouvènen peyi Edon an, anvan te gen ankenn wa pou gouvènen pèp Izrayèl la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 32, text = "Bela, gason Beyò a, t'ap gouvènen peyi Edon. Yo te rele lavil kote li te rete a Denaba.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 33, text = "Lè Bela mouri, se Jobab, gason Zerak la, moun lavil Bozra, ki te gouvènen nan plas li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 34, text = "Lè Jobab mouri, se Oucham, moun peyi Teman, ki te gouvènen nan plas li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 35, text = "Lè Oucham mouri, se Adad, pitit gason Bedad la, ki te gouvènen nan plas li. Se Adad sa a ki te bat moun peyi Madyan yo nan plenn Moab la. Yo te rele lavil kote li te rete a Avit.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 36, text = "Lè Adad mouri, se Samla, moun Masreka, ki te gouvènen nan plas li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 37, text = "Lè Samla mouri, se Sayil, moun lavil Reyobòt bò gwo larivyè Lefrat la, ki te gouvènen nan plas li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 38, text = "Lè Sayil mouri, se Baalanan, pitit gason Akbò a, ki te gouvènen nan plas li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 39, text = "Lè Baalanan, pitit gason Akbò a, mouri, se Ada ki te gouvènen nan plas li. Yo te rele lavil kote li te rete a Paou. Madanm li te rele Metabèl. Se te pitit fi Matrèd ki poutèt pa l' tè pitit fi Mezarab.", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 40, text = "Men lis non tout pitit Ezaou yo ki te chèf ansanm ak non branch fanmi yo ak non kote yo te rete: Timna, Alva, Jetèt,", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 41, text = "Olibama, Ela, Penon,", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 42, text = "Kenaz, Teman, Mibza,", bookId = 1),
        Verse(book = "Jenèz", chapter = 36, verseNumber = 43, text = "Magdiyèl, Iram. Se non chèf Edon yo sa ansanm ak non kote yo te rete nan peyi a. Se Ezaou ki papa yo tout nan peyi Edon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 1, text = "Men Jakòb rete rete l' nan peyi Kanaran kote papa l' te pase tout lavi l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 2, text = "Men istwa fanmi Jakòb la. Jozèf te yon jenn gason disètan. Li t'ap gade mouton ak kabrit ansanm ak frè l' yo, pitit gason Bila ak Zilpa, fanm kay papa l' yo. Li te konn rapòte bay papa l' tout vye bagay yo t'ap fè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 3, text = "Izrayèl menm te renmen Jozèf plis pase tout lòt pitit li yo, paske li te fin granmoun lè Jozèf te fèt. Li fè yon bèl varèz long ak manch pou li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 4, text = "Lè frè l' yo wè jan papa yo te renmen Jozèf plis pase yo, yo pran rayi l'. Yo pa t' louvri bouch avè l' san yo pa joure l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 5, text = "Yon jou, Jozèf fè yon rèv. Li rakonte l' bay frè li yo. Sa te fè yo rayi l' pi plis toujou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 6, text = "Li di yo: -Mesye, tande yon rèv mwen fè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 7, text = "Mwen wè nou tout nou te nan jaden, chak moun t'ap mare yon pakèt zèb. Pakèt mwen an rete konsa li kanpe tout dwat pou kont li, epi tout pakèt pa nou yo fè wonn li, yo vin bese tèt devan pa m' lan tankou moun y'ap salwe.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 8, text = "Frè l' yo di l': -Anhan! Ou vle di ou pral chèf nou, ou pral kòmande nou! Yo te vin rayi l' pi plis toujou poutèt rèv li te di yo li fè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 9, text = "Apre sa, Jozèf fè yon lòt rèv ankò. Li rakonte l' bay frè li yo. Li di yo: -Mwen fè yon lòt rèv. Mwen wè solèy la, lalen lan ansanm ak onz zetwal ki t'ap bese tèt devan mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 10, text = "Li rakonte rèv la bay papa l' ansanm ak frè l' yo. Men papa a t'ap rale zòrèy li, li t'ap di l': -Ki kalite rèv w'ap fè konsa a? Koulye a, se pou mwen menm, manman ou ansanm ak onz frè ou yo, pou nou vin bese tèt devan ou?", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 11, text = "Frè Jozèf yo t'ap fè jalouzi, men papa l' t'ap kalkile tout bagay sa yo nan tèt li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 12, text = "Frè Jozèf yo leve, y ale jouk Sichèm ak bann bèt papa yo pou fè yo manje.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 13, text = "Izrayèl rele Jozèf, li di l' konsa: -Frè ou yo mennen bèt yo jouk Sichèm al manje. Vini non, m'ap voye ou bò kote yo pou mwen. Jozèf reponn: -Men mwen wi, papa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 14, text = "Izrayèl di l' konsa: -Tanpri, ale we kouman frè ou yo ak bèt yo ye laba a. Apre sa, tounen vin pote nouvèl yo ban mwen. Konsa, se papa l' menm ki te fè l' pati kite Fon Ebwon an. Lè Jozèf rive Sichèm,", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 15, text = "li pèdi wout li nan savann lan, li kontre ak yon nonm ki mande l': -Kisa w'ap chache konsa?", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 16, text = "Jozèf reponn li: -M'ap chache frè m' yo. Tanpri, di m' ki kote yo mennen bèt yo al manje.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 17, text = "Nonm lan di l': -Yo te isit la wi, men yo pati deja. Mwen tande yo t'ap di yo pral Dotan. Jozèf pati dèyè frè l' yo, li jwenn yo Dotan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 18, text = "Men, anvan Jozèf te rive, yo te gen tan wè l' byen lwen ap vini. Yo fè konplo pou yo touye l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 19, text = "Yonn di lòt: -Men nonm ki renmen fè rèv la ap vini.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 20, text = "Annou wè. N'ap touye l', n'ap jete kadav la nan yonn nan pi yo. Epi n'a di se bèt nan bwa ki touye l'. Konsa n'a wè si sa l' te wè nan rèv li yo va rive vre.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 21, text = "Woubenn t'ap koute yo, li t'ap chache yon jan pou sove Jozèf anba men yo. Li di yo: -Piga nou touye l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 22, text = "Pa fè san koule. Ann voye l' jete nan pi sa a ki nan dezè a. Men, pa leve men sou li. Li t'ap di yo sa paske li te fè lide sove l' anba men yo pou l' te voye l' tounen bay papa l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 23, text = "Lè Jozèf rive bò kote frè l' yo, yo wete bèl varèz long ak manch ki te sou li a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 24, text = "Yo pran l', yo jete l' nan pi a. Pi a te vid, li pa t' gen dlo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 25, text = "Apre sa, yo chita pou yo manje. Pandan yo leve je yo, konsa yo wè yon kolonn moun Izmayèl ki t'ap vwayaje. Yo te soti Galarad. Chamo yo te chaje ak gonm bwa, lansan ak lami yo t'ap pote al vann nan peyi Lejip.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 26, text = "Jida di frè l' yo konsa: -Sa sa ap rapòte nou pou nou touye frè nou an epi apre sa pou nou kache sa?", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 27, text = "Annou vann li ak moun Izmayèl yo. Konsa nou p'ap bezwen leve men nou sou li. Apre tou, se frè nou li ye, se menm san ak nou. Frè l' yo tonbe dakò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 28, text = "Lè machann Madyan yo vin ap pase, yo rale Jozèf moute sot nan pi a. Yo vann li ak moun Izmayèl yo pou vin pyès lajan. Moun Izmayèl yo menm mennen l' nan peyi Lejip.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 29, text = "Lè Woubenn tounen nan pi a, li pa jwenn Jozèf ladan l'. Sa te fè l' lapenn anpil. Li chire rad ki te sou li a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 30, text = "Li tounen al jwenn frè li yo, li di yo: -Ti gason an pa nan pi a non! Kisa m' pral fè koulye a?", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 31, text = "Yo touye yon bouk kabrit, yo pran bèl varèz Jozèf la, yo tranpe l' nan san an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 32, text = "Yo voye varèz la bay papa yo ak komisyon sa a: -Men sa nou jwenn. Gade wè si se pa varèz pitit gason ou lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 33, text = "Jakòb rekonèt rad la, li di: -Men wi, se varèz pitit gason m' lan. Se yon bèt nan bwa ki devore l'. Bèt la dechèpiye l' nèt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 34, text = "Sa ou tande a, yon sèl lapenn pran Jakòb, li chire rad ki te sou li, li mare yon tanga sak nan ren li. Li pase kèk tan ap kriye pou pitit gason l' lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 35, text = "tout lòt gason l' yo ansanm ak pitit fi l' yo te vin ba l' kouraj, men li te refize tande sa yo t'ap di l'. Li t'ap plede repete: -M'ap kriye pou pitit gason m' lan jouk m al jwenn li lè m'a mouri. Se konsa li t'ap kriye pou pitit gason l' lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 37, verseNumber = 36, text = "Pandan tout tan sa a, moun Madyan yo te gen tan vann Jozèf nan peyi Lejip ak Potifa, yonn nan chèf lame farawon an. Se li menm ki te kòmandan gad palè yo.", bookId = 1)
    )

    private val part4 = listOf(
        Verse(book = "Jenèz", chapter = 38, verseNumber = 1, text = "Lè sa a, Jida kite frè l' yo, li al jwenn Ira, yon nonm lavil Adoulam.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 2, text = "Antan li la, li wè yon fi. Papa fi a te yon moun peyi Kanaran yo te rele Chwa. Jida marye ak fi a, li kouche avè l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 3, text = "Madanm lan vin ansent, li fè yon pitit gason. Jida rele pitit la Er.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 4, text = "Madanm lan vin ansent ankò, li fè yon lòt pitit gason, yo rele l' Onan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 5, text = "Li fè yon lòt pitit gason ankò, yo rele l' Chela. Jida te lavil Kezib lè madanm li fè Chela.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 6, text = "Jida chwazi yon fi yo rele Tama pou Er, premye pitit gason l' lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 7, text = "Men Er, premye pitit Jida a, pa t' fè Seyè a plezi paske li te twò mechan. Se konsa Seyè a te fè l' mouri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 8, text = "Lè sa a, Jida di Onan: -Ale jwenn madanm frè ou la, kouche avè l'. Se devwa ou, paske ou se frè mari l' ki mouri. Konsa, w'a fè yon pitit pou frè ou pou non li pa pèdi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 9, text = "Men Onan te konnen pitit la pa t'ap pou li. Se konsa, chak fwa li kouche ak madanm frè li a, li voye atè pou li pa t' fè pitit pou frè li a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 10, text = "Sa l' t'ap fè a pa t' fè Seyè a plezi. Se konsa Seyè a fè l' mouri tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 11, text = "Lè sa a, Jida di Tama, bèlfi li a: -Ou mèt tounen kay papa ou, rete vèv san marye jouk tan Chela, lòt gason m' lan, vin gran. Li te di l' sa paske li te pè pou Chela pa t' mouri tankou frè l' yo. Tama menm tounen rete kay papa l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 12, text = "Kèk tan apre sa, madanm Jida, pitit fi Chwa a, mouri. Apre Jida te fin fè sa pou l' te fè pou lanmò a, li moute al Timna ansanm ak zanmi l' lan, Ira, moun Adoulam lan. Li tapral wè moun ki t'ap taye lenn mouton l' yo pou li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 13, text = "Yo fè Tama konn sa, yo di l': -Gade. Men bòpè ou ap moute al Timna, pou l' fè taye lenn mouton li yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 14, text = "Se konsa, Tama wete rad vèv ki te sou li a, li kouvri tèt li ak yon vwal, li al chita bò pòtay lavil Enayim, sou chemen ki mennen Timna a. Li te wè Chela te fin gran, men Jida pa t' pran l' bay Chela pou madanm.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 15, text = "Lè Jida wè l', li konprann se te yon jennès, paske figi l' te kouvri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 16, text = "li al jwenn li bò chemen an, li di l': -vin non. Kite m' kouche avè ou. Li pa t' konnen se bèlfi li li te ye. Tama di li: -Kisa w'ap ban mwen pou m' kite ou kouche avè m'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 17, text = "Jida reponn li: -m'a voye yon jenn kabrit ba ou nan bèt mwen yo. Tama di li: -Kisa w'a ban m' kenbe jouk ou voye l' ban mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 18, text = "Jida reponn li: -Kisa ou vle m' ba ou kenbe? Tama di li: -Letanp ou a ak tout kòd li, ansanm ak baton ki nan men ou lan. Jida ba li yo. Li kouche ak li. Tama vin ansent pou li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 19, text = "Apre sa Tama leve, li al fè wout li. Li wete vwal la, epi li mete rad vèv li sou li ankò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 20, text = "Jida voye zanmi l', moun lavil Adoulam lan, ak jenn kabrit la pou l' te ka reprann sa l' te bay fanm lan kenbe a. Men zanmi l' lan pa t' kapab jwenn fanm lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 21, text = "Li mande mesye ki te la yo. Kote jennès ki te chita bò chemen an, sou pòtay lavil Enayim lan? Yo reponn li: -Pa janm gen ankenn jennès bò isit la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 22, text = "Li tounen al jwenn Jida, li di l': -Mwen pa jwenn li non. Mesye nan zòn lan di m' pa janm gen ankenn jennès bò la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 23, text = "Jida di l': -Pa fatige kò ou chache reprann sak nan men l' lan. Moun va pase m' nan betiz twòp. Mwen voye kabrit la ba li, ou pa jwenn li. Kite sa!", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 24, text = "Sou twa mwa konsa, yo vin di Jida: -Tama, bèlfi ou la, lage kò l' nan jennès. Li gen tan ansent. Jida di yo: -Pran l', mennen l' deyò lavil la. Mete dife anwo l' jouk li mouri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 25, text = "Yo t'ap mennen Tama deyò lavil la lè li voye komisyon sa a bay bòpè li: -Se pou mèt bagay sa yo mwen ansent. Gade wè si ou rekonèt ki moun ki mèt letanp sa a ak tout kòd li ansanm ak baton sa a?", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 26, text = "Jida rekonèt yo, li di: -Li gen rezon. Se mwen menm ki antò. Mwen te dwe fè l' marye ak Chela, pitit gason m' lan. Jida pa t' kouche avè l' ankò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 27, text = "Lè lè a rive pou Tama akouche, yo wè li te gen marasa nan vant li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 28, text = "Pandan li te gen tranche, yonn nan timoun yo lonje men l' deyò. Fanmchay la kenbe men an, li mare yon moso fil wouj ladan l'. Li di: -Sa a fèt anvan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 29, text = "Men pitit la rale men an antre, epi se lòt frè a ki soti anvan. Fanmchay la di: -Se konsa ou fè chemen pou ou pase! Se poutèt sa yo rele l' Perèz.", bookId = 1),
        Verse(book = "Jenèz", chapter = 38, verseNumber = 30, text = "Apre sa, frè li a soti ak fil wouj la mare nan men l'. Yo rele l' Zerak.", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 1, text = "Moun Izmayèl yo te mennen Jozèf nan peyi Lejip. Rive la, Potifa, yon moun peyi Lejip ki te chèf nan gouvènman farawon an ak kòmandan gad palè yo, achte l' nan men yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 2, text = "Seyè a te kanpe la avèk Jozèf. Li te fè tout bagay mache byen pou li. Jozèf te rete kay mèt li, moun peyi Lejip la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 3, text = "Mèt li tout te wè Seyè a te avèk Jozèf. Seyè a te fè tout zafè l' mache byen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 4, text = "Potifa te kontan ak Jozèf ak jan li t'ap sèvi li. Li mete l' reskonsab kay li, li renmèt li tout sa li te genyen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 5, text = "Depi lè Potifa te renmèt kay li ansanm ak tout sa li te genyen bay Jozèf, Seyè a beni kay moun peyi Lejip la poutèt Jozèf. Seyè a beni tout sa li te gen lakay li ak nan jaden l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 6, text = "Potifa te lage tout zafè l' nan men Jozèf. Li pa t' okipe anyen ankò, se annik vin chita manje. Jozèf te vin yon bèl gason byen kanpe.", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 7, text = "Se konsa madanm mèt li a vin tonbe pou li. Li di l': -vin kouche avè m' non!", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 8, text = "Men Jozèf derefize, li di l': -Mèt mwen an pa okipe anyen k'ap pase nan kay li a, paske mwen la. Li lage tout bagay nan men m'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 9, text = "Mwen gen menm otorite avè l' nan kay la, li pa defann mwen manyen anyen, esepte ou menm, paske se madanm li ou ye. Ki jan ou ta vle pou m' fè yon bagay konsa, pou m' fè peche sa a kont Bondye?", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 10, text = "Se chak jou li te nan kò Jozèf. Men, Jozèf te toujou derefize kouche avè l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 11, text = "Yon jou, Jozèf vin pou fè travay li nan kay la. Lè sa a pesonn pa t' la:", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 12, text = "Madanm lan kenbe rad Jozèf, li di l': -Jòdi a, se pou ou kouche avè m'. Lè Jozèf wè sa, li chape kò l' met deyò, li kite rad la nan men madanm lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 13, text = "Madanm lan menm, lè li wè Jozèf te kite rad la nan men l' pou l' kouri ale deyò,", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 14, text = "li rele domestik li yo, li di yo: -Nou wè sa! Mari mwen mennen yon ebre nan kay la, men koulye a li soti pou avili m'. Li vini jwenn mwen jouk isit la, li vle pou m' kouche avè l'. Mwen pete rele.", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 15, text = "Lè li tande m' rele a, msye kouri, li met deyò, li kite rad li la bò kote m'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 16, text = "Madanm lan kite rad la bò kote l', li tann mèt Jozèf la tounen lakay la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 17, text = "Li rakonte l' menm bagay la, li di l': -Esklav ebre ou mennen lakay la vin jwenn mwen jouk isit la pou avili m'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 18, text = "Men, mwen pete yon rèl, li kouri met deyò, li kite rad li bò kote m'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 19, text = "Lè Potifa tande madanm li di l' sa domestik li a te fè l', li move sou Jozèf.", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 20, text = "Li fè arete l', mete l' nan prizon kote yo fèmen tout prizonye wa a. Se konsa Jozèf twouve l' nan prizon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 21, text = "Men Seyè a te kanpe la avèk Jozèf. Li moutre l' jan l' te renmen l', li fè chèf prizon an gen Jozèf konfyans.", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 22, text = "Li mete l' veye tout lòt prizonye yo. Se li menm ki te reskonsab tout bagay nan prizon an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 39, verseNumber = 23, text = "Depi li te renmèt yon bagay nan men Jozèf, li pa t' bezwen okipe anyen ankò paske Seyè a te la avèk Jozèf. Seyè a te fè tout zafè l' mache byen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 1, text = "Kèk tan apre sa, chèf kanbiz ak chèf boulanje wa Lejip la te fè mèt yo yon bagay.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 2, text = "Farawon an te move ni sou chèf kanbiz la ni sou chèf boulanje a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 3, text = "Se konsa li te mete yo lakay kòmandan gad palè a, kote yo te fèmen Jozèf nan prizon an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 4, text = "Kòmandan gad palè a mete yo sou kont Jozèf pou l' sèvi yo. Yo pase kèk tan nan prizon an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 5, text = "Yon jou lannwit, antan yo nan prizon an, chèf kanbiz ak chèf boulanje wa a te fè yo chak yon rèv. Chak rèv te gen sans pa yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 6, text = "Lè Jozèf vin jwenn yo nan denmen maten, li jwenn yo boulvèse.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 7, text = "Li mande yo: -Poukisa nou kagou konsa jòdi a?", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 8, text = "Yo reponn li: -Nou chak fè yon rèv, men pa gen pesonn isit la ki ka esplike nou rèv yo. Jozèf reponn yo: -Eske se pa Bondye sèl ki ka esplike bagay konsa? Rakonte m' rèv nou yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 9, text = "Chèf kanbiz la rakonte Jozèf rèv li te fè a, li di l': -Nan rèv mwen an, mwen wè yon pye rezen devan m'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 10, text = "Li te gen twa branch. Branch yo pran boujonnen, yo fè flè, yo fè rezen, rezen yo mi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 11, text = "Gwo gode farawon an te nan men mwen. Mwen pran rezen yo, mwen pije yo nan gode farawon an, lèfini mwen bay wa a li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 12, text = "Jozèf di li: -Men sa rèv la vle di: Twa branch yo se twa jou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 13, text = "Nan twa jou, farawon an pral chonje ou, li pral mete ou nan pozisyon ou ankò. Ou pral bay farawon an diven jan ou te konn fè l' anvan lè ou te chèf kanbiz li a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 14, text = "Men, lè tout bagay va mache byen pou ou, pa bliye m'. Tanpri, rann mwen sèvis sa a, pale ak farawon an pou mwen. Fè m' soti nan prizon sa a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 15, text = "Ou wè: se vòlè yo te vòlè m' nan peyi Ebre yo. Isit la menm, mwen pa t' fè anyen pou yo te mete m' nan prizon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 16, text = "Lè chèf boulanje a wè bèl esplikasyon Jozèf te bay lòt la, li di l': -Mwen menm tout mwen fè yon rèv. Mwen wè te gen twa panyen pen sou tèt mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 17, text = "Nan panyen ki te anwo nèt la, te gen tout kalite bagay yo konn kwit nan fou pou wa a. Men, zwazo t'ap manje yo nan panyen an sou tèt mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 18, text = "Jozèf reponn li: -Men sa rèv la vle di: Twa panyen yo se twa jou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 19, text = "Nan twa jou farawon an pral fè rele ou, l'ap fè yo pann ou nan yon pyebwa, kote zwazo ap vin dechèpiye ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 20, text = "Sou twa jou vre, farawon an t'ap fè yon gwo resepsyon pou tout chèf ki t'ap sèvi avè l' yo, paske se te jou fèt li. Li fè rele chèf kanbiz la ak chèf boulanje a devan tout lòt chèf yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 21, text = "Li mete chèf kanbiz la nan plas li ankò pou sèvi l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 22, text = "Men, li fè pann chèf boulanje a, jan Jozèf te di yo a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 40, verseNumber = 23, text = "Men, chèf kanbiz la pa dòmi reve Jozèf, li bliye l' nèt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 1, text = "Dezan te fin pase. Farawon an fè yon rèv. Li wè li te kanpe bò larivyè Nil la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 2, text = "Li wè sèt bèl vach byen gra moute soti nan larivyè a, yo t'ap manje zèb bò dlo a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 3, text = "Apre sa, sèt lòt vach tout lèd, tout mèg, moute soti nan dlo a tou. Yo vin kanpe toupre lòt vach yo, bò dlo a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 4, text = "Sèt vye vach mèg yo manje sèt bèl vach gra yo. Epi je farawon an vin klè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 5, text = "Dòmi pran l' ankò, li fè yon lòt rèv. Li wè sèt gwo grap ble ki t'ap pouse sou yon sèl pye ble. Yo te plen grenn, yo te mi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 6, text = "Apre sa, sèt lòt grap vin parèt sou menm pye ble a. Yo te chèch, van nòde te fin boule yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 7, text = "Sèt grap chèch yo souse sèt bèl grap yo. Epi je farawon an vin klè ankò. Se rèv sa yo li te fè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 8, text = "Nan maten, li te boulvèse anpil, li voye chache dènye divinò ak nèg save ki nan peyi Lejip la. Li rakonte yo rèv la, men yo yonn pa t' kapab esplike rèv la ba li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 9, text = "Se lè sa a, chèf kanbiz la di farawon an: -Koulye a mwen chonje mwen te fè yon fòt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 10, text = "Yon jou, monwa, ou te ankòlè sou sèvitè ou yo. Ou te fè mete yo nan prizon lakay kòmandan gad palè ou la. Se te mwen menm, chèf kanbiz ou a, ansanm ak chèf boulanje ou la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 11, text = "Yon jou lannwit, nou tout de nou reve. Chak moun te fè yon rèv diferan. Chak rèv te gen sans pa l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 12, text = "Te gen yon jenn ebre avèk nou nan prizon an. Se te yon esklav kòmandan gad palè a. Nou rakonte l' rèv nou yo. Epi li esplike yo ban nou, li bay chak moun sans rèv li te fè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 13, text = "tout bagay pase jan li te di a: Sou twa jou vre, farawon an te mete m' nan plas mwen ankò. Pou chèf boulanje a menm, li te fè pann li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 14, text = "Farawon an voye chache Jozèf. Yo fè l' soti byen vit nan prizon an. Jozèf fè labab, li koupe cheve l', li chanje rad, epi li parèt devan farawon an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 15, text = "Farawon an di Jozèf konsa: -Mwen fè yon rèv, pesonn pa ka di m' sa l' vle di. Men yo di m' depi yo rakonte ou yon rèv, ou ka esplike l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 16, text = "Jozèf reponn farawon an: -Se pa mwen menm non! Se Bondye ki pral bay farawon an esplikasyon rèv la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 17, text = "Farawon an di: -Mwen reve mwen te kanpe bò larivyè Nil la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 18, text = "Konsa, sèt bèl vach byen gra te moute soti nan larivyè a, yo t'ap manje zèb bò dlo a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 19, text = "Apre sa, sèt lòt vach tout mèg, tout lèd, tout chèch te moute soti nan dlo a dèyè lòt yo. Mwen poko janm wè vye vach lèd konsa nan tout peyi Lejip la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 20, text = "Vye vach mèg yo manje bèl vach gra yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 21, text = "Lè yo te fin vale yo, se tankou si yo pa t' janm manje. Yo te rete menm jan yo te ye anvan an. Epi je m' vin klè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 22, text = "Apre sa, mwen fè yon lòt rèv. Mwen wè sèt grap ble byen plen, byen mi ki t'ap pouse ansanm sou yon sèl pye ble a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 23, text = "Apre sa, sèt lòt grap parèt dèyè yo. Yo te chèch, van nòde te fin boule yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 24, text = "Grap mèg yo souse sèt bèl grap yo. Mwen rakonte rèv yo bay divinò yo, men yo yonn pa t' kapab esplike yo ban mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 25, text = "Jozèf di farawon an: -tout de rèv yo vle di menm bagay la: Bondye fè ou konnen sa li pral fè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 26, text = "Sèt vach gra yo, se sèt lanne. Sèt bèl grap yo se sèt lanne tou. Yo vle di menm bagay.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 27, text = "Sèt vach tout mèg, tout lèd ki vin apre lòt yo, se sèt lanne. Sèt grap ble boule yo, se sèt lanne tou. Sa vle di pral gen sèt lanne grangou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 28, text = "Se jan m' sot di farawon an: Bondye vle fè ou konnen sa li pral fè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 29, text = "Pandan sèt lanne pral gen bèl rekòt nan tout peyi Lejip la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 30, text = "Apre sa, pral gen sèt lanne grangou. Lè sa a, moun pral bliye tout bèl rekòt yo te fè nan peyi a. Grangou pral fini nèt ak peyi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 31, text = "Grangou ki pral tonbe sou peyi a pral rèd anpil. Moun p'ap wè tras rekòt ki te fèt nan peyi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 32, text = "Si farawon an fè menm rèv la de fwa, sa vle di Bondye gen tan fin fè plan l' nèt. Se yon bagay Bondye pral fè talè konsa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 33, text = "Koulye a, se pou farawon an chwazi yon moun ki gen lespri ak bon konprann pou l' mete l' chèf sou tout peyi Lejip la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 34, text = "Se pou ou mete chèf toupatou nan peyi Lejip la, pou yo ranmase yon senkyèm nan tout rekòt ki pral fèt pandan sèt bon lanne yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 35, text = "Se pou yo ranmase pwovizyon pandan tout lanne ki pral vini yo. Se pou farawon an ba yo otorite pou yo anpile pwovizyon yo nan depo nan chak vil, lèfini pou yo veye yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 36, text = "Konsa, pwovizyon sa yo va sèvi yon rezèv pou peyi a pandan sèt lanne grangou k'ap vin tonbe apre sa sou peyi Lejip, pou grangou pa fini ak peyi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 37, text = "Farawon an ak tout moun pa l' yo te tonbe dakò ak sa Jozèf te di a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 38, text = "Farawon an di moun pa l' yo: -Ki bò nou ka jwenn yon moun ki gen lespri Bondye sou li tankou nonm sa a?", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 39, text = "Farawon an di Jozèf: -Gade tout bagay Bondye fè ou konnen! Pa gen pesonn ki gen plis lespri, osinon plis bon konprann pase ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 40, text = "M'ap mete ou chèf sou tout peyi mwen an. Se pou tout moun nan peyi a obeyi ou. Se sèlman paske mwen wa kifè mwen menm m'a pi gwo chèf pase ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 41, text = "Apre sa, farawon an di Jozèf: -Gade, m'ap mete ou chèf pou gouvènen tout peyi Lejip la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 42, text = "Li wete gwo bag ki te nan dwèt li a, li mete l' nan dwèt Jozèf. Li abiye l' ak yon rechanj fèt ak bèl twal fen. Li pase yon chenn an lò nan kou l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 43, text = "Li fè l' moute sou yon cha. Se te pi bèl cha nan tout peyi a apre cha wa a. Li bay gad onè ki t'ap mache devan Jozèf yo lòd pou yo di byen fè: Abrèk. Se konsa farawon an te mete Jozèf chèf sou tout peyi Lejip la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 44, text = "Farawon an di Jozèf: -Se mwen menm farawon an k'ap pale avèk ou. Pesonn pa gen dwa fè anyen ni al ankenn kote nan peyi Lejip san pèmisyon ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 45, text = "Farawon an rele Jozèf Safna-Paneak. Li pran Asnat, pitit fi Potifera, yon prèt lavil On, li bay Jozèf li pou madanm. Jozèf al vizite tout peyi Lejip la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 46, text = "Jozèf te gen trantan lè li te konmanse sèvi farawon an, wa peyi Lejip la. Li pati, li vwayaje toupatou nan peyi Lejip la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 47, text = "Pandan sèt bon lanne yo, tè a te bay anpil anpil rekòt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 48, text = "Jozèf ranmase pwovizyon pandan sèt lanne bon rekòt yo nan tout peyi a, li mete yo nan depo nan lavil yo. Chak lavil te gen kont depo pou sere tout sa jaden alantou yo te bay.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 49, text = "Li ranmase ble, li ranmase ble tankou ou ta di sab bò lanmè. Sitèlman te gen anpil ble, yo pa t' ka konnen kantite ki te genyen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 50, text = "Anvan lanne grangou yo mete pye, Jozèf te gen tan gen de pitit ak Asnat, pitit fi Potifera, prèt lavil On an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 51, text = "Jozèf rele premye a Manase paske li t'ap di nan kè l': Bondye fè m' bliye tout soufrans mwen ansanm ak moun lakay papa m' yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 52, text = "Li rele dezyèm lan Efrayim paske li t'ap di nan kè l': Bondye fè m' fè pitit nan peyi kote m'ap soufri a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 53, text = "Sèt bon lanne rekòt yo te fin pase nan peyi Lejip la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 54, text = "Sèt lanne grangou yo te konmanse jan Jozèf te di a. Grangou t'ap bat nan tout lòt peyi yo tou, men te gen manje toujou nan tout peyi Lejip la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 55, text = "Men, yon lè grangou konmanse mete pye nan peyi Lejip la tou. Pèp la menm pran rele nan zòrèy farawon an, y'ap mande manje. Farawon an di moun peyi Lejip yo: -Al jwenn Jozèf. Se li menm ki va di nou sa pou nou fè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 56, text = "Lè grangou a te toupatou nan peyi Lejip la, Jozèf louvri tout depo yo. Li vann moun peyi Lejip yo ble, paske grangou a te rèd anpil nan peyi Lejip la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 41, verseNumber = 57, text = "Moun soti toupatou nan tout lòt peyi yo vin achte ble nan men Jozèf nan peyi Lejip, paske grangou a te rèd anpil toupatou sou latè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 1, text = "Lè Jakòb vin konnen te gen ble pou vann nan peyi Lejip, li di pitit li yo: -Poukisa nou chita konsa yonn ap gade lòt, de bra kwaze?", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 2, text = "Mwen tande y'ap vann ble nan peyi Lejip. Desann non, al achte ble pou nou ka viv pou nou pa mouri grangou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 3, text = "Se konsa, dis nan frè Jozèf yo desann nan peyi Lejip, y al achte ble.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 4, text = "Men Jakòb pa t' voye Benjamen, lòt frè Jozèf menm manman avè l' la, avèk yo paske li te pè pou malè pa t' rive l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 5, text = "Grangou a te rèd nan peyi Kanaran an tou. Se konsa, pitit Izrayèl yo te vwayaje ansanm ak lòt moun ki tapral achte ble tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 6, text = "Se Jozèf ki t'ap gouvènen sou tout peyi Lejip la. Se nan men l' moun te konn soti toupatou vin achte manje. Frè Jozèf yo rive, yo bese tèt yo byen ba jouk atè pou di l' bonjou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 7, text = "Lè Jozèf wè frè l' yo, li rekonèt yo. Men li pran pòz pa konnen yo. Li pale rèd ak yo. Li di: -Ki bò nou soti? Yo reponn: -Nou soti peyi Kanaran, nou vin achte manje.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 8, text = "Jozèf te rekonèt frè l' yo, men yo menm yo pa t' rekonèt li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 9, text = "Le sa a Jozèf vin chonje rèv li te fè sou frè l' yo. Li di yo: -Nou se yon bann espyon. Nou vin isit la pou n' chache konnen pwen fèb peyi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 10, text = "Yo reponn li: -Non, mèt. Nou se moun pa ou, se manje nou vin achte isit la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 11, text = "Nou tout nou se pitit yon sèl papa. Nou p'ap ba ou manti, se pa espyon nou ye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 12, text = "Jozèf di yo: -Se pa vre. Nou vin isit la pou n' chache konnen pwen fèb peyi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 13, text = "Yo di l': -Nou se douz frè, pitit yon sèl papa nan peyi Kanaran. Dènye a rete ak papa nou. Gen yonn nan nou ki disparèt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 14, text = "Jozèf reponn yo: -Nou wè mwen gen rezon lè m' di se yon bann espyon nou ye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 15, text = "Men ki bò mwen pral kenbe nou: M'ap fè sèman sou tèt farawon an, nou p'ap soti isit la tout tan nou pa fè ti frè nou an vini isit la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 16, text = "Voye yonn nan nou al chache l'. Lòt yo ap rete nan prizon. Se konsa, m'a wè nou pa t'ap bay manti. Si se pa sa, mwen fè sèman sou tèt farawon an, se espyon nou ye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 17, text = "Li fè fèmen yo tout nan prizon pandan twa jou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 18, text = "Sou twazyèm jou a, Jozèf di yo: -Men sa pou n' fè, si nou vle sove lavi nou: Mwen menm mwen se moun ki respekte Bondye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 19, text = "Si nou konnen nou p'ap bay manti se pou yonn nan nou rete fèmen nan prizon kote yo te fèmen nou an. Lòt yo mèt pote ble a ale pou fanmi nou yo ka manje.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 20, text = "Men, ti frè nou an, sa ki pi piti a, se pou nou mennen l' ban mwen, pou nou ka moutre m' nou pa t' ban m' manti. Konsa, yo p'ap touye nou. Yo tonbe dakò sou sa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 21, text = "Yonn t'ap di lòt: -Nou wè. Nou peye sa nou te fè frè nou an pase. Se vre wi. Nou te fè mal lè nou te fè frè nou an pase tout sa nou te fè l' la. Nou te wè ki jan sa te fè l' lapenn anpil, lè li t'ap mande nou fè l' gras. Men, nou pa t' vle koute l'. Se poutèt sa nou nan tout traka sa a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 22, text = "Woubenn di yo: -Mwen te di nou pa fè tibway la anyen, men nou pa t' vle koute m'. Koulye a se lanmò tibway la n'ap peye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 23, text = "Jozèf te konprann tout sa yo t'ap di a. Men yo pa t' konn sa paske te gen yon moun ki t'ap tradwi pou yo lè yo t'ap pale avè l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 24, text = "Jozèf soti kote yo te ye a, li al kriye. Lèfini li tounen, li pale ak yo, li pran Simeyon, li fè yo mete l' nan chenn, la devan yo tout.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 25, text = "Jozèf te bay lòd pou yo te plen sak yo avèk ble, pou yo te mete lajan yo chak nan sak yo ankò, lèfini pou yo ba yo manje pou yo manje sou wout la. Se sa yo te fè vre.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 26, text = "Frè yo menm chaje bourik yo ak ble yo te achte a, yo pati.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 27, text = "Lè yo rive kote yo t'ap pase nwit la a, yonn ladan yo louvri sak li pou l' te ka bay bourik li manje. Li jwenn lajan li te bay la nan sak la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 28, text = "Li di frè l' yo. -Yo renmèt mwen lajan m' lan wi. Men li nan sak mwen an. Kè yo kase. Yo t'ap tranble kou fèy bwa tèlman yo te pè. Yonn t'ap di lòt: -Kisa Bondye fè nou konsa?", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 29, text = "Lè yo rive kay Jakòb, papa yo, nan peyi Kanaran, yo rakonte l' tout sa ki te pase. Yo di l':", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 30, text = "-Nèg k'ap gouvènen peyi a pale rèd ak nou. Li pran nou pou espyon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 31, text = "Nou di l' nou p'ap ba l' manti, se pa espyon nou ye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 32, text = "Se douz frè nou ye, pitit yon sèl papa. Yonn nan nou disparèt, dènye a rete ak papa nou nan peyi Kanaran.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 33, text = "Men chèf peyi a di nou: Men ki jan m'ap konnen si nou p'ap ban m' manti: Kite yonn nan frè nou yo isit la avèk mwen. Pran sa nou bezwen pou fanmi nou. Nou mèt ale. Mennen lòt ti frè nou an ban mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 34, text = "Lè sa a, m'a konnen se pa espyon nou ye, nou pa t'ap ban m' manti. m'a renmèt nou frè nou an. m'a kite nou trafike nan peyi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 35, text = "Lè yo vide sak yo, chak moun jwenn ti sakit lajan li te bay la nan bouch sak li ankò. Lè yo wè sa, yon sèl lapè pran yo ansanm ak papa yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 36, text = "Lè sa a Jakòb, papa yo, di: -N'ap wete tout pitit mwen yo nan men m'. Jozèf disparèt, Simeyon pa la ankò. Koulye a, nou vle pran m' Benjamen. Se mwen menm k'ap pote tout chaj la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 37, text = "Woubenn di papa l' konsa: -Papa, ou mèt touye de pitit gason m' yo, si m' pa mennen Benjamen tounen ba ou. Ou mèt renmèt mwen li nan men, m'ap mennen l' tounen ba ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 42, verseNumber = 38, text = "Men Jakòb te di: -Pitit gason m' lan p'ap fè yon pa. Frè li a fin mouri. Se li menm sèl ki rete nan pitit manman l' yo. Si pou yon malè ta rive l' nan vwayaj nou pral fè a, m'a mouri. Mwen fin granmoun, lapenn sa a va twòp pou mwen, la fin pote m' ale.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 1, text = "Grangou t'ap bat pi rèd nan peyi Kanaran an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 2, text = "Lè fanmi Jakòb yo te fin manje ble yo te pote soti nan peyi Lejip la, Jakòb di pitit li yo: -Tounen al chache manje pou nou ankò non.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 3, text = "Jida reponn li: -Nonm lan te byen avèti nou pou nou pa parèt devan l' si nou pa vin ak ti frè nou an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 4, text = "Si ou vle kite ti frè nou an vin ak nou, nou v al achte manje pou ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 5, text = "Si ou pa vle kite l' ale, n'ap rete, paske msye a te tout di nou: piga nou parèt devan l' ankò si nou pa vin ak ti frè nou an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 6, text = "Izrayèl di: -Sa nou te bezwen di l' nou te gen yon ti frè fè? Poukisa nou fè m' sa?", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 7, text = "Yo reponn li: -Msye a t'ap poze nou keksyon sou nou ak sou fanmi nou. Li mande nou si papa nou la toujou, si nou gen lòt frè, se pou n' te reponn li. Kouman pou n' ta fè konnen li tapral mande nou pou nou mennen ti frè nou an ba li?", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 8, text = "Jida di Izrayèl, papa l', konsa: -Kite tibway la ale ak nou. Konsa n'a leve, n'a pati. Konsa ni ou menm, ni nou menm, ni timoun nou yo p'ap mouri grangou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 9, text = "Se nan men m' li ye, se mwen menm ki pou rann ou kont pou li. Si m' pa mennen l' tounen ba ou, si m' pa tounen avè l' la devan ou, se mwen menm k'ap pote fòt la devan ou jouk mwen mouri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 10, text = "Si nou pa t' pran tout reta sa a, koulye a nou ta gen tan ale nou tounen de fwa deja.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 11, text = "Lè sa a, Izrayèl, papa yo, di: -Bon. Si se konsa sa ye, men sa pou n' fè: n'ap pran pi bon danre ki gen nan peyi a, n'ap mete nan sak nou, n'ap pote fè nonm lan kado: gonm santi bon, siwo myèl, lansan, lami, pistach ak nwa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 12, text = "Lèfini, n'a pran de fwa valè lajan nou bezwen, paske fòk nou renmèt lajan yo te mete nan bouch sak ble yo tou. Ou pa janm konnen, yo ka pa t' wè sa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 13, text = "Pran frè nou an, tounen kote msye a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 14, text = "M'ap mande Bondye ki gen tout pouvwa a pou l' fè nonm lan aji byen ak nou, pou l' ka renmèt nou ni lòt frè nou an, ni Benjamen. Pou mwen menm, si se pou m' pèdi pitit mwen yo, mwen mèt pèdi yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 15, text = "Se konsa mesye yo pran kado yo, de fwa valè lajan yo te bezwen ansanm ak Benjamen, yo leve, yo desann peyi Lejip kote yo parèt devan Jozèf.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 16, text = "Lè Jozèf wè Benjamen ak yo, li rele chèf domestik li a, li di l': -Mennen mesye sa yo lakay mwen. Touye yon bèt, kwit li, paske mesye sa yo ap manje avè m' midi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 17, text = "Chèf domestik la fè sa Jozèf te di l' fè a, li mennen mesye yo lakay li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 18, text = "Men, lè mesye yo wè yo t'ap mennen yo lakay Jozèf, yo te pè anpil. Yo t'ap di: -Se poutèt lajan nou te jwenn nan sak nou yo dènye fwa a kifè y'ap mennen nou bò isit la. Yo pral kenbe nou, yo pral bat nou, y'ap fè nou tounen esklav. Lèfini y'ap pran bourik nou yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 19, text = "Se konsa, antan yo rive nan papòt kay la, yo pwoche bò chèf domestik la,", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 20, text = "yo di l': -Eskize nou wi, mèt. Nou te vin isit la yon fwa deja pou n' te achte manje.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 21, text = "Lè n'ap tounen lakay nou, nou rive yon kote nou t'ap poze pou pase nwit, nou louvri sak nou yo, nou jwenn tout lajan an nan bouch sak yo, byen konte. Nou pote l' tounen wi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 22, text = "Nou pote lòt lajan tout pou n' ka achte manje. Nou pa konnen ki moun ki te mete lajan an nan sak nou yo ankò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 23, text = "Domestik anchèf la di yo: -Pa okipe bagay konsa. Nou pa bezwen pè. Se Bondye nou an, Bondye papa nou an, ki mete richès sa a pou nou nan sak yo. Mwen te resevwa premye lajan an. Lèfini, li mennen Simeyon vin jwenn yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 24, text = "Chèf domestik la mennen mesye yo lakay Jozèf. Li ba yo dlo pou yo lave pye yo, li bay bourik yo manje.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 25, text = "Mesye yo menm pare kado yo pou lè Jozèf va vin jwenn yo midi, paske yo te vin konnen yo tapral manje avè l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 26, text = "Lè Jozèf antre lakay li, yo pote kado yo ba li, yo bese tèt yo jouk atè devan li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 27, text = "Jozèf mande yo kouman yo ye. Apre sa, li di yo: -Granmoun nou te pale m' lan, papa nou an, ban m' nouvèl li non? Li la toujou? Li byen?", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 28, text = "Yo reponn li: -Granmoun lan la wi, l'ap debat. Li byen mèsi. Yo tonbe ajenou, yo bese tèt yo jouk atè devan li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 29, text = "Lè Jozèf fè sa li wè Benjamen, frè menm manman menm papa avè l' la, li di: -Eske se ti frè nou an sa, ti frè nou t'ap pale m' lan? Bondye beni ou, pitit mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 30, text = "Lè sa a, Jozèf kouri soti byen vit, paske kè l' t'ap fè l' mal pou frè l' yo. Dlo vin nan je l', li antre nan chanm li, li kriye kont li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 31, text = "Apre sa, li lave figi l', li soti, li kenbe pou li pa kriye ankò, epi li bay lòd sèvi manje a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 32, text = "Yo te sèvi yon tab apa pou Jozèf, yon tab apa pou frè l' yo ak yon lòt tab apa pou moun peyi Lejip ki t'ap manje ansanm ak yo tou, paske pou moun peyi Lejip yo, se ta yon wont pou yo chita manje sou menm tab ak ebre yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 33, text = "Frè Jozèf yo te chita anfas li. Yo te mete yo chita dapre laj yo, depi pi gran an jouk pi piti. Lè yo wè sa, yo te sezi, yonn gade lòt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 43, verseNumber = 34, text = "Jozèf te fè yo pran manje sou tab li pote ba yo. Benjamen te resevwa senk fwa plis pase lòt yo. Yo manje, yo bwè, yo fete ansanm avè l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 1, text = "Apre sa, Jozèf bay chèf domestik la lòd sa a: -Plen sak mesye yo manje mezi yo ka pote. Mete lajan chak moun nan bouch sak yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 2, text = "W'a pran gwo gode m' lan, gode an ajan an, w'a mete l' nan bouch sak pi piti a ansanm ak tout lajan l' lan. Chèf domestik la fè sa Jozèf te di l' fè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 3, text = "Nan denmen maten, byen bonè, yo voye mesye yo al fè wout yo ak tout bourik yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 4, text = "Yo te fin kite lavil la dèyè, men yo pa t' pi lwen pase sa, lè Jozèf di domestik li a: -Leve, kouri dèyè mesye yo. Lè w'a trape yo, w'a di yo: Poukisa nou aji mal konsa ak moun ki fè nou byen?", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 5, text = "Poukisa nou pran gwo gode mèt mwen an? Se ladan l' li bwè, se ak li li sèvi pou l' konnen sa ki pral pase. Sa nou fè a pa bon menm.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 6, text = "Lè domestik la trape yo, li repete tout sa mèt li a te di l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 7, text = "Men yo reponn: -Men msye, nou pa konprann sa w'ap di la a. pou n' ta fè bagay konsa? Mande Bondye padon!", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 8, text = "Gade, lajan nou te jwenn premye fwa a nan bouch sak nou yo, nou pote l' tounen ba ou soti peyi Kanaran. Ki jan ou vle wè pou nou ta vòlò ajan osinon lò kay mèt la?", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 9, text = "Si ou jwenn gwo gode a nan men yonn nan nou, se pou moun sa a mouri. Nou menm lòt yo, se pou yo fè nou tounen esklav.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 10, text = "Domestik la di: -Dakò. Men, si yo jwenn gode a nan men yonn nan nou, se moun sa a m'ap pran pou sèvi m' esklav. Lòt yo lib, yo mèt ale.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 11, text = "La menm, yo prese mete sak yo atè, chak moun louvri sak yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 12, text = "Chèf domestik Jozèf la pran fouye sak yo yonn apre lòt. Li konmanse ak sak pi gran an pou l' fini ak sak pi piti a. Yo jwenn gode a nan sak Benjamen an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 13, text = "Sa ou tande a, yon sèl lapenn pran mesye yo, yo chire rad sou yo. Chak moun chaje bourik yo ankò, yo tounen lavil.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 14, text = "Lè Jida ak frè l' yo rive lakay Jozèf, Jozèf te la toujou. Yo bese tèt yo jouk atè devan li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 15, text = "Jozèf di yo: -Kisa nou fè konsa? Eske nou pa konnen yon nonm tankou mwen gen pouvwa pou m' wè tout sa ki pral rive?", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 16, text = "Jida reponn li: -Mèt, nou pa konn sa pou nou di. Nou pa ka pale. Pa gen savon pou lave nou devan ou. Se Bondye menm ki fè ou dekouvri nou. Mèt, se poutèt sa se pa sèlman moun ki te gen gode a nan men l' lan ki esklav ou, se nou tout ki esklav ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 17, text = "Men Jozèf di: -Mande Bondye padon! Mwen pa ka fè sa. Moun ki te gen gode a, se li menm sèlman k'ap rete pou sèvi m' esklav. Lòt yo mèt tounen lakay papa yo ak kè poze jan yo te vini an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 18, text = "Lè sa a, Jida pwoche bò kote Jozèf, li di l' konsa: -Tanpri, mèt. Kite m' di ou yon ti pawòl. Ou pa bezwen fache sou mwen. Mwen konnen ki di ou menm di farawon an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 19, text = "Mèt, ou te mande nou èske papa nou la, èske nou gen lòt frè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 20, text = "Nou te reponn ou: Wi, nou gen yon papa ki fin vye granmoun ak yon ti frè, pitit papa nou te fè nan vyeyès li. Ti bway la te gen yon lòt frè menm manman avè l'. Men, li mouri. Nan de pitit manman l' yo, se li menm ase ki rete. Lèfini papa nou renmen l' anpil.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 21, text = "Ou te mande nou pou nou mennen l' isit la pou ou te ka wè l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 22, text = "Nou te reponn ou, mèt, ti bway la pa t' ka kite papa l'. Si li kite l', chagren va touye papa a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 23, text = "Men, ou te kenbe pawòl ou pi rèd, ou te di nou si ti frè nou an pa vini ak nou, nou pa bezwen parèt devan ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 24, text = "Lè nou tounen kay papa nou, nou rakonte l' tout sa ou te di nou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 25, text = "Apre sa, papa di nou: Tounen al achte manje pou mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 26, text = "Nou di l': Non, papa. Nou pa ka desann paske si ti frè nou an pa ale ak nou, nou p'ap ka parèt devan chèf la. Men, si ou dakò pou ti frè nou an ale ak nou, n'a desann.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 27, text = "Lè sa a, papa nou di: Nou konnen madanm mwen te fè de sèl pitit gason pou mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 28, text = "Gen yonn ki pati kite m'. Mwen kwè se bèt nan bwa ki dwe devore l', paske mwen pa janm wè l' jouk koulye a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 29, text = "Jòdi a, si nou pran sa a nan men m', si yon malè rive l', avèk tout laj sa ki sou tèt mwen an, mwen p'ap ka sipòte lapenn sa a, chagren va touye m'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 30, text = "Koulye a atò, mèt, si mwen tounen al jwenn papa m' san pitit gason l' sa a, ki de je nan tèt li,", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 31, text = "kou la gade li wè pitit li a pa la, l'ap mouri. Se nou menm ki va lakòz lapenn sa a k'ap twòp pou granmoun lan. Papa nou va mouri sou kont nou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 32, text = "Wi, se mwen menm ki te bay papa m' garanti m'ap tounen ak pitit la. Mwen te di l': Si m' pa mennen l' tounen ba li, se mwen menm k'ap pote fòt la devan l' jouk jou mwen mouri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 33, text = "Se poutèt sa, mèt, tanpri, kite ti bway la ale avèk frè l' yo, kite m' pran plas li. Gade m' pou esklav ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 44, verseNumber = 34, text = "Mwen pa konnen ki pye pou m' ta mete devan pou m' tounen kay papa m' san ti gason an pa avèk nou. Mwen pa ta vle wè lapenn sa a tonbe sou papa m'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 1, text = "Jozèf pa t' kapab kenbe ankò devan tout moun ki t'ap sèvi l' yo. Li di byen fò: -Fè tout moun soti. Se konsa, pesonn pa t' la avèk Jozèf lè li fè frè l' yo rekonèt li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 2, text = "Li te pran kriye byen fò, tèlman fò moun peyi Lejip yo te tande l'. Bri a te rive jouk lakay farawon an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 3, text = "Jozèf di frè l' yo: -Se mwen menm Jozèf. Eske papa m' vivan toujou? Men frè l' yo pa t' kapab reponn li paske yo te boulvèse lè yo wè l' devan yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 4, text = "Jozèf di frè l' yo: -Pwoche vin pi pre m'. Yo pwoche, li di yo: -Se mwen menm Jozèf wi, frè nou an. Se mwen menm wi nou te vann bay moun ki tapral peyi Lejip la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 5, text = "Men koulye a, nou pa bezwen boulvèse. Nou pa bezwen règrèt nou te vann mwen pou yo mennen m' isit la. Se Bondye ki te voye m' devan pou m' te ka sove lavi nou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 6, text = "Sa fè dezan depi grangou tonbe sou peyi a. Men, p'ap gen mwayen travay latè ni fè rekòt pou senk lanne ankò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 7, text = "Bondye te voye m' vini devan pou ras nou an pa t' fini nan peyi a, pou m' te ka sove lavi nou, pou nou pa mouri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 8, text = "Nou wè. Se pa nou menm ki te voye m' isit la, men se Bondye. Se Bondye menm ki mete m' sèvi yon papa pou farawon an. Mwen se chèf nan tout kay li, se mwen k'ap gouvènen tout peyi Lejip la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 9, text = "Koulye a, prese tounen kay papa m'. Al di l': Men sa Jozèf, pitit gason l' lan, voye di l': Bondye mete m' chèf sou tout peyi Lejip la. Desann vin jwenn mwen. Pa mize.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 10, text = "Ou pral rete nan peyi Gochenn. Konsa, w'a toupre m', ou menm ansanm ak pitit ou yo, pitit pitit ou yo, mouton ou yo, bèf ou yo ak tout sa ou genyen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 11, text = "Lè wa Gochenn, m'a pran swen ou, paske grangou a la pou senk lanne ankò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 12, text = "Koulye a, nou wè, pa vre. Benjamen, frè m' lan, wè tout se mwen menm menm Jozèf k'ap pale ak nou an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 13, text = "Fè papa m' konnen jan moun respekte m' isit nan peyi Lejip. Rakonte l' tou sa nou wè. Prese mennen papa m' desann isit la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 14, text = "Epi li lage kò l' nan bra Benjamen, frè li a, li konmanse kriye ankò. Benjamen tout t'ap kriye sou zepòl li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 15, text = "Apre sa, li bo tout frè li yo, li t'ap kriye toujou. Lèfini, frè l' yo pran pale ak li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 16, text = "Lè moun lakay farawon yo vin konnen frè Jozèf yo te vini, sa te fè farawon an ak chèf li yo kontan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 17, text = "Farawon an di Jozèf konsa: -Pale ak frè ou yo. Di yo men sa pou yo fè: Chaje bèt yo, ale nan peyi Kanaran.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 18, text = "Lè y'a rive, y'a pran papa yo ak tout fanmi yo, y'a tounen vin jwenn mwen. m'a ba yo pi bon tè ki nan peyi Lejip la pou fè jaden. Y'a manje pi bon manje ki gen nan peyi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 19, text = "Ou menm poutèt pa ou, w'a di yo sa pou yo fè. Y'a pran kèk cha nan peyi Lejip la pou timoun yo ak madanm yo. Y'a mennen papa yo vini.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 20, text = "Yo pa bezwen règrèt kite anyen, paske se pi bon bagay nan tout peyi Lejip la m'ap ba yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 21, text = "Se sa menm pitit Izrayèl yo te fè. Jozèf ba yo kèk cha jan farawon an te ba li lòd la. Li ba yo pwovizyon pou fè vwayaj la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 22, text = "Li ba yo chak yon rad tout nèf. Men, li bay Benjamen twasan (300) pyès lajan ak senk rad nèf.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 23, text = "Apre sa, li pran dis mal bourik chaje ak pi bon bagay ki te nan peyi Lejip la, dis fenmèl bourik chaje ak ble ak pen ak tout kalite lòt pwovizyon ankò, li voye bay papa l' pou l' ka fè vwayaj la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 24, text = "Lè l'ap voye frè l' yo pati, li di yo: -Piga nou chache kont yonn ak lòt nan chemen an, tande.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 25, text = "Yo kite peyi Lejip, yo rive Kanaran lakay Jakòb, papa yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 26, text = "Yo di l': -Papa, Jozèf la toujou wi. Se li menm k'ap gouvènen peyi Lejip la wi. Men, Jakòb rete tout frèt, paske li pa t' kwè yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 27, text = "Men, lè yo rakonte l' tout sa Jozèf te di yo, lè li wè cha Jozèf te voye pou l' te ka vwayaje a, Jakòb gen yon sèl kontantman ki pran l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 45, verseNumber = 28, text = "Li di yo: -Se kont. Jozèf, pitit mwen an, vivan toujou. Fòk m ale pou m' ka wè l' anvan m' mouri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 1, text = "Izrayèl pati avèk tout sa li te genyen. li al Bècheba, li touye bèt, li ofri yo bay Bondye Izarak, papa li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 2, text = "Jou lannwit sa a, Bondye pale ak Izrayèl nan rèv, li di l': -Jakòb! Jakòb! Jakòb reponn: -Men mwen wi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 3, text = "Bondye di li: -Mwen se Bondye, Bondye papa ou la. Ou pa bezwen pè desann ale nan peyi Lejip paske m'ap fè pitit pitit ou yo tounen yon gwo pèp laba a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 4, text = "M'ap desann avè ou nan peyi Lejip, m'ap fè pitit pitit ou yo tounen isit la ankò. Se Jozèf ki va fèmen je ou lè wa mouri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 5, text = "Jakòb pati, li kite Bècheba. Pitit Izrayèl yo pran Jakòb, papa yo, ansanm ak timoun yo ak madanm yo, yo fè yo moute sou cha farawon an te voye pou yo vwayaje a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 6, text = "Yo pran tout bèt ak tout byen yo te fè nan peyi Kanaran an. Yo desann nan peyi Lejip. Yo mennen Jakòb desann nan peyi Lejip ak tout pitit pitit li yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 7, text = "Jakòb pran pitit gason l' yo ak pitit fi l' yo, pitit pitit li yo, fi kou gason, li desann nan peyi Lejip ak yo tout.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 8, text = "Men non pitit Izrayèl yo ansanm ak pitit pitit yo ki te desann nan peyi Lejip: Jakòb ak pitit gason l' yo. Premye gason an te rele Woubenn.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 9, text = "Men non pitit Woubenn yo: Enòk, Palou, Ezwon ak Kami.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 10, text = "Men non pitit Simeyon yo: Jemouyèl, Jamen, Orad, Jaken, Zoka ak Sayil. Li te fè dènye sa a ak yon fanm peyi Kanaran.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 11, text = "Men non pitit gason Levi yo: Gèchon, Keyat ak Merari.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 12, text = "Men non pitit gason Jida yo: Er, Onan, Chela, Perèz ak Zerak. Men Er ak Onan te mouri nan peyi Kanaran. Perèz te gen de pitit gason: Ezwon ak Amoul.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 13, text = "Men non pitit Isaka yo: Tola, Pouva, Jòb ak Chimwon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 14, text = "Men non pitit Zabilon yo: Serèd, Elon ak Jaleyèl.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 15, text = "Se pitit sa yo Leya te fè pou Jakòb lè yo te Mezopotami. Leya te fè yon fi tout yo te rele Dena. Avèk pitit pitit yo, sa te fè antou tranntwa gason ak yon fi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 16, text = "Men non pitit gason Gad yo: Zifjon, Agi, Chouni, Ezbon, Eri, Awodi ak Areyèli.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 17, text = "Men non pitit gason Asè yo: Jimna, Jichva, Jichvi epi Beria. Yo te gen yon sè ki te rele Serak. Beria te gen de pitit gason: Ebè ak Malkyèl.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 18, text = "Se pitit gason sa yo Zilpa te fè pou Jakòb. Zilpa sa a, se te sèvant Laban te bay Leya, pitit fi li a. Avèk pitit pitit yo, sa te fè antou sèz moun.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 19, text = "Men non pitit gason Rachèl, madan Jakòb: Jozèf ak Benjamen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 20, text = "Pandan Jozèf te nan peyi Lejip, Asnat, pitit fi Potifera, prèt lavil On an, te fè Manase ak Efrayim pou li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 21, text = "Men non pitit Benjamen yo: Bela, Bekè, Achbèl, Gera, Naaman, Ei, Wòch, Moupen, Oupim epi Ad.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 22, text = "Se pitit gason sa yo Rachèl te fè pou Jakòb. Avèk pitit pitit yo, sa te fè antou katòz moun.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 23, text = "Men non pitit gason Dann lan: Ouchim.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 24, text = "Men non pitit gason Neftali yo: Jazeyèl, Gouni, Jezè epi Chilèm.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 25, text = "Se pitit gason sa yo Bila te fè pou Jakòb. Bila sa a, se te sèvant Laban te bay Rachèl, pitit fi li a. Avèk pitit pitit yo, sa te fè antou sèt moun.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 26, text = "Antou sa te fè swasannsis moun, pitit ak pitit pitit ki te desann nan peyi Lejip ansanm ak Jakòb, san konte madanm pitit li yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 27, text = "Avèk Jozèf ki te gen tan fè de pitit nan peyi Lejip, sa te fè antou swasanndis moun laras Jakòb ki te vin nan peyi Lejip.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 28, text = "Izrayèl te voye Jida devan al mande Jozèf pou l' vin jwenn li Gochenn.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 29, text = "Jozèf fè pare cha li a, li moute, li al Gochenn, li al kontre papa l'. Rive Jozèf rive devan papa l', li lage kò l' nan bra l', li pase yon bon tan ap kriye sou zepòl li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 30, text = "Izrayèl di Jozèf konsa: -Koulye a, mwen wè figi ou, mwen konnen ou vivan toujou, mwen mèt mouri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 31, text = "Epi Jozèf di frè l' yo ak tout fanmi papa l' yo: -Mwen pral avèti wa a. Mwen pral di l': men frè m' yo ak tout fanmi papa m' yo ki t'ap viv nan peyi Kanaran vin jwenn mwen isit la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 32, text = "Se gadò mouton yo ye. Se bèt yo konn gade. Yo mennen tout mouton yo ak tout bèf yo ansanm ak tout sa yo genyen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 33, text = "Lè farawon an va rele nou pou mande nou ki metye nou,", bookId = 1),
        Verse(book = "Jenèz", chapter = 46, verseNumber = 34, text = "n'a reponn li: Monwa, depi nou tout piti jouk koulye a, se bèt n'ap gade, tankou tout zansèt nou yo. Konsa, nou ka rete nan peyi Gochenn lan. Li te di yo sa paske moun peyi Lejip yo pa ka sipòte wè moun k'ap gade bèt viv nan mitan yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 1, text = "Apre sa, Jozèf al avèti farawon an li di l': -Men papa m' ak frè m' yo rive soti nan peyi Kanaran, yo vini ak mouton yo, bèf yo ak tout sa yo genyen. Koulye a menm yo Gochenn.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 2, text = "Jozèf te pran senk nan frè l' yo avèk li, li prezante yo bay farawon an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 3, text = "Farawon an di yo konsa: -Ki metye nou? Yo reponn li: -Metye nou se gade bèt tankou zansèt nou yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 4, text = "Apre sa, yo di farawon an: -Nou vin pou nou ka rete nan peyi a, paske pa gen manje ankò nan peyi nou pou bèt yo manje. Lèfini, grangou a rèd anpil nan peyi Kanaran. Tanpri, ban nou pèmisyon pou nou rete nan peyi Gochenn lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 5, text = "Farawon an di Jozèf: -Men papa ou ak frè ou yo vin jwenn ou isit la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 6, text = "tout peyi Lejip la la devan ou. Chwazi pi bon tè nan peyi a, ba yo l' pou rete. Yo mèt rete sou tè Gochenn lan. Epi, si ou konnen gen nan mitan yo moun ki kapab pran swen bèt pa m' yo, ou mèt ba yo bèt mwen yo gade.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 7, text = "Apre sa, Jozèf fè papa l' vini, li prezante l' bay farawon an. Lè Jakòb fin di farawon an bonjou,", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 8, text = "farawon an mande l': -Ki laj ou?", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 9, text = "Jakòb reponn li: -Mwen gen santrantan (130 an) depi m'ap moute desann sou latè. Men, mwen poko prèt pou m' rive laj zansèt mwen yo te rive lè yo t'ap fè moute desann pa yo. Mwen pa gen anpil laj, se vre. Men, mwen pa manke bat mizè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 10, text = "Jakòb di farawon an orevwa, epi li ale.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 11, text = "Jozèf fè papa l' ak frè l' yo rete nan peyi Lejip. Li ba yo tè bò lavil Ranmsès, jan farawon an te mande l' la. Li ba yo yon bon tè nan peyi a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 12, text = "Jozèf te bay papa l', frè l' yo ak tout fanmi yo kantite manje yo te bezwen pou mezi timoun yo te genyen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 13, text = "Grangou a te rèd anpil toupatou. pa t' gen manje ankò. Moun peyi Lejip ak moun peyi Kanaran yo t'ap fin deperi anba grangou a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 14, text = "Jozèf te fin ranmase dènye lajan moun peyi Lejip ak moun peyi Kanaran te genyen nan vann yo ble. Li pote tout lajan an lakay farawon an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 15, text = "Lè tout lajan moun yo fini nan peyi Lejip ak nan peyi Kanaran, tout moun peyi Lejip yo vin jwenn Jozèf, yo di l': -Ban nou manje non, souple. Pa kite nou mouri. Fè kichòy pou nou, nou pa gen lajan ankò.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 16, text = "Jozèf di yo: -Si nou pa gen lajan, mennen bèt nou yo vini, n'a boukante yo pou manje.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 17, text = "Se konsa, yo mennen bèt yo bay Jozèf pou fè boukantay. Li ba yo manje, yo ba li chwal, bèf, mouton, bourik. Pandan tout lanne a, li boukante manje ak yo pou valè bèt yo te genyen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 18, text = "Apre lanne a fin pase, yo tounen bò kote Jozèf ankò. Yo di li: -Nou p'ap kapab kache ou sa, mèt. Lajan nou fini nèt. Nou deja ba ou tout bèt nou te genyen. Koulye a, mèt, se tè nou yo ak pwòp tèt nou ase ki rete pou n' ba ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 19, text = "Pa kite nou mouri. Fè kichòy pou nou! Pa kite nou pèdi tè nou yo. Fè pri pou nou menm ansanm ak tout tè nou yo. N'ap tounen esklav farawon an. Tè nou yo va pou li tou. Men, ban nou plan pou nou simen nan jaden nou yo pou nou pa mouri, pou tè a pa fin tounen savann.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 20, text = "Se konsa Jozèf achte tout tè Lejip la pou farawon an. tout moun peyi Lejip yo te vann li tè yo paske grangou a t'ap fini ak yo. tout peyi a vini pou farawon an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 21, text = "Jozèf fè tout moun toupatou nan peyi a tounen esklav farawon an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 22, text = "Se te prèt yo ase li pa t' manyen. Prèt yo pa t' bezwen tè pou yo manje, paske, dapre yon lwa ki gen nan peyi a, se farawon an menm ki te toujou peye yo. Se ak lajan sa a yo te viv.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 23, text = "Jozèf di pèp la: -Jòdi a, mwen achte nou ansanm ak tout tè nou yo pou farawon an. Men grenn m'ap ban nou pou nou plante nan jaden nou yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 24, text = "Lè sezon rekòt la va rive, n'a bay farawon an yon senkyèm (1/5) nan tou sa nou rekòlte. Rès la va pou nou, pou nou plante nan jaden nou yo, pou nou manje nou menm ansanm ak pitit nou yo ak tout moun ki lakay nou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 25, text = "Yo reponn li: -Ou sove lavi nou! Sèl sa nou mande ou, se pou ou aji byen ak nou. N'ap rete esklav farawon an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 26, text = "Se konsa, Jozèf te pase yon regleman pou tout peyi Lejip la: dapre regleman sa a ki la jouk koulye a toujou, se pou yo bay farawon an yon senkyèm sou chak rekòt. Se sèlman tè prèt yo ki pa t' pou farawon an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 27, text = "Moun Izrayèl yo te rete nan peyi Lejip sou tè Gochenn lan. Yo vin gen anpil byen. Yo te fè anpil anpil pitit. Yo t'ap fè toujou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 28, text = "Jakòb pase disèt lanne nan peyi Lejip. Li te rive gen sankarannsèt (147) lanne sou tèt li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 29, text = "Lè sa a, Izrayèl vin wè li pa t' gen lontan pou l' viv ankò. Li fè rele Jozèf, pitit li a, li di l' konsa: -Si ou renmen m' vre, tanpri, fè m' sèman. Mete men ou nan fant janm mwen, pwomèt mwen w'ap kenbe pawòl ou, ou p'ap janm trayi m'. Tanpri, pa antere m' nan peyi Lejip.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 30, text = "Mwen vle pou yo antere m' menm kote ak zansèt mwen yo, lè m aval jwenn fanmi mwen yo ki mouri deja a. Se pou ou pran kadav mwen, pote l' soti peyi Lejip, al antere l' nan kavo fanmi m' yo. Jozèf reponn li: -m'a fè jan ou mande m' lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 47, verseNumber = 31, text = "Men, Jakòb di Jozèf konsa: -Fè m' sèman w'ap fè sa pou mwen! Jozèf sèmante ba li. Apre sa, Izrayèl bese kouche nan kabann li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 1, text = "Kèk tan apre sa, yo vin fè Jozèf konnen papa l' malad. Jozèf pran Manase ak Efrayim, de pitit gason l' yo, ak li, li ale wè Jakòb.", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 2, text = "Yo vin di Jakòb: -Men Jozèf, pitit ou, vin wè ou. Izrayèl ranmase dènye ti rès fòs li te genyen an, li leve chita sou kabann lan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 3, text = "Jakòb di Jozèf: -Bondye ki gen tout pouvwa a te parèt devan mwen yon kote yo rele Louz, nan peyi Kanaran. Li beni m'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 4, text = "Li di m' konsa: M'ap ba ou anpil pitit ak pitit pitit. M'ap fè yo tounen anpil nasyon. Ou wè tè sa a? M'ap bay pitit pitit ou yo li pou li rele yo pa yo pou tout tan.", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 5, text = "Bon. De pitit gason ou te fè nan peyi Lejip anvan m' te vin jwenn ou isit la a, se pitit mwen yo pral ye. Wi, Efrayim ak Manase ap pou mwen tankou Woubenn ak Simeyon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 6, text = "Men, tout pitit ou va fè apre yo, se pitit ou y'ap ye. Y'a pote non gran frè yo pou yo ka jwenn pa yo nan byen m' yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 7, text = "Lè m' t'ap tounen soti nan peyi Mezopotami an, Rachèl, manman ou, te mouri nan men mwen. Li mouri sou wout pou ale peyi Kanaran, pa twò lwen lavil Efrata. Mwen antere l' la sou wout Efrata a. Se Efrata sa a yo rele Betleyèm lan tou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 8, text = "Lè Izrayèl wè pitit Jozèf yo, li mande: -Ki timoun sa yo?", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 9, text = "Jozèf reponn li: -Se pitit gason Bondye te ban mwen antan mwen isit la wi. Izrayèl di li: -Tanpri, fè yo pwoche pi pre m' pou m' ka beni yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 10, text = "Izrayèl te fin granmoun, je l' pa t' bon menm. Li pa t' kapab wè ankò. Jozèf fè pitit li yo pwoche bò kote papa l'. Jakòb pran yo, li bo yo, li pase bra l' nan kou yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 11, text = "Izrayèl di Jozèf konsa: -Mwen pa t' gen espwa wè figi ou ankò, men Bondye fè m' wè ata pitit ou yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 12, text = "Jozèf wete timoun yo sou jenou Izrayèl, epi li bese tèt li jouk atè devan papa l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 13, text = "Li pran timoun yo, Efrayim nan men dwat li ak Manase nan men gòch li. Konsa, Efrayim vin sou bò gòch Izrayèl, Manase menm sou bò dwat li. Li fè yo pwoche vin jwenn papa l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 14, text = "Men, Izrayèl kwaze men l' lè l'ap lonje yo, li mete men dwat li sou tèt Efrayim ki te pi piti a, li mete men gòch li sou tèt Manase ki te pi gran an. Izrayèl te konnen sa l' t'ap fè lè l' te fè sa.", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 15, text = "Li beni Jozèf, li di l': -Se pou Bondye zansèt mwen yo, Bondye Abraram ak Izarak te sèvi tout lavi yo a, beni timoun sa yo. Se pou Bondye ki te pran swen mwen depi lè m' te fèt jouk jòdi a beni timoun yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 16, text = "Se pou zanj Bondye ki te delivre m' anba tout move pa beni timoun yo. Se pou yo pote non mwen ak non zansèt mwen yo, Abraram ak Izarak. Se pou yo fè anpil pitit pitit, se pou yo peple sou tè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 17, text = "Men Jozèf pa t' kontan lè li wè papa l' te mete men dwat li sou tèt Efrayim. Li kenbe men papa l' pou l' wete l' sou tèt Efrayim pou l' mete l' pito sou tèt Manase.", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 18, text = "Epi li di papa l': -Se pa konsa, papa. Men pi gran an bò isit. Mete men dwat ou sou tèt li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 19, text = "Men, papa a derefize. Li di l': -Mwen konnen, pitit mwen, mwen konnen. Manase tout ap vin yon pèp. Li menm tout l'ap grannèg. Men, ti frè l' la pral pi grannèg pase l'. Pitit li yo pral vin anpil nasyon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 20, text = "Jou sa a, li beni yo, li di: -Nan peyi pitit pitit Izrayèl yo, lè y'ap bay benediksyon, y'a nonmen non nou. y'a mande pou Bondye beni yon moun menm jan li te beni Efrayim ak Manase. Se konsa li te mete Efrayim anvan Manase.", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 21, text = "Apre sa, Izrayèl di Jozèf: -Gade. Mwen pral mouri. Men Bondye ap la avèk ou. La fè ou tounen nan peyi zansèt ou yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 48, verseNumber = 22, text = "Se pa pou lòt moun nan frè ou yo, se pou ou m'ap kite moso tè Sichèm lan. Se pòsyon tè sa a mwen te pran nan men moun Amori yo anba gwo goumen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 1, text = "Jakòb fè rele pitit gason l' yo, li di yo: -Sanble non. M'ap fè nou konnen sa ki pral rive nou nan jou k'ap vini yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 2, text = "Sanble, vin koute non, pitit Jakòb yo! vin koute sa Izrayèl, papa nou, pral di nou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 3, text = "Ou menm, Woubenn, premye pitit gason mwen, ou se fòs mwen, premye pitit mwen fè. Nan tout pitit mwen yo, se ou ki gen plis fòs, se ou ki pi gwonèg.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 4, text = "Ou tankou yon larivyè k'ap desann. Men, se pa ou k'ap alatèt, paske ou kouche ak yon madanm papa ou. Ou moute sou kabann mwen, ou fè sa ou pa t' dwe fè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 5, text = "Simeyon ak Levi se menm moun, se pwason kraze nan bouyon! Yo sèvi ak zam yo pou fè mechanste.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 6, text = "Mwen p'ap patisipe nan konplo yo. Mwen p'ap la avèk yo nan reyinyon yo. Paske lè yo ankòlè, yo touye moun. Yo koupe jarèt towo bèf pou dan ri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 7, text = "Madichon pou yo lè yo move paske yo san manman! M'ap fè yo rete toupatou nan peyi Jakòb la. M'ap gaye yo nan tout peyi Izrayèl la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 8, text = "Ou menm, Jida, frè ou yo ap fè lwanj ou. W'ap kenbe lènmi ou yo dèyè kou. Pitit papa ou yo ap bese tèt devan ou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 9, text = "Jida, se yon jenn ti lyon. Lè ou fin fè ravaj, pitit mwen, ou tounen tounen ou. Ou kwoupi, ou kache kò ou tankou yon jenn ti lyon, tankou yon fenmèl lyon. Ki moun ki ka deranje ou?", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 10, text = "Yo p'ap ka wete kòmandman an nan men Jida. Non. Baton kòmandman an p'ap soti nan mitan janm li, jouk tan moun tout pèp sou latè pral obeyi a va vini.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 11, text = "L'ap mare ti bourik li a nan yon pye rezen, l'ap mare pitit manman bourik li a nan pi bon pye rezen an. L'ap lave rad li nan diven, l'ap lave varèz li nan diven wouj kou san.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 12, text = "Je l' wouj ak diven. Dan l' blan ak lèt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 13, text = "Zabilon pral rete bò lanmè. Batiman yo va jwenn bon pò sou rivaj li yo. Limit peyi l' la ap rive jouk Sidon.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 14, text = "Isaka, se yon bon bourik chay. Li kouche nan mitan de bò sakpay.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 15, text = "Li wè jan kote li poze kò l' la nan gou li, li wè jan peyi a bèl. Li pare do l' pou l' pote chay li. Li tounen esklav pou l' travay di.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 16, text = "Dann ap yon chèf pou pèp li, tankou yon branch nan fanmi Izrayèl.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 17, text = "Dann ap tankou yon sèpan bò gran chemen an, yon sèpan mechan sou bò wout la. L'ap mòde chwal yo nan talon pou l' fè kavalye yo tonbe sou tèt.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 18, text = "O Seyè, m'ap tann ou vin sove mwen!", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 19, text = "Ou menm, Gad, yon bann vòlò ap vin tonbe sou ou. Men, w'ap kouri dèyè yo, se ou k'ap mete men sou yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 20, text = "Peyi Asè a ap bay bon manje k'ap bay fòs. L'ap donnen manje ki gou nan bouch wa yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 21, text = "Neftali, se yon fenmèl kabrit ki lage. L'ap fè bèl ti pitit.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 22, text = "Jozèf se boujon yon pye rezen ki konn donnen, li soti nan yon pye rezen bò sous dlo ki donnen byen. Branch li yo moute sou tout miray la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 23, text = "Y'ap chache l' kont, y'ap voye wòch sou li. Moun k'ap voye flèch yo tounen yon pèsekisyon pou li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 24, text = "Men, banza pa li a rete fèm, ponyèt li pa febli, gremesi pouvwa Bondye Jakòb la, Bondye ki gadò pèp Izrayèl la. Se li ki tout pwoteksyon yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 25, text = "Sa soti nan Bondye papa ou la k'ap ede ou, nan Bondye ki gen tout pouvwa a k'ap beni ou avèk benediksyon lapli ki soti anwo nan syèl la, avèk benediksyon sous dlo k'ap soti anba tè a, avèk benediksyon ki soti nan tete ak nan vant manman.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 26, text = "Benediksyon papa ou yo pi plis pase benediksyon mòn ki la pou tout tan yo. Se pou benediksyon sa yo tonbe sou tèt Jozèf, sou tèt moun Bondye te chwazi nan mitan tout frè l' yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 27, text = "Benjamen, se yon bèt nan bwa devoran. Nan maten, li manje bèt li kenbe a. Nan aswè, l'ap separe toujou sa l' te pran yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 28, text = "Men douz branch fanmi Izrayèl yo. Men sa papa yo te di yo. Li beni yo, li bay chak moun benediksyon pa yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 29, text = "Apre sa, Jakòb ba yo lòd sa a: -Mwen menm, mwen pral jwenn fanmi m' yo ki mouri deja. Antere m' menm kote ak zansèt mwen yo nan twou wòch ki nan jaden Efwon, moun Et la,", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 30, text = "nan twou wòch ki nan jaden Makpela a, anfas Manmre, nan peyi Kanaran. Se Abraram ki te achte twou wòch sa a ak tout jaden an nan men Efwon, moun Et la, pou sèvi l' simityè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 31, text = "Se la yo te antere Abraram ak Sara, madanm li. Se la yo te antere Izarak ak Rebeka, madanm li. Se la tout mwen te antere Leya.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 32, text = "Se nan men mesye Et yo nou te achte jaden an ak tout twou wòch ki sou li a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 49, verseNumber = 33, text = "Lè Jakòb fin pale konsa ak pitit gason l' yo, li lonje kò l' sou kabann lan, li mouri, li al jwenn fanmi li yo ki te mouri deja.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 1, text = "Jozèf lage kò l' sou papa l', li kriye kont li, li bo l' nan figi.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 2, text = "Apre sa, Jozèf rele dòktè ki t'ap sèvi l' yo, li fè yo pare kadav la. Se sa menm dòktè yo fè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 3, text = "Yo pran karant jou pou pare kadav la jan yo konn fè l' la. Apre sa, moun peyi Lejip yo pase swasanndi jou ap kriye pou li.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 4, text = "Lè tout swasanndi jou yo fin pase, jou pou antèman an rive. Jozèf pale ak moun lakay farawon yo, li di yo konsa: -Tanpri souple, rann mwen sèvis sa a. Pote komisyon sa a bay farawon an pou mwen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 5, text = "Di l' pou mwen: Anvan papa m' te mouri li te fè m' sèmante pou m' te antere l' nan kavo li te fè pare pou li nan peyi Kanaran. Tanpri, kite m' moute al antere papa m'. Apre sa, m'a tounen.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 6, text = "Farawon an voye reponn li: -Ou mèt al antere papa ou, jan ou te sèmante ba li a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 7, text = "Se konsa Jozèf moute al antere papa l'. tout moun lakay farawon yo, tout chèf ak tout notab peyi Lejip yo ale ak li,", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 8, text = "ansanm ak tout fanmi Jozèf yo, frè l' yo, ak tout fanmi papa l' yo. Men yo te kite tout timoun piti yo Gochenn ansanm ak bèt yo, mouton, kabrit ak bèf.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 9, text = "Te gen anpil cha ak anpil kavalye sou chwal ki t ale avek li. Kifè pa t' manke moun nan lantèman an.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 10, text = "Lè yo rive nan glasi Atad ki lòt bò larivyè Jouden, kote sòlèy leve a, yo pran rele byen fò. Jozèf te fè yo fè sèvis la pandan sèt jou pou papa l'.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 11, text = "Lè moun peyi Kanaran yo wè sèvis lantèman yo t'ap fè Atad la, yo di: -Ala yon grannèg ki mouri lakay moun peyi Lejip yo papa! Se poutèt sa yo rele glasi ki lòt bò larivyè Jouden an: Glasi lapenn moun peyi Lejip yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 12, text = "Konsa, pitit gason Jakòb yo te fè jan papa yo te ba yo lòd fè a.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 13, text = "Yo pote kadav li nan peyi Kanaran, yo antere l' nan twou wòch ki te nan jaden Makpela a, anfas Manmre. Se jaden sa a Abraram te achte nan men Efwon, moun Et la, pou sèvi l' simityè.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 14, text = "Apre Jozèf fin antere papa l', li tounen Lejip ansanm ak frè l' yo ak tout moun ki te moute avè l' pou lantèman papa l' la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 15, text = "Apre lanmò papa yo, frè Jozèf yo di: -Ou pa janm konnen. Jozèf ka kenbe nou nan kè, li ka fè nou peye tout sa nou te fè l' yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 16, text = "Se konsa yo voye di Jozèf: -Men komisyon papa te ban nou pou ou anvan l' te mouri:", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 17, text = "Men sa n'a di Jozèf pou mwen: Tanpri, padonnen krim frè ou yo te fè ou la. Padonnen peche yo paske yo te fè ou mal anpil. Koulye a atò, tanpri, padonnen mal nou te fè ou la, nou menm k'ap sèvi Bondye papa ou la. Lè Jozèf tande pawòl sa a, li pran kriye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 18, text = "Apre sa, frè l' yo vini yo menm menm, yo bese tèt yo jouk atè devan li, yo di l' konsa: -Men nou pote tèt nou pou nou sèvi ou domestik.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 19, text = "Jozèf di yo: -Nou pa bezwen pè. Mwen pa kapab pran plas Bondye.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 20, text = "Nou te moute konplo pou fè m' mal. Men Bondye fè sa tounen yon byen, pou l' te fè sak rive jòdi a rive, pou l' te ka sove lavi tout kantite moun sa yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 21, text = "Non. Nou pa bezwen pè. M'ap okipe nou, nou menm ansanm ak tout pitit nou yo. Se konsa, Jozèf te pale byen ak frè l' yo, li te di yo pawòl ki te touche kè yo, li remoute kouraj yo.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 22, text = "Jozèf te rete nan peyi Lejip ak tout fanmi papa l' yo. Li te gen sandizan (110 an) lè l' mouri.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 23, text = "Li te gen tan wè pitit ak pitit pitit Efrayim. Se nan men l' pitit Maki yo te fèt. Maki sa a te pitit Manase.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 24, text = "Li di frè l' yo konsa: -Mwen pral mouri. Men mwen sèten Bondye gen pou vin ede nou. L'ap fè nou kite peyi sa a, l'ap fè nou tounen nan peyi li te sèmante l'ap bay Abraram, Izarak ak Jakòb la.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 25, text = "Apre sa, Jozèf fè pitit Izrayèl yo sèmante ba li, li di yo: -Wi, Bondye gen pou vin ede nou. Lè sa a, tanpri, pote zosman m' yo moute ak nou.", bookId = 1),
        Verse(book = "Jenèz", chapter = 50, verseNumber = 26, text = "Lè Jozèf mouri li te gen sandizan (110 an). Yo benyen kadav la, yo pare l' pou l' pa pouri. Yo mete l' nan yon sèkèy byen fèmen nan peyi Lejip.", bookId = 1)
    )
}

